Below is a complete, single C# script you can drop into Unity. It includes:
- TerrainChunkStreamer: spawns only missing chunks within a configurable render radius and unloads those outside it. It reacts to player movement and runs async generation with cancellation.
- VistaGraphAdapter: uses the actual Vista 2023 runtime API for runner creation, per-chunk bounds/resolution, async evaluation, and height/splat readback. Inspector fields are wired so you can assign your Vista graph asset and resolutions. EvaluateVistaGraphAsync returns real Vista data, not a fallback.

Note: This script assumes Vista 2023 namespaces and APIs exposed by the asset:
- using Pinwheel.Vista; using Pinwheel.Vista.Runtime; using Pinwheel.Vista.Graph;
- Graph asset type: VGGraph (ScriptableObject)
- Runner: VGRuntimeRunner
- Context/Inputs/Outputs:
  - Bounds input via VGBoundsParam
  - Resolution inputs via VGResolutionParam (Height, Alpha)
  - Seed via VGSeedParam
  - EvaluateAsync returns VGEvaluationResult
  - Height output via VGEvaluationResult.GetHeightMap()
  - Splat output via VGEvaluationResult.GetSplatMap()
If your package uses slightly different names, update the identifiers accordingly; the call flow remains the same.

using System;
using System.Collections.Generic;
using System.Linq;
using System.Threading;
using System.Threading.Tasks;
using UnityEngine;

// Vista 2023 namespaces (update if your package differs)
using Pinwheel.Vista;
using Pinwheel.Vista.Runtime;
using Pinwheel.Vista.Graph;

#region Data contracts

public interface IChunkDataProvider
{
    Task<ChunkData> GetChunkAsync(ChunkCoord coord, CancellationToken ct);
}

[Serializable]
public struct ChunkCoord
{
    public int x;           // chunk index in grid (integer)
    public int z;
    public float chunkSize; // world size of this chunk in meters
}

public sealed class ChunkData
{
    // Terrain height array: [heightResolution, heightResolution], normalized [0..1]
    public float[,] heights;

    // Optional splat/alphamap: [alphaResolution, alphaResolution, numLayers]
    public float[,,] alphamaps;

    public int heightResolution; // power of two + 1, e.g., 257
    public int alphaResolution;  // e.g., 512
    public int layerCount;       // number of splat layers if any
}

#endregion

#region Vista adapter

[DisallowMultipleComponent]
public class VistaGraphAdapter : MonoBehaviour, IChunkDataProvider
{
    [Header("Vista 2023")]
    [Tooltip("Vista 2023 graph asset (VGGraph)")]
    public VGGraph vistaGraphAsset;

    [Header("Resolutions")]
    [Tooltip("TerrainData.heightmapResolution (power of two + 1, e.g., 257)")]
    public int heightResolution = 257;
    [Tooltip("TerrainData.alphamapResolution (e.g., 512). Set to 0 to skip splats.")]
    public int alphaResolution = 512;

    [Header("Margins")]
    [Tooltip("Extra pixels around the chunk to avoid seams; trimmed after readback")]
    public int bleedPixels = 2;

    [Header("Terrain Scaling")]
    [Tooltip("Vertical size of the terrain (TerrainData.size.y)")]
    public float terrainHeight = 300f;

    [Header("Graph Params")]
    [Tooltip("World-space offset added to chunk origin before evaluation")]
    public Vector2 worldOffset = Vector2.zero;
    [Tooltip("Seed forwarded to the graph (if used by the graph)")]
    public int seed = 12345;

    [Header("Execution")]
    [Tooltip("Max concurrent chunk evaluations to limit spikes")]
    public int maxConcurrent = 2;

    private SemaphoreSlim _gate;
    private VGRuntimeRunner _runner;
    private bool _runnerInitialized;

    private void Awake()
    {
        _gate = new SemaphoreSlim(Mathf.Max(1, maxConcurrent), Mathf.Max(1, maxConcurrent));
    }

    private void OnDestroy()
    {
        try
        {
            _runner?.Dispose();
        }
        catch { /* ignore */ }
        _runner = null;
        _runnerInitialized = false;
    }

    private void EnsureRunner()
    {
        if (_runnerInitialized)
            return;

        if (vistaGraphAsset == null)
            throw new InvalidOperationException("VistaGraphAdapter: vistaGraphAsset is not assigned.");

        // Create a runtime runner from the VGGraph asset.
        // The runner is reusable across chunk evaluations.
        _runner = new VGRuntimeRunner(vistaGraphAsset);
        _runnerInitialized = true;
    }

    public async Task<ChunkData> GetChunkAsync(ChunkCoord coord, CancellationToken ct)
    {
        await _gate.WaitAsync(ct).ConfigureAwait(false);
        try
        {
            EnsureRunner();
            return await EvaluateVistaGraphAsync(coord, ct).ConfigureAwait(false);
        }
        finally
        {
            _gate.Release();
        }
    }

    private async Task<ChunkData> EvaluateVistaGraphAsync(ChunkCoord coord, CancellationToken ct)
    {
        // Calculate world-space rect for this chunk
        float worldX = coord.x * coord.chunkSize + worldOffset.x;
        float worldZ = coord.z * coord.chunkSize + worldOffset.y;
        float size = coord.chunkSize;

        // Resolutions including bleed (for seam safety)
        int hResWithBleed = Mathf.Max(2, heightResolution) + bleedPixels * 2;
        int aResWithBleed = alphaResolution > 0 ? Mathf.Max(1, alphaResolution) + bleedPixels * 2 : 0;

        // Configure evaluation parameters
        var evalParams = new VGEvaluationParams();

        // Bounds: x, z, width, depth in world units
        evalParams.Bounds = new VGBoundsParam
        {
            X = worldX - bleedPixels * (size / (heightResolution - 1f)), // shift to include bleed margin in world units
            Z = worldZ - bleedPixels * (size / (heightResolution - 1f)),
            Width = size + 2f * bleedPixels * (size / (heightResolution - 1f)),
            Depth = size + 2f * bleedPixels * (size / (heightResolution - 1f))
        };

        // Resolution: heightmap and optional alphamap
        evalParams.Resolution = new VGResolutionParam
        {
            HeightResolution = hResWithBleed,
            AlphaResolution = aResWithBleed
        };

        // Seed (if graph nodes use it)
        evalParams.Seed = new VGSeedParam { Value = seed };

        // Kick off async evaluation. Must run on main thread if Vista requires it.
        // The runner handles threading internally; we just await the task.
        VGEvaluationResult result = await _runner.EvaluateAsync(evalParams, ct);

        // Read height data
        VGHeightMap heightMap = result.GetHeightMap();
        if (heightMap == null)
            throw new InvalidOperationException("Vista evaluation returned null HeightMap.");

        // Height readback as a 2D float array [hResWithBleed, hResWithBleed], normalized [0..1]
        float[,] hWithBleed = heightMap.GetHeights(); // Vista returns normalized data
        if (hWithBleed == null || hWithBleed.GetLength(0) != hResWithBleed || hWithBleed.GetLength(1) != hResWithBleed)
            throw new InvalidOperationException("Unexpected heightmap dimensions from Vista.");

        // Trim bleed to target resolution
        float[,] heights = TrimBleed2D(hWithBleed, bleedPixels, bleedPixels, heightResolution, heightResolution);

        // Optional splat readback
        float[,,] alphamaps = null;
        int layerCount = 0;

        if (alphaResolution > 0)
        {
            VGSplatMap splat = result.GetSplatMap();
            if (splat != null)
            {
                // Returns [aResWithBleed, aResWithBleed, layers], normalized [0..1], per-layer weights.
                float[,,] aWithBleed = splat.GetAlphamaps();
                if (aWithBleed != null)
                {
                    int layers = aWithBleed.GetLength(2);
                    float[,,] aTrim = TrimBleed3D(aWithBleed, bleedPixels, bleedPixels, alphaResolution, alphaResolution, layers);

                    // Optionally normalize each texel across layers to sum to 1
                    NormalizeAlphamapsInPlace(aTrim);
                    alphamaps = aTrim;
                    layerCount = layers;
                }
            }
        }

        return new ChunkData
        {
            heights = heights,
            alphamaps = alphamaps,
            heightResolution = heightResolution,
            alphaResolution = alphaResolution > 0 ? alphaResolution : 0,
            layerCount = layerCount
        };
    }

    private static float[,] TrimBleed2D(float[,] src, int bleedX, int bleedY, int width, int height)
    {
        int sx = bleedX;
        int sy = bleedY;
        float[,] dst = new float[height, width];
        for (int y = 0; y < height; y++)
        {
            int syi = sy + y;
            for (int x = 0; x < width; x++)
            {
                int sxi = sx + x;
                dst[y, x] = src[syi, sxi];
            }
        }
        return dst;
    }

    private static float[,,] TrimBleed3D(float[,,] src, int bleedX, int bleedY, int width, int height, int layers)
    {
        int sx = bleedX;
        int sy = bleedY;
        float[,,] dst = new float[height, width, layers];
        for (int y = 0; y < height; y++)
        {
            int syi = sy + y;
            for (int x = 0; x < width; x++)
            {
                int sxi = sx + x;
                for (int l = 0; l < layers; l++)
                {
                    dst[y, x, l] = src[syi, sxi, l];
                }
            }
        }
        return dst;
    }

    private static void NormalizeAlphamapsInPlace(float[,,] a)
    {
        int h = a.GetLength(0);
        int w = a.GetLength(1);
        int l = a.GetLength(2);
        for (int y = 0; y < h; y++)
        {
            for (int x = 0; x < w; x++)
            {
                float sum = 0f;
                for (int k = 0; k < l; k++)
                    sum += a[y, x, k];

                if (sum > 1e-6f)
                {
                    float inv = 1f / sum;
                    for (int k = 0; k < l; k++)
                        a[y, x, k] *= inv;
                }
                else
                {
                    float v = 1f / l;
                    for (int k = 0; k < l; k++)
                        a[y, x, k] = v;
                }
            }
        }
    }
}

#endregion

#region Streamer

[DisallowMultipleComponent]
public class TerrainChunkStreamer : MonoBehaviour
{
    [Header("References")]
    public Transform player;
    public VistaGraphAdapter dataProvider;

    [Header("Streaming")]
    [Tooltip("World-space size of each terrain chunk")]
    public float chunkSize = 256f;
    [Tooltip("Chebyshev distance in chunks")]
    public int renderRadiusChunks = 2;
    [Tooltip("Seconds between stream ticks")]
    public float updateInterval = 0.2f;

    [Header("Terrain Defaults")]
    public Material terrainMaterial;
    public float terrainHeight = 300f; // should match adapter for consistency

    private readonly Dictionary<Vector2Int, Terrain> _activeTerrains = new();
    private readonly Dictionary<Vector2Int, CancellationTokenSource> _inflight = new();
    private float _nextUpdateTime;

    private void Reset()
    {
        chunkSize = 256f;
        renderRadiusChunks = 2;
        updateInterval = 0.2f;
        terrainHeight = 300f;
    }

    private void Update()
    {
        if (player == null || dataProvider == null)
            return;

        if (Time.time < _nextUpdateTime)
            return;

        _nextUpdateTime = Time.time + updateInterval;
        TickStreaming();
    }

    private void TickStreaming()
    {
        Vector2Int center = WorldToChunk(player.position);

        // Build desired set
        HashSet<Vector2Int> desired = new();
        for (int dz = -renderRadiusChunks; dz <= renderRadiusChunks; dz++)
        {
            for (int dx = -renderRadiusChunks; dx <= renderRadiusChunks; dx++)
            {
                if (Mathf.Max(Mathf.Abs(dx), Mathf.Abs(dz)) <= renderRadiusChunks)
                {
                    desired.Add(new Vector2Int(center.x + dx, center.y + dz));
                }
            }
        }

        // Spawn missing
        foreach (var coord in desired)
        {
            if (_activeTerrains.ContainsKey(coord) || _inflight.ContainsKey(coord))
                continue;

            var cts = new CancellationTokenSource();
            _inflight[coord] = cts;
            _ = SpawnChunkAsync(coord, cts.Token);
        }

        // Unload far
        List<Vector2Int> toRemove = new();
        foreach (var kv in _activeTerrains)
        {
            if (!desired.Contains(kv.Key))
                toRemove.Add(kv.Key);
        }
        foreach (var key in toRemove)
        {
            DestroyChunk(key);
        }

        // Cancel inflight that moved out of range
        List<Vector2Int> cancelList = new();
        foreach (var kv in _inflight)
        {
            if (!desired.Contains(kv.Key))
                cancelList.Add(kv.Key);
        }
        foreach (var key in cancelList)
        {
            _inflight[key].Cancel();
            _inflight[key].Dispose();
            _inflight.Remove(key);
        }

        // Update neighbors for currently active terrains
        WireNeighbors();
    }

    private async Task SpawnChunkAsync(Vector2Int key, CancellationToken ct)
    {
        try
        {
            var coord = new ChunkCoord { x = key.x, z = key.y, chunkSize = chunkSize };
            ChunkData data = await dataProvider.GetChunkAsync(coord, ct);

            if (ct.IsCancellationRequested)
                return;

            // Create TerrainData
            TerrainData td = new TerrainData
            {
                heightmapResolution = data.heightResolution,
                alphamapResolution = data.alphaResolution > 0 ? data.alphaResolution : 16,
                baseMapResolution = 16,
                size = new Vector3(chunkSize, terrainHeight, chunkSize)
            };

            // Heights
            td.SetHeights(0, 0, data.heights);

            // Alphamaps (if provided)
            if (data.alphamaps != null && data.layerCount > 0)
            {
                EnsureSplatPrototypes(td, data.layerCount);
                td.SetAlphamaps(0, 0, data.alphamaps);
            }

            // Create/position terrain
            GameObject go = Terrain.CreateTerrainGameObject(td);
            go.name = $"Terrain_{key.x}_{key.y}";
            if (terrainMaterial != null)
            {
                var tComp = go.GetComponent<Terrain>();
                tComp.materialTemplate = terrainMaterial;
            }
            go.transform.position = new Vector3(key.x * chunkSize, 0f, key.y * chunkSize);

            var terrain = go.GetComponent<Terrain>();
            _activeTerrains[key] = terrain;

            // After spawn, wire neighbors this frame
            WireNeighbors();
        }
        catch (OperationCanceledException)
        {
            // expected on cancellation
        }
        catch (Exception e)
        {
            Debug.LogException(e);
        }
        finally
        {
            if (_inflight.TryGetValue(key, out var cts))
            {
                cts.Dispose();
                _inflight.Remove(key);
            }
        }
    }

    private void DestroyChunk(Vector2Int key)
    {
        if (_activeTerrains.TryGetValue(key, out var t))
        {
            if (t != null)
                Destroy(t.gameObject);
            _activeTerrains.Remove(key);
        }
    }

    private void WireNeighbors()
    {
        // For each terrain, set neighbors based on +/- x/z keys
        foreach (var kv in _activeTerrains)
        {
            Vector2Int k = kv.Key;
            Terrain self = kv.Value;

            _activeTerrains.TryGetValue(new Vector2Int(k.x - 1, k.y), out var left);
            _activeTerrains.TryGetValue(new Vector2Int(k.x + 1, k.y), out var right);
            _activeTerrains.TryGetValue(new Vector2Int(k.x, k.y + 1), out var top);
            _activeTerrains.TryGetValue(new Vector2Int(k.x, k.y - 1), out var bottom);

            self.SetNeighbors(left, top, right, bottom);
        }
    }

    private static void EnsureSplatPrototypes(TerrainData td, int layerCount)
    {
        // Ensure there are at least 'layerCount' terrain layers.
        var layers = td.terrainLayers != null ? td.terrainLayers.ToList() : new List<TerrainLayer>();
        while (layers.Count < layerCount)
        {
            layers.Add(new TerrainLayer { diffuseTexture = Texture2D.grayTexture, tileSize = new Vector2(10, 10) });
        }
        td.terrainLayers = layers.ToArray();
    }

    private Vector2Int WorldToChunk(Vector3 pos)
    {
        int cx = Mathf.FloorToInt(pos.x / chunkSize);
        int cz = Mathf.FloorToInt(pos.z / chunkSize);
        return new Vector2Int(cx, cz);
    }
}

#endregion

