# Vue + Vuetify 2: Avataaars builder with single URL updater and computed option previews.
# Paste this Single File Component into your Vuetify 2 app (e.g., AvatarBuilder.vue) and register it.

<template>
  <v-container fluid>
    <!-- Main avatar preview -->
    <v-row justify="center" class="mb-6">
      <v-col cols="12" sm="6" md="4" class="text-center">
        <v-img :src="avatarUrl" contain height="300" />
      </v-col>
    </v-row>

    <!-- Category tabs -->
    <v-tabs v-model="activeTab" background-color="primary" dark grow>
      <v-tab v-for="cat in categories" :key="cat.key">{{ cat.label }}</v-tab>
    </v-tabs>

    <v-tabs-items v-model="activeTab">
      <v-tab-item v-for="(cat, tabIndex) in categories" :key="cat.key">
        <v-card flat class="pa-4">
          <div class="subtitle-2 mb-3">
            Selected: {{ selections[cat.key] }}
          </div>

          <!-- Item group: 3 items per row -->
          <v-item-group
            v-model="selections[cat.key]"
            mandatory
            @change="onSelectionChange"
          >
            <v-row dense>
              <v-col
                v-for="opt in cat.options"
                :key="opt"
                cols="4"
                class="d-flex"
              >
                <v-item :value="opt" v-slot="{ active, toggle }">
                  <v-card
                    :elevation="active ? 10 : 2"
                    :class="['d-flex', 'flex-column', 'align-center', 'pa-2', active ? 'primary--text' : '']"
                    @click="toggle"
                  >
                    <v-img
                      :src="previewsByCategory[cat.key][opt]"
                      height="100"
                      contain
                    />
                    <div class="caption mt-2 text-truncate" style="max-width: 100%;">
                      {{ opt }}
                    </div>
                  </v-card>
                </v-item>
              </v-col>
            </v-row>
          </v-item-group>
        </v-card>
      </v-tab-item>
    </v-tabs-items>
  </v-container>
</template>

<script>
export default {
  name: 'AvatarBuilder',
  data() {
    return {
      activeTab: 0,
      avatarBaseUrl: 'https://avataaars.io/',
      avatarUrl: '',
      storageKey: 'avatarSelectionsV1',

      // Centralized selections (single source of truth for the avatar)
      selections: {
        avatarStyle: 'Transparent',
        topType: 'ShortHairShortFlat',
        accessoriesType: 'Blank',
        hairColor: 'BrownDark',
        facialHairType: 'Blank',
        facialHairColor: 'BrownDark',
        clotheType: 'Hoodie',
        clotheColor: 'PastelBlue',
        graphicType: 'Skull',
        eyeType: 'Default',
        eyebrowType: 'Default',
        mouthType: 'Smile',
        skinColor: 'Light'
      },

      // All categories with options
      categories: [
        { key: 'avatarStyle', label: 'Avatar Style', options: ['Transparent', 'Circle'] },
        {
          key: 'topType',
          label: 'Top',
          options: [
            'NoHair', 'Eyepatch', 'Hat', 'Hijab', 'Turban',
            'WinterHat1', 'WinterHat2', 'WinterHat3', 'WinterHat4',
            'LongHairBigHair', 'LongHairBob', 'LongHairBun', 'LongHairCurly', 'LongHairCurvy',
            'LongHairDreads', 'LongHairFrida', 'LongHairFro', 'LongHairFroBand', 'LongHairMiaWallace',
            'LongHairNotTooLong', 'LongHairShavedSides', 'LongHairStraight', 'LongHairStraight2',
            'LongHairStraightStrand',
            'ShortHairDreads01', 'ShortHairDreads02', 'ShortHairFrizzle', 'ShortHairShaggyMullet',
            'ShortHairShortCurly', 'ShortHairShortFlat', 'ShortHairShortRound', 'ShortHairShortWaved',
            'ShortHairSides', 'ShortHairTheCaesar', 'ShortHairTheCaesarSidePart'
          ]
        },
        {
          key: 'accessoriesType',
          label: 'Accessories',
          options: ['Blank', 'Kurt', 'Prescription01', 'Prescription02', 'Round', 'Sunglasses', 'Wayfarers']
        },
        {
          key: 'hairColor',
          label: 'Hair Color',
          options: ['Auburn', 'Black', 'Blonde', 'BlondeGolden', 'Brown', 'BrownDark', 'PastelPink', 'Platinum', 'Red', 'SilverGray']
        },
        {
          key: 'facialHairType',
          label: 'Facial Hair',
          options: ['Blank', 'BeardLight', 'BeardMedium', 'BeardMajestic', 'MoustacheFancy', 'MoustacheMagnum']
        },
        {
          key: 'facialHairColor',
          label: 'Facial Hair Color',
          options: ['Auburn', 'Black', 'Blonde', 'BlondeGolden', 'Brown', 'BrownDark', 'Platinum', 'Red']
        },
        {
          key: 'clotheType',
          label: 'Clothes',
          options: ['BlazerShirt', 'BlazerSweater', 'CollarSweater', 'GraphicShirt', 'Hoodie', 'Overall', 'ShirtCrewNeck', 'ShirtScoopNeck', 'ShirtVNeck']
        },
        {
          key: 'clotheColor',
          label: 'Clothes Color',
          options: ['Black', 'Blue01', 'Blue02', 'Blue03', 'Gray01', 'Gray02', 'Heather', 'PastelBlue', 'PastelGreen', 'PastelOrange', 'PastelRed', 'PastelYellow', 'Pink', 'Red', 'White']
        },
        {
          key: 'graphicType',
          label: 'Graphic',
          options: ['Bear', 'Bat', 'Cumbia', 'Deer', 'Diamond', 'Hola', 'Pizza', 'Resist', 'Selena', 'Skull', 'SkullOutline']
        },
        {
          key: 'eyeType',
          label: 'Eyes',
          options: ['Close', 'Cry', 'Default', 'Dizzy', 'EyeRoll', 'Happy', 'Hearts', 'Side', 'Squint', 'Surprised', 'Wink', 'WinkWacky']
        },
        {
          key: 'eyebrowType',
          label: 'Eyebrows',
          options: ['Angry', 'AngryNatural', 'Default', 'DefaultNatural', 'FlatNatural', 'RaisedExcited', 'RaisedExcitedNatural', 'SadConcerned', 'SadConcernedNatural', 'UnibrowNatural', 'UpDown', 'UpDownNatural']
        },
        {
          key: 'mouthType',
          label: 'Mouth',
          options: ['Concerned', 'Default', 'Disbelief', 'Eating', 'Grimace', 'Sad', 'ScreamOpen', 'Serious', 'Smile', 'Tongue', 'Twinkle', 'Vomit']
        },
        {
          key: 'skinColor',
          label: 'Skin',
          options: ['Tanned', 'Yellow', 'Pale', 'Light', 'Brown', 'DarkBrown', 'Black']
        }
      ]
    };
  },

  computed: {
    // Computed dictionary of preview URLs for every category/option, derived from the current selections.
    // Each preview shows how the avatar would look if ONLY that category changed to the option.
    previewsByCategory() {
      const result = {};
      for (const cat of this.categories) {
        const map = {};
        for (const opt of cat.options) {
          const hypothetical = { ...this.selections, [cat.key]: opt };
          map[opt] = this.buildAvatarUrl(hypothetical);
        }
        result[cat.key] = map;
      }
      return result;
    }
  },

  created() {
    // Load from localStorage if present
    const saved = localStorage.getItem(this.storageKey);
    if (saved) {
      try {
        const parsed = JSON.parse(saved);
        // Only assign known keys to avoid stray data
        Object.keys(this.selections).forEach(k => {
          if (parsed[k] !== undefined) this.selections[k] = parsed[k];
        });
      } catch (_) {}
    }
    // Initialize URL once selections are ready
    this.updateAvatarUrl();
  },

  methods: {
    // Build a single Avataaars URL from a selections object (or current state by default)
    buildAvatarUrl(sel = this.selections) {
      // Map internal keys to avataaars query parameter names
      const paramMap = {
        avatarStyle: 'avatarStyle',
        topType: 'topType',
        accessoriesType: 'accessoriesType',
        hairColor: 'hairColor',
        facialHairType: 'facialHairType',
        facialHairColor: 'facialHairColor',
        clotheType: 'clotheType',
        clotheColor: 'clotheColor',
        graphicType: 'graphicType',
        eyeType: 'eyeType',
        eyebrowType: 'eyebrowType',
        mouthType: 'mouthType',
        skinColor: 'skinColor'
      };

      const params = new URLSearchParams();
      Object.keys(paramMap).forEach(k => {
        const v = sel[k];
        if (v !== undefined && v !== null && v !== '') {
          params.set(paramMap[k], v);
        }
      });

      return `${this.avatarBaseUrl}?${params.toString()}`;
    },

    // Single function to update the main avatar URL and persist to localStorage
    updateAvatarUrl() {
      this.avatarUrl = this.buildAvatarUrl(this.selections);
      localStorage.setItem(this.storageKey, JSON.stringify(this.selections));
    },

    // Handler when any selection changes
    onSelectionChange() {
      this.updateAvatarUrl();
    }
  }
};
</script>
