Below is a complete, compilable C# implementation. It defines Range as a readonly record struct using half-open semantics [StartIncl, EndExl), validates inputs (StartIncl <= EndExl), and provides:

- SplitByOverlap: returns a compact, ordered list of non-empty segments.
- SplitByOverlap3: returns a fixed-shape tuple (Before, Overlap, After) as nullable ranges.

Behavior summary:
- Empty inputs:
  - both empty -> []
  - one empty -> [the non-empty range] (SplitByOverlap) or (non-empty, null, null) (SplitByOverlap3)
- Disjoint or touching (adjacent) -> return the two inputs in start order
- Overlap or containment -> return up to three segments: before, overlap, after

// You can compile this as a single file: `dotnet new console -n Demo && cd Demo && dotnet run` after replacing Program.cs.

using System;
using System.Collections.Generic;

public readonly record struct Range(long StartIncl, long EndExl)
{
    // Half-open interval: [StartIncl, EndExl)
    public bool IsEmpty => StartIncl >= EndExl;

    public override string ToString() => $"[{StartIncl},{EndExl})";
}

public static class RangeUtils
{
    // Split into a compact, ordered list of non-empty segments.
    // - If disjoint or abutting: [left, right]
    // - If overlapping: [before?], overlap, [after?]
    // - Empty inputs: both empty -> []; one empty -> [non-empty]
    public static List<Range> SplitByOverlap(Range r1, Range r2)
    {
        ValidateRange(r1, nameof(r1));
        ValidateRange(r2, nameof(r2));

        // Handle empty inputs early
        bool e1 = r1.IsEmpty;
        bool e2 = r2.IsEmpty;
        if (e1 && e2) return new List<Range>(0);
        if (e1) return new List<Range>(1) { r2 };
        if (e2) return new List<Range>(1) { r1 };

        // Normalize so 'left' starts no later than 'right'
        var (left, right) = Normalize(r1, r2);

        var result = new List<Range>(capacity: 3);

        // Disjoint or abutting (no overlap)
        if (left.EndExl <= right.StartIncl)
        {
            result.Add(left);
            result.Add(right);
            return result;
        }

        // Overlapping or containment
        long overlapStart = Math.Max(left.StartIncl, right.StartIncl); // == right.StartIncl after normalization
        long overlapEnd = Math.Min(left.EndExl, right.EndExl);

        // Before overlap (if left starts earlier)
        if (left.StartIncl < overlapStart)
            result.Add(new Range(left.StartIncl, overlapStart));

        // Overlap itself (non-empty under this branch)
        if (overlapStart < overlapEnd)
            result.Add(new Range(overlapStart, overlapEnd));

        // After overlap (extends to the later end)
        long laterEnd = Math.Max(left.EndExl, right.EndExl);
        if (overlapEnd < laterEnd)
            result.Add(new Range(overlapEnd, laterEnd));

        return result;
    }

    // Split into fixed slots: (Before, Overlap, After), each nullable.
    // - Disjoint or touching: (left, null, right)
    // - Overlapping or containment: (before?, overlap, after?)
    // - Empty inputs: both empty -> (null, null, null); one empty -> (non-empty, null, null)
    public static (Range? Before, Range? Overlap, Range? After) SplitByOverlap3(Range r1, Range r2)
    {
        ValidateRange(r1, nameof(r1));
        ValidateRange(r2, nameof(r2));

        // Handle empty inputs early
        bool e1 = r1.IsEmpty;
        bool e2 = r2.IsEmpty;
        if (e1 && e2) return (null, null, null);
        if (e1) return (r2, null, null);
        if (e2) return (r1, null, null);

        // Normalize to (left, right)
        var (left, right) = Normalize(r1, r2);

        // Disjoint or abutting (no overlap)
        if (left.EndExl <= right.StartIncl)
            return (left, null, right);

        // Overlapping or containment
        long overlapStart = Math.Max(left.StartIncl, right.StartIncl); // == right.StartIncl after normalization
        long overlapEnd = Math.Min(left.EndExl, right.EndExl);

        Range? before = null;
        Range? overlap = null;
        Range? after = null;

        if (left.StartIncl < overlapStart)
            before = new Range(left.StartIncl, overlapStart);

        if (overlapStart < overlapEnd)
            overlap = new Range(overlapStart, overlapEnd);

        long laterEnd = Math.Max(left.EndExl, right.EndExl);
        if (overlapEnd < laterEnd)
            after = new Range(overlapEnd, laterEnd);

        return (before, overlap, after);
    }

    // Validate a single range: allow empty; disallow inverted
    private static void ValidateRange(Range r, string paramName)
    {
        if (r.StartIncl > r.EndExl)
            throw new ArgumentException("StartIncl must be <= EndExl (EndExl is exclusive).", paramName);
    }

    // Order the two ranges so 'left' starts first (then ends first if tied)
    private static (Range left, Range right) Normalize(Range r1, Range r2)
    {
        if (r1.StartIncl < r2.StartIncl ||
            (r1.StartIncl == r2.StartIncl && r1.EndExl <= r2.EndExl))
        {
            return (r1, r2);
        }
        return (r2, r1);
    }
}

public static class Program
{
    public static void Main()
    {
        // Quick demos

        // 1) Overlap partially: [1,10) and [5,15) -> [1,5), [5,10), [10,15)
        Dump(RangeUtils.SplitByOverlap(new Range(1, 10), new Range(5, 15)));
        Dump3(RangeUtils.SplitByOverlap3(new Range(1, 10), new Range(5, 15)));

        // 2) Containment: [1,10) and [3,7) -> [1,3), [3,7), [7,10)
        Dump(RangeUtils.SplitByOverlap(new Range(1, 10), new Range(3, 7)));
        Dump3(RangeUtils.SplitByOverlap3(new Range(1, 10), new Range(3, 7)));

        // 3) Identical: [2,5) and [2,5) -> [2,5)
        Dump(RangeUtils.SplitByOverlap(new Range(2, 5), new Range(2, 5)));
        Dump3(RangeUtils.SplitByOverlap3(new Range(2, 5), new Range(2, 5)));

        // 4) Adjacent (touching, no overlap): [0,3) and [3,8) -> [0,3), [3,8)
        Dump(RangeUtils.SplitByOverlap(new Range(0, 3), new Range(3, 8)));
        Dump3(RangeUtils.SplitByOverlap3(new Range(0, 3), new Range(3, 8)));

        // 5) Disjoint: [0,3) and [5,8) -> [0,3), [5,8)
        Dump(RangeUtils.SplitByOverlap(new Range(0, 3), new Range(5, 8)));
        Dump3(RangeUtils.SplitByOverlap3(new Range(0, 3), new Range(5, 8)));

        // 6) One empty: [] and [10,20) -> [10,20)
        Dump(RangeUtils.SplitByOverlap(new Range(5, 5), new Range(10, 20)));
        Dump3(RangeUtils.SplitByOverlap3(new Range(5, 5), new Range(10, 20)));

        // 7) Both empty: [] and [] -> []
        Dump(RangeUtils.SplitByOverlap(new Range(7, 7), new Range(9, 9)));
        Dump3(RangeUtils.SplitByOverlap3(new Range(7, 7), new Range(9, 9)));
    }

    private static void Dump(List<Range> ranges)
    {
        Console.WriteLine(string.Join(", ", ranges));
    }

    private static void Dump3((Range? Before, Range? Overlap, Range? After) t)
    {
        Console.WriteLine($"Before={t.Before?.ToString() ?? "null"}, Overlap={t.Overlap?.ToString() ?? "null"}, After={t.After?.ToString() ?? "null"}");
    }
}

Below is a complete, runnable Flask app that you can deploy (Render, Railway, Fly.io, Heroku, etc.) and embed on your Square.com site via an iframe. It provides:

- A working /embed route with a compact UI for pasting recipe text or uploading .txt/.pdf files
- Ingredient extraction and external lookups (Wikipedia, Wikidata, Datamuse) with timeouts and error handling
- A playful spell generator using the extracted ingredients and lookup info
- Clear error states and a self-contained HTML/CSS layout suitable for iframes

How to embed on Square:
- Deploy this app to a public URL (e.g., https://your-spell-app.example.com)
- In Square Online > Website > Edit site > Add section > Embed code, paste this exact snippet:
  <iframe src="https://your-spell-app.example.com/embed" width="100%" height="960" style="border:0;max-width:100%"></iframe>

Note:
- For PDFs, install PyPDF2 (pip install PyPDF2). If not installed, PDF upload will show a clear error.
- All lookups use public endpoints with no API keys.
- Default timeout per HTTP call is 4 seconds.
- Intended for entertainment/creative use.

```python
# app.py
import io
import re
import html
import logging
import random
from datetime import datetime
from typing import List, Dict, Optional
from collections import OrderedDict

from flask import Flask, request, make_response, redirect, url_for
import requests

# Optional PDF support
try:
    import PyPDF2
    HAS_PDF = True
except Exception:
    HAS_PDF = False

app = Flask(__name__)
app.config["MAX_CONTENT_LENGTH"] = 2 * 1024 * 1024  # 2 MB upload limit

logging.basicConfig(level=logging.INFO)
logger = logging.getLogger("spell-app")

# --------- Ingredient Parsing ---------

UNITS = {
    "cup", "cups", "tsp", "teaspoon", "teaspoons", "tbsp", "tablespoon", "tablespoons",
    "g", "gram", "grams", "kg", "kilogram", "kilograms", "ml", "l", "liter", "liters",
    "oz", "ounce", "ounces", "lb", "pound", "pounds",
    "pinch", "dash", "slice", "slices", "clove", "cloves", "piece", "pieces",
    "can", "cans", "package", "packages", "pkg", "small", "medium", "large"
}
STOPWORDS = {
    "fresh", "dried", "ground", "minced", "chopped", "sliced", "grated", "crushed",
    "to", "taste", "and", "or", "optional", "about", "of"
}
SECTION_BREAKERS = {
    "ingredients", "instructions", "method", "directions", "steps", "preparation",
    "prep", "cook", "cooking", "baking", "notes", "equipment"
}
USER_AGENT = {"User-Agent": "SpellWidget/1.0 (+https://example.com)"}
HTTP_TIMEOUT = 4.0


def normalize_ingredient_line(line: str) -> Optional[str]:
    # Remove parenthetical notes
    line = re.sub(r"\([^)]*\)", "", line)
    # Normalize and trim
    line = line.strip().lstrip("-•*").strip()
    # Remove leading quantities like "1 1/2", "2", "2-3", "200 g", etc.
    line = re.sub(r"^\s*(\d+([\/\.\-]\d+)?(\s+\d+\/\d+)?\s*)+", "", line)
    # Remove unicode fraction like "½"
    line = re.sub(r"^[¼½¾⅓⅔⅕⅖⅗⅘⅙⅚⅛⅜⅝⅞]+\s*", "", line)
    tokens = [t for t in re.split(r"[,\s]+", line) if t]
    if not tokens:
        return None

    # Skip initial unit tokens
    i = 0
    while i < len(tokens) and tokens[i].lower() in UNITS:
        i += 1
    cleaned = tokens[i:] if i < len(tokens) else []

    if not cleaned:
        return None

    # Remove common stopwords
    cleaned = [t for t in cleaned if t.lower() not in STOPWORDS]

    if cleaned and cleaned[0].lower() == "of":
        cleaned = cleaned[1:]

    ing = " ".join(cleaned)
    ing = ing.strip(" ,.;:-").strip()

    pieces = ing.split()
    if len(pieces) > 5:
        # Keep the likely core, e.g., "brown sugar"
        ing = " ".join(pieces[-3:])

    ing = re.sub(r"\s+", " ", ing).strip().lower()

    if not ing or len(ing) < 2:
        return None

    # Exclude section headers and non-ingredient lines
    if any(h in ing for h in SECTION_BREAKERS):
        return None
    if ing.startswith(("serves", "yield", "time", "total time", "prep time", "cook time")):
        return None
    # Avoid lines that are likely headings
    if len(ing.split()) <= 1 and not ing.isalpha():
        return None

    # Trim trailing descriptors like "to taste" or "as needed"
    ing = re.sub(r"\b(to taste|as needed)\b", "", ing).strip()
    return ing if ing else None


def extract_ingredients_from_text(text: str, limit: int = 20) -> List[str]:
    lines = [l.strip() for l in text.splitlines()]
    ingredients_block: List[str] = []
    in_ing = False
    found_section = False

    # Try to find an "Ingredients" section
    for line in lines:
        low = line.strip().lower()
        if not in_ing and re.match(r"^\s*ingredients\s*:?\s*$", low):
            in_ing = True
            found_section = True
            continue
        if in_ing:
            if (not line or
                any(b in low for b in SECTION_BREAKERS if b != "ingredients") or
                re.match(r"^\s*[A-Za-z ]{3,}\s*:?\s*$", low)):
                # End on blank or another section header
                if ingredients_block:
                    break
                else:
                    in_ing = False
                    continue
            ingredients_block.append(line)

    candidates: List[str] = []
    if found_section and ingredients_block:
        for raw in ingredients_block:
            ing = normalize_ingredient_line(raw)
            if ing:
                candidates.append(ing)
    else:
        # Fallback: scan all lines, prefer bullets or lines with quantities
        for raw in lines:
            if not raw:
                continue
            if raw.strip().startswith(("-", "*", "•")) or re.search(r"\d", raw):
                ing = normalize_ingredient_line(raw)
                if ing:
                    candidates.append(ing)

    # Deduplicate while preserving order
    seen = set()
    deduped: List[str] = []
    for ing in candidates:
        if ing not in seen:
            seen.add(ing)
            deduped.append(ing)
        if len(deduped) >= limit:
            break
    return deduped


def extract_text_from_pdf(file_bytes: bytes) -> str:
    if not HAS_PDF:
        raise RuntimeError("PDF parsing not available on server")
    try:
        reader = PyPDF2.PdfReader(io.BytesIO(file_bytes))
        pages_text = []
        for page in reader.pages:
            try:
                pages_text.append(page.extract_text() or "")
            except Exception:
                continue
        return "\n".join(pages_text).strip()
    except Exception as e:
        raise RuntimeError(f"Failed to read PDF: {e}")

# --------- External Knowledge Lookups ---------

def http_get_json(url: str, params: Optional[dict] = None, timeout: float = HTTP_TIMEOUT) -> Optional[dict]:
    try:
        r = requests.get(url, params=params, headers=USER_AGENT, timeout=timeout)
        if r.status_code == 200:
            return r.json()
        else:
            logger.warning(f"GET {url} returned {r.status_code}")
            return None
    except requests.RequestException as e:
        logger.warning(f"GET {url} failed: {e}")
        return None


def truncate(text: str, max_len: int = 300) -> str:
    if not text:
        return ""
    text = re.sub(r"\s+", " ", text).strip()
    return (text[: max_len - 1] + "…") if len(text) > max_len else text


def wiki_summary(term: str) -> Optional[str]:
    # Try REST summary first
    safe_title = term.replace(" ", "_")
    url = f"https://en.wikipedia.org/api/rest_v1/page/summary/{requests.utils.quote(safe_title)}"
    try:
        r = requests.get(url, headers=USER_AGENT, timeout=HTTP_TIMEOUT)
        if r.status_code == 200:
            data = r.json()
            extract = data.get("extract") or ""
            if extract:
                return truncate(extract, 420)
    except requests.RequestException:
        pass

    # Action API search fallback
    search_api = "https://en.wikipedia.org/w/api.php"
    sdata = http_get_json(search_api, {
        "action": "opensearch",
        "search": term,
        "limit": 1,
        "namespace": 0,
        "format": "json",
        "redirects": "resolve",
    })
    if sdata and len(sdata) >= 4 and sdata[1]:
        title = sdata[1][0]
        edata = http_get_json(search_api, {
            "action": "query",
            "prop": "extracts",
            "exintro": 1,
            "explaintext": 1,
            "redirects": 1,
            "titles": title,
            "format": "json",
        })
        if edata:
            pages = edata.get("query", {}).get("pages", {})
            for _, p in pages.items():
                ext = p.get("extract")
                if ext:
                    return truncate(ext, 420)
    return None


def wikidata_description(term: str) -> Optional[str]:
    url = "https://www.wikidata.org/w/api.php"
    data = http_get_json(url, {
        "action": "wbsearchentities",
        "language": "en",
        "format": "json",
        "search": term,
        "limit": 1,
    })
    if data and data.get("search"):
        desc = data["search"][0].get("description")
        return truncate(desc, 160) if desc else None
    return None


def datamuse_adjectives(noun: str, maxn: int = 5) -> List[str]:
    url = "https://api.datamuse.com/words"
    try:
        r = requests.get(url, params={"rel_jjb": noun, "max": maxn}, headers=USER_AGENT, timeout=HTTP_TIMEOUT)
        if r.status_code == 200:
            words = [w.get("word") for w in r.json() if w.get("word")]
            keep = []
            seen = set()
            for w in words:
                lw = w.lower()
                if lw in seen:
                    continue
                if lw in {"good", "many", "more", "much", "little", "other"}:
                    continue
                seen.add(lw)
                keep.append(lw)
            return keep[:maxn]
    except requests.RequestException:
        pass
    return []


def datamuse_similar(noun: str, maxn: int = 5) -> List[str]:
    url = "https://api.datamuse.com/words"
    try:
        r = requests.get(url, params={"ml": noun, "max": maxn}, headers=USER_AGENT, timeout=HTTP_TIMEOUT)
        if r.status_code == 200:
            words = [w.get("word") for w in r.json() if w.get("word")]
            keep = []
            seen = set()
            for w in words:
                lw = w.lower()
                if lw in seen or " " in lw:
                    continue
                seen.add(lw)
                keep.append(lw)
            return keep[:maxn]
    except requests.RequestException:
        pass
    return []


LOOKUP_CACHE: Dict[str, Dict] = {}


def fetch_knowledge_for_ingredient(ing: str) -> Dict:
    if ing in LOOKUP_CACHE:
        return LOOKUP_CACHE[ing]

    summary = wiki_summary(ing) or ""
    desc = wikidata_description(ing) or ""
    adjs = datamuse_adjectives(ing, maxn=5)
    related = datamuse_similar(ing, maxn=5)

    data = {
        "ingredient": ing,
        "wikipedia_summary": summary,
        "wikidata_description": desc,
        "adjectives": adjs,
        "related": related,
        "sources": {
            "wikipedia": f"https://en.wikipedia.org/wiki/{requests.utils.quote(ing.replace(' ', '_'))}",
            "wikidata_search": f"https://www.wikidata.org/w/index.php?search={requests.utils.quote(ing)}",
            "datamuse": "https://api.datamuse.com/words"
        }
    }
    LOOKUP_CACHE[ing] = data
    return data

# --------- Spell Generation ---------

def build_spell(ingredients: List[str], knowledge: Dict[str, Dict]) -> str:
    if not ingredients:
        return "No ingredients found to weave into a spell."

    incantation_openers = [
        "By spoon and star I call upon",
        "Hear me, hearth and hidden flame, with",
        "Under moonlit whisk I summon",
        "From pantry realms arise with",
        "Bound by crumb and candle, gather"
    ]
    closers = [
        "So stirred, let wonders rise.",
        "Thus mixed, may luck be thine.",
        "Now baked in fate and fragrant time.",
        "Henceforth, sweetness guard your way.",
        "Be it whisked, be it done."
    ]
    opener = random.choice(incantation_openers)
    closer = random.choice(closers)

    lines = [f"{opener} the essence of:"]
    for ing in ingredients[:12]:
        info = knowledge.get(ing, {})
        adjs = info.get("adjectives") or []
        desc = info.get("wikidata_description") or ""
        pick_adj = adjs[0] if adjs else "true"
        fragment = desc if desc else (info.get("wikipedia_summary") or "")
        frag_short = truncate(fragment, 120)
        lines.append(f"• {pick_adj} {ing}" + (f" — {frag_short}" if frag_short else ""))

    lines.append("")
    lines.append(closer)
    return "\n".join(lines)

