# --------- Routes ---------

@app.after_request
def add_security_headers(resp):
    # Minimal headers friendly to iframes on same-site or cross-site
    resp.headers.setdefault("X-Content-Type-Options", "nosniff")
    resp.headers.setdefault("Referrer-Policy", "no-referrer-when-downgrade")
    return resp

@app.route("/")
def index():
    # Redirect to embed UI for simplicity
    return redirect(url_for("embed"))

@app.route("/embed", methods=["GET"])
def embed():
    # Initial empty UI
    html_out = EMBED_HTML
    rendered = html_out.replace("{% if error %}", "{% if error %}")  # noop to keep template text intact
    # We are not using Jinja template engine to avoid multi-file deps; do simple token replacement.
    return make_response(simple_render(EMBED_HTML, {
        "error": "",
        "recipe_text": "",
        "results": None,
        "now": html.escape(datetime.utcnow().strftime("%Y-%m-%d %H:%M UTC"))
    }), 200)

@app.route("/process", methods=["POST"])
def process():
    error = ""
    text_input = (request.form.get("recipe_text") or "").strip()
    file_text = ""
    if "recipe_file" in request.files:
        f = request.files["recipe_file"]
        if f and f.filename:
            try:
                fname = f.filename.lower()
                fb = f.read()
                if not fb:
                    pass
                elif fname.endswith(".txt"):
                    try:
                        file_text = fb.decode("utf-8", errors="ignore")
                    except Exception:
                        file_text = fb.decode("latin-1", errors="ignore")
                elif fname.endswith(".pdf") or f.mimetype == "application/pdf":
                    if not HAS_PDF:
                        error = "PDF parsing not available on server. Please install PyPDF2."
                    else:
                        try:
                            file_text = extract_text_from_pdf(fb)
                        except Exception as e:
                            error = f"Failed to read PDF: {e}"
                else:
                    error = "Unsupported file type. Please upload .txt or .pdf."
            except Exception as e:
                error = f"Failed to read file: {e}"

    recipe_text = (text_input + ("\n" + file_text if file_text else "")).strip()

    ingredients: List[str] = []
    if not error:
        if recipe_text:
            try:
                ingredients = extract_ingredients_from_text(recipe_text, limit=20)
            except Exception as e:
                error = f"Failed to parse ingredients: {e}"
        else:
            error = "Please paste text or upload a .txt/.pdf file."

    knowledge_by_ing: Dict[str, Dict] = {}
    if not error and ingredients:
        for ing in ingredients:
            try:
                knowledge_by_ing[ing] = fetch_knowledge_for_ingredient(ing)
            except Exception as e:
                # Continue even if one lookup fails
                logger.warning(f"Lookup failed for {ing}: {e}")
                knowledge_by_ing[ing] = {
                    "ingredient": ing,
                    "wikipedia_summary": "",
                    "wikidata_description": "",
                    "adjectives": [],
                    "related": [],
                    "sources": {}
                }

    spell_text = ""
    if not error and ingredients:
        try:
            spell_text = build_spell(ingredients, knowledge_by_ing)
        except Exception as e:
            error = f"Failed to generate spell: {e}"

    results = {
        "ingredients": ingredients,
        "spell": spell_text,
        "error": error
    }

    page = simple_render(EMBED_HTML, {
        "error": html.escape(error) if error else "",
        "recipe_text": html.escape(text_input),
        "results": results,
        "now": html.escape(datetime.utcnow().strftime("%Y-%m-%d %H:%M UTC"))
    })
    return make_response(page, 200)


# --------- Minimal string-template renderer ---------
# We keep a single-file app without importing jinja2; replace only a small subset.

def simple_render(tpl: str, ctx: Dict) -> str:
    # Very tiny renderer that supports the placeholders in EMBED_HTML
    # We handle only: {{ var }} and a few conditional/result blocks used above.
    s = tpl

    def esc(v):
        if v is None:
            return ""
        if isinstance(v, str):
            return v
        return html.escape(str(v))

    # Conditionals for top-level error
    if ctx.get("error"):
        s = s.replace("{% if error %}", "").replace("{% endif %}", "", 1)
        s = s.replace("{{ error }}", esc(ctx["error"]))
    else:
        # Remove the error block entirely
        s = remove_block(s, "{% if error %}", "{% endif %}")

    s = s.replace("{{ recipe_text or \"\" }}", esc(ctx.get("recipe_text") or ""))
    s = s.replace("{{ recipe_text }}", esc(ctx.get("recipe_text") or ""))

    # Results section
    if ctx.get("results") is None:
        # Remove entire results block
        s = remove_block(s, "{% if results %}", "{% endif %}")
    else:
        # Keep results block, then handle its internal conditionals
        s = s.replace("{% if results %}", "").replace("{% endif %}", "", 1)

        results = ctx["results"]
        # Insert ingredients badges
        if results.get("ingredients"):
            ing_html = ""
            for ing in results["ingredients"]:
                ing_html += f'<span class="badge">{html.escape(ing)}</span>\n'
            s = s.replace("{% for ing in results.ingredients %}\n              <span class=\"badge\">{{ ing }}</span>\n            {% endfor %}", ing_loop_placeholder())
            s = s.replace("{{ING_BADGES_LOOP}}", ing_html)
        else:
            # remove badges row
            s = remove_block(s,
                             '<div class="badges" style="margin: 8px 0 12px;">',
                             '</div>',
                             include_bounds=True)

        # Error inside results
        if results.get("error"):
            s = s.replace("{% if results.error %}", "").replace("{% endif %}", "", 1)
            s = s.replace("{{ results.error }}", esc(results["error"]))
        else:
            s = remove_block(s, "{% if results.error %}", "{% endif %}")

        # If ingredients and spell
        if results.get("ingredients") and results.get("spell"):
            s = s.replace("{% if results.ingredients and results.spell %}", "").replace("{% endif %}", "", 1)
            s = s.replace("{{ results.spell }}", esc(results["spell"]))
        else:
            s = remove_block(s, "{% if results.ingredients and results.spell %}", "{% endif %}")

        # elif ingredients and not spell
        if results.get("ingredients") and not results.get("spell"):
            s = s.replace("{% elif results.ingredients and not results.spell %}", "")
            # keep block content; ensure the later {% else %} is removed
            s = remove_after(s, "{% elif results.ingredients and not results.spell %}")
            s = remove_block(s, "{% else %}", "{% endif %}")
        else:
            s = remove_block(s, "{% elif results.ingredients and not results.spell %}", "{% else %}")

            # now handle final else (no ingredients)
            if not results.get("ingredients"):
                s = s.replace("{% else %}", "").replace("{% endif %}", "", 1)
            else:
                s = remove_block(s, "{% else %}", "{% endif %}")

    s = s.replace("{{ now }}", esc(ctx.get("now") or ""))

    return s


def remove_block(s: str, start_marker: str, end_marker: str, include_bounds: bool = False) -> str:
    start = s.find(start_marker)
    if start == -1:
        return s
    end = s.find(end_marker, start + len(start_marker))
    if end == -1:
        return s
    if include_bounds:
        return s[:start] + s[end + len(end_marker):]
    else:
        return s[:start] + s[start + len(start_marker):end] + s[end + len(end_marker):]


def remove_after(s: str, marker: str) -> str:
    # Remove just the marker token
    return s.replace(marker, "")


def ing_loop_placeholder() -> str:
    # Replace the for-loop region with a placeholder token
    start = '{% for ing in results.ingredients %}'
    end = '{% endfor %}'
    return "{{ING_BADGES_LOOP}}"


# --------- Entrypoint ---------

if __name__ == "__main__":
    # For local testing
    app.run(host="0.0.0.0", port=5000, debug=False)
