def read_text_file_storage(fs) -> str:
    try:
        data = fs.read()
        if isinstance(data, bytes):
            try:
                return data.decode("utf-8")
            except UnicodeDecodeError:
                return data.decode("latin-1", errors="ignore")
        return str(data)
    finally:
        try:
            fs.close()
        except Exception:
            pass

@app.route("/process", methods=["POST"])
def process():
    # Server-side validation
    text = (request.form.get("recipe_text") or "").strip()
    file = request.files.get("recipe_file")

    if not text and (not file or file.filename.strip() == ""):
        return render_form(error="Please paste recipe text or choose a .txt/.pdf file.")

    if file and file.filename:
        filename = file.filename
        lower = filename.lower()
        if not (lower.endswith(".txt") or lower.endswith(".pdf")):
            return render_form(error="Unsupported file type. Please upload a .txt or .pdf file.")
        try:
            bytes_data = file.read()
            if len(bytes_data) == 0:
                return render_form(error="Uploaded file is empty.")
            if lower.endswith(".txt"):
                try:
                    text = bytes_data.decode("utf-8")
                except UnicodeDecodeError:
                    text = bytes_data.decode("latin-1", errors="ignore")
            else:
                try:
                    text = extract_text_from_pdf(bytes_data)
                except RuntimeError as e:
                    return render_form(error=str(e))
        except Exception as e:
            logger.exception("File read failed")
            return render_form(error=f"Failed to read uploaded file: {e}")

    if not text or len(text.strip()) < 10:
        return render_form(error="Recipe text is too short. Please provide more content.", prefill=text)

    # Extract ingredients
    try:
        ingredients = extract_ingredients_from_text(text, limit=12)
    except Exception as e:
        logger.exception("Ingredient extraction failed")
        return render_form(error=f"Failed to extract ingredients: {e}", prefill=text)

    warnings: List[str] = []
    if not ingredients:
        warnings.append("No clear ingredients were found. The spell may be less flavorful.")

    # Fetch lore for each ingredient with error isolation
    lore: Dict[str, Dict] = {}
    for ing in ingredients:
        try:
            lore[ing] = fetch_knowledge_for_ingredient(ing)
        except Exception as e:
            logger.warning(f"Lookup failed for {ing}: {e}")
            lore[ing] = {
                "ingredient": ing,
                "wikipedia_summary": "",
                "wikidata_description": "",
                "adjectives": [],
                "related": [],
                "sources": {}
            }
            warnings.append(f"Some lookups failed for '{ ing }'. Using defaults.")

    # Build spell
    try:
        spell_text = build_spell(ingredients, lore)
    except Exception as e:
        logger.exception("Spell generation failed")
        return render_form(error=f"Failed to generate spell: {e}", prefill=text)

    return render_result(ingredients, lore, spell_text, warnings)

