// TypeScript / Redux-Saga refactor with robust parsing, immutability, and edge-case handling.

import { ResultType, StepResponse } from '@txp-core/runtime';
import { put, select } from 'redux-saga/effects';
import {
  PaymentChargesTableAction,
  paymentTableSelectors
} from '@txp-core/payment-transactions-table';
import type { CreditChargesPaymentTypes } from '@txp-core/payment-transactions-table/dist/paymentTableStateTypes';

// Configuration
const DECIMALS = 2;

// ---------- Utilities ----------
const toNumber = (value: unknown, fallback = 0): number => {
  if (value == null) return fallback;
  if (typeof value === 'number' && Number.isFinite(value)) return value;
  if (typeof value === 'string') {
    const cleaned = value
      .replace(/,/g, '')
      .replace(/\s+/g, '')
      .replace(/^\((.+)\)$/, '-$1'); // "(123.45)" -> "-123.45"
    const n = Number(cleaned);
    return Number.isFinite(n) ? n : fallback;
  }
  try {
    const str = (value as any)?.toString?.();
    const n = Number(typeof str === 'string' ? str : '');
    return Number.isFinite(n) ? n : fallback;
  } catch {
    return fallback;
  }
};

const clampNonNegative = (n: number): number => (n < 0 ? 0 : n);

const roundTo = (n: number, decimals = DECIMALS): number => {
  const factor = 10 ** decimals;
  return Math.round((n + Number.EPSILON) * factor) / factor;
};

const formatAmount = (n: number, decimals = DECIMALS): string => {
  const fixed = n.toFixed(decimals);
  const trimmed = fixed.replace(/\.?0+$/, ''); // trim trailing zeros and optional dot
  return trimmed === '' ? '0' : trimmed;
};

// ---------- Saga ----------
export function* outstandingTransactionsHandler(): Generator<any, StepResponse, any> {
  try {
    const creditTableLines: CreditChargesPaymentTypes[] =
      (yield select(paymentTableSelectors.getCredits)) ?? [];

    const totalOfChargesTableRaw: unknown =
      yield select(paymentTableSelectors.getTotalOfChargesTable);

    // Normalize inputs and guard against invalid data
    let remaining = clampNonNegative(toNumber(totalOfChargesTableRaw, 0));

    // Fast path: nothing to do
    if (!Array.isArray(creditTableLines) || creditTableLines.length === 0) {
      return { result: ResultType.SUCCESS };
    }

    let didChange = false;

    const updatedCreditTable: CreditChargesPaymentTypes[] = creditTableLines.map((credit) => {
      // Shallow copy to preserve immutability
      const next: CreditChargesPaymentTypes = { ...credit };

      // "Checked" means linkedPaymentAmount is a non-empty string (including "0")
      const isChecked = String(credit?.linkedPaymentAmount ?? '') !== '';

      if (!isChecked) {
        // Unchecked rows are not modified
        return next;
      }

      const openBalance = clampNonNegative(toNumber(credit?.openBalance, 0));

      if (remaining <= 0) {
        // Match original semantics: clear when nothing left to allocate
        if (next.linkedPaymentAmount !== '') {
          next.linkedPaymentAmount = '';
          didChange = true;
        }
        return next;
      }

      // Allocate up to the open balance
      const allocation = Math.min(openBalance, remaining);
      const formatted = formatAmount(allocation, DECIMALS);

      if (next.linkedPaymentAmount !== formatted) {
        next.linkedPaymentAmount = formatted;
        didChange = true;
      }

      // Decrease remaining with rounding to avoid FP drift
      remaining = roundTo(remaining - allocation, DECIMALS);
      if (remaining < 0) remaining = 0;

      return next;
    });

    // Only dispatch if we actually changed something
    if (didChange) {
      yield put(PaymentChargesTableAction.fullCreditsTableUpdate(updatedCreditTable));
    }

    return { result: ResultType.SUCCESS };
  } catch (err) {
    // Optionally, log to monitoring here
    // e.g., yield call(logger.error, 'outstandingTransactionsHandler failed', err);
    return {
      result: ResultType.FAILURE,
      message: 'Unable to allocate outstanding transactions'
    } as StepResponse;
  }
}

public static void EmbedGeometryIntoTableCell(
    McTable table,
    int row,
    int col,
    string blockName,
    List<EntityGeometry> entityGeometry)
{
    // Minimal input validation
    if (table == null) throw new ArgumentNullException(nameof(table));
    if (row < 0 || col < 0) throw new ArgumentOutOfRangeException("Row/Col must be non-negative.");
    if (string.IsNullOrWhiteSpace(blockName)) throw new ArgumentException("Block name is required.", nameof(blockName));
    if (entityGeometry == null || entityGeometry.Count == 0) throw new ArgumentException("Entity geometry list must not be null or empty.", nameof(entityGeometry));

    try
    {
        // Acquire database and dictionaries
        var db = HostMgd.ApplicationServices.Application.DocumentManager.MdiActiveDocument.Database;
        using (var tr = db.TransactionManager.StartTransaction())
        {
            // Open BlockTable for read/update
            var bt = (McDbBlockTable)tr.GetObject(db.BlockTableId, McDbOpenMode.ForRead);
            McDbObjectId btrId;

            // Create or open target BlockTableRecord
            if (!bt.Has(blockName))
            {
                bt.UpgradeOpen();
                var newBtr = new McDbBlockTableRecord { Name = blockName };
                btrId = bt.Add(newBtr);
                tr.AddNewlyCreatedDBObject(newBtr, true);
            }
            else
            {
                btrId = bt[blockName];
            }

            var btr = (McDbBlockTableRecord)tr.GetObject(btrId, McDbOpenMode.ForWrite);

            // Clean existing entities in the block to "update" its contents
            var toErase = new List<McDbObjectId>();
            foreach (var id in btr)
                toErase.Add(id);
            foreach (var id in toErase)
            {
                var ent = (McDbEntity)tr.GetObject(id, McDbOpenMode.ForWrite, false);
                ent.Erase();
            }

            // Convert EntityGeometry -> McDbEntity and append to block
            var extents = new McGeExtents3d();
            bool hasExtents = false;

            foreach (var eg in entityGeometry)
            {
                if (eg == null) continue;

                McDbEntity newEnt = null;

                // Minimal, representative conversions; extend as your EntityGeometry supports
                switch (eg.Type)
                {
                    case EntityGeometryType.Line:
                    {
                        var ln = new McDbLine(new McGePoint3d(eg.P1.X, eg.P1.Y, eg.P1.Z),
                                              new McGePoint3d(eg.P2.X, eg.P2.Y, eg.P2.Z));
                        newEnt = ln;
                        break;
                    }
                    case EntityGeometryType.Arc:
                    {
                        var arc = new McDbArc(
                            new McGePoint3d(eg.Center.X, eg.Center.Y, eg.Center.Z),
                            eg.Radius,
                            eg.StartAngle,
                            eg.EndAngle);
                        newEnt = arc;
                        break;
                    }
                    case EntityGeometryType.Circle:
                    {
                        var cir = new McDbCircle(
                            new McGePoint3d(eg.Center.X, eg.Center.Y, eg.Center.Z),
                            eg.Radius);
                        newEnt = cir;
                        break;
                    }
                    case EntityGeometryType.Polyline:
                    {
                        var pl = new McDbPolyline();
                        foreach (var v in eg.Vertices)
                            pl.AddVertexAt(pl.NumberOfVertices, new McGePoint2d(v.X, v.Y), 0.0, 0.0, 0.0);
                        pl.Closed = eg.Closed;
                        newEnt = pl;
                        break;
                    }
                    default:
                        // Skip unsupported geometry
                        continue;
                }

                if (newEnt != null)
                {
                    var id = btr.AppendEntity(newEnt);
                    tr.AddNewlyCreatedDBObject(newEnt, true);

                    try
                    {
                        var eext = new McGeExtents3d();
                        if (newEnt.GetGeomExtents(ref eext))
                        {
                            if (!hasExtents)
                            {
                                extents = eext;
                                hasExtents = true;
                            }
                            else
                            {
                                extents.AddExt(eext);
                            }
                        }
                    }
                    catch
                    {
                        // Ignore entities without valid extents
                    }
                }
            }

            // If no geometry extents produced, create a small dummy to avoid zero-scale
            if (!hasExtents)
            {
                var pt = new McDbPoint(new McGePoint3d(0, 0, 0));
                var id = btr.AppendEntity(pt);
                tr.AddNewlyCreatedDBObject(pt, true);
                var e = new McGeExtents3d();
                pt.GetGeomExtents(ref e);
                extents = e;
                hasExtents = true;
            }

            // Get target cell geometry (size) and origin
            if (row >= table.RowsCount || col >= table.ColumnsCount)
                throw new ArgumentOutOfRangeException("Target cell is out of table bounds.");

            // Ensure the table is open for write to assign contents
            var tblForWrite = (McTable)tr.GetObject(table.ObjectId, McDbOpenMode.ForWrite);

            double cellWidth = tblForWrite.GetColumnWidth(col);
            double cellHeight = tblForWrite.GetRowHeight(row);

            // Compute scaling and transform to fit block contents into cell
            // Extents provide min/max in block space
            var minPt = extents.MinPoint;
            var maxPt = extents.MaxPoint;

            double geomW = Math.Max(1e-9, maxPt.X - minPt.X);
            double geomH = Math.Max(1e-9, maxPt.Y - minPt.Y);

            double sx = cellWidth / geomW;
            double sy = cellHeight / geomH;
            double scale = Math.Min(sx, sy);

            // Build transform: translate to origin, scale, translate to cell center
            var baseToOrigin = McGeMatrix3d.Displacement(new McGeVector3d(-minPt.X, -minPt.Y, 0));
            var scaling = McGeMatrix3d.Scaling(scale, new McGePoint3d(0, 0, 0));

            // Cell insertion point (bottom-left) and center
            McGePoint3d cellOrigin = tblForWrite.GetCellContentPoint(row, col); // API returns base point of content
            double cx = cellOrigin.X + cellWidth / 2.0;
            double cy = cellOrigin.Y + cellHeight / 2.0;

            // After baseToOrigin+scaling, geometry min is at (0,0) and size is (geomW*scale, geomH*scale)
            // We want it centered: offset by half scaled size
            double ox = -0.5 * geomW * scale;
            double oy = -0.5 * geomH * scale;

            var toCenter = McGeMatrix3d.Displacement(new McGeVector3d(cx + ox, cy + oy, 0));

            var fullXform = baseToOrigin * scaling * toCenter;

            // Apply transform to each entity in the block
            foreach (var id in btr)
            {
                var ent = (McDbEntity)tr.GetObject(id, McDbOpenMode.ForWrite, false);
                ent.TransformBy(fullXform);
            }

            // Create or reuse a block reference for the cell
            // Many table APIs allow setting a block name as cell content directly
            tblForWrite.SetCellType(row, col, McTableCellType.Block);
            tblForWrite.SetCellBlock(row, col, blockName, true); // true to allow scaling to cell
            tblForWrite.SetCellAutoScale(row, col, true);

            // Commit transaction
            tr.Commit();
        }
    }
    catch
    {
        // Swallow or rethrow based on your policy; here we rethrow to signal failure to caller
        throw;
    }
}

using System;
using System.Collections.Generic;
using Multicad;
using Multicad.DatabaseServices;
using Multicad.Geometry;
using Multicad.Objects;

public static class TableBlockInserter
{
    // Example EntityGeometry placeholder type assumption:
    // If your project already defines EntityGeometry, remove this and use your existing type.
    public class EntityGeometry
    {
        public string Type; // "Line","Circle","Arc","Polyline","Point","Text","MText"
        public Point3d P1;
        public Point3d P2;
        public double Radius;
        public double StartAngle; // radians
        public double EndAngle;   // radians
        public List<Point3d> PolyPts;
        public bool Closed;
        public string Text;
        public double TextHeight;
        public string StyleName;
    }

    // Inserts or updates a block built from provided geometries and assigns it into McTable[row, col].
    public static bool InsertBlockIntoTableCell(McTable table, int row, int col, List<EntityGeometry> geometries, string blockName)
    {
        try
        {
            // Minimal input validation
            if (table == null) return false;
            if (row < 0 || col < 0 || row >= table.RowsCount || col >= table.ColumnsCount) return false;
            if (geometries == null || geometries.Count == 0) return false;
            if (string.IsNullOrWhiteSpace(blockName)) blockName = "GEOM_CELL_BLOCK";

            using (var tr = new Transaction())
            {
                tr.Start();

                // Get/ensure BlockTable
                var db = HostMgd.ApplicationServices.Core.Application.DocumentManager.MdiActiveDocument?.Database;
                if (db == null)
                {
                    tr.Abort();
                    return false;
                }

                // Open BlockTable
                var btId = db.BlockTableId;
                var bt = (BlockTable)tr.GetObject(btId, OpenMode.ForRead);

                // Create or get BlockTableRecord
                ObjectId btrId;
                if (bt.Has(blockName))
                {
                    btrId = bt[blockName];
                    // Clear existing entities (update block)
                    var btrUpd = (BlockTableRecord)tr.GetObject(btrId, OpenMode.ForWrite);
                    var toErase = new List<ObjectId>();
                    foreach (ObjectId entId in btrUpd)
                        toErase.Add(entId);
                    foreach (var id in toErase)
                    {
                        var ent = (Entity)tr.GetObject(id, OpenMode.ForWrite);
                        ent.Erase();
                    }
                }
                else
                {
                    // Create new block record
                    var btrNew = new BlockTableRecord { Name = blockName };
                    bt.UpgradeOpen();
                    btrId = bt.Add(btrNew);
                    tr.AddNewlyCreatedDBObject(btrNew, true);
                }

                // Open block for write to add entities
                var btr = (BlockTableRecord)tr.GetObject(btrId, OpenMode.ForWrite);

                // Convert geometries to McDbEntity (Entity in DatabaseServices) and add to block
                var bbox = new Extents3d();
                bool bboxInit = false;

                foreach (var g in geometries)
                {
                    if (g == null || string.IsNullOrEmpty(g.Type)) continue;

                    Entity ent = null;
                    switch (g.Type)
                    {
                        case "Line":
                            ent = new Line(g.P1, g.P2);
                            break;

                        case "Circle":
                            ent = new Circle(g.P1, Vector3d.ZAxis, g.Radius);
                            break;

                        case "Arc":
                            {
                                var arc = new Arc(g.P1, g.Radius, g.StartAngle, g.EndAngle);
                                ent = arc;
                                break;
                            }

                        case "Polyline":
                            {
                                var pl = new Polyline();
                                if (g.PolyPts != null)
                                {
                                    for (int i = 0; i < g.PolyPts.Count; i++)
                                    {
                                        var pt = g.PolyPts[i];
                                        pl.AddVertexAt(i, new Point2d(pt.X, pt.Y), 0.0, 0.0, 0.0);
                                    }
                                }
                                pl.Closed = g.Closed;
                                ent = pl;
                                break;
                            }

                        case "Point":
                            ent = new DBPoint(g.P1);
                            break;

                        case "Text":
                            {
                                var dbt = new DBText
                                {
                                    Position = g.P1,
                                    TextString = g.Text ?? string.Empty,
                                    Height = g.TextHeight > 0 ? g.TextHeight : 2.5
                                };
                                if (!string.IsNullOrWhiteSpace(g.StyleName))
                                {
                                    var tsId = EnsureTextStyle(tr, db, g.StyleName);
                                    if (!tsId.IsNull) dbt.TextStyleId = tsId;
                                }
                                ent = dbt;
                                break;
                            }

                        case "MText":
                            {
                                var mt = new MText
                                {
                                    Location = g.P1,
                                    Contents = g.Text ?? string.Empty,
                                    TextHeight = g.TextHeight > 0 ? g.TextHeight : 2.5,
                                    Attachment = AttachmentPoint.MiddleCenter
                                };
                                if (!string.IsNullOrWhiteSpace(g.StyleName))
                                {
                                    var tsId = EnsureTextStyle(tr, db, g.StyleName);
                                    if (!tsId.IsNull) mt.TextStyleId = tsId;
                                }
                                ent = mt;
                                break;
                            }
                    }

                    if (ent == null) continue;

                    btr.AppendEntity(ent);
                    tr.AddNewlyCreatedDBObject(ent, true);

                    try
                    {
                        var ext = ent.GeometricExtents;
                        if (!bboxInit)
                        {
                            bbox = ext;
                            bboxInit = true;
                        }
                        else
                        {
                            bbox.AddExtents(ext);
                        }
                    }
                    catch
                    {
                        // Some entities may not have extents until regenerated; ignore.
                    }
                }

                // If no valid entities were created, abort
                if (!bboxInit)
                {
                    tr.Abort();
                    return false;
                }

                // Create or reuse a block reference to place into the table cell
                // Determine cell rectangle in WCS
                var cellRect = table.GetCellExtents(row, col); // Extents3d in WCS for the cell
                var cellWidth = cellRect.MaxPoint.X - cellRect.MinPoint.X;
                var cellHeight = cellRect.MaxPoint.Y - cellRect.MinPoint.Y;
                if (cellWidth <= 0 || cellHeight <= 0)
                {
                    tr.Abort();
                    return false;
                }

                // Compute block content extents size
                var contentWidth = bbox.MaxPoint.X - bbox.MinPoint.X;
                var contentHeight = bbox.MaxPoint.Y - bbox.MinPoint.Y;
                if (contentWidth <= 1e-9 || contentHeight <= 1e-9)
                {
                    tr.Abort();
                    return false;
                }

                // Scale to fit while preserving aspect ratio, with small margin
                double marginFactor = 0.9;
                double sx = (cellWidth * marginFactor) / contentWidth;
                double sy = (cellHeight * marginFactor) / contentHeight;
                double scale = Math.Min(sx, sy);

                // Base point to align: use bbox center mapped to cell center
                var contentCenter = new Point3d(
                    (bbox.MinPoint.X + bbox.MaxPoint.X) * 0.5,
                    (bbox.MinPoint.Y + bbox.MaxPoint.Y) * 0.5,
                    0.0);

                var cellCenter = new Point3d(
                    (cellRect.MinPoint.X + cellRect.MaxPoint.X) * 0.5,
                    (cellRect.MinPoint.Y + cellRect.MaxPoint.Y) * 0.5,
                    0.0);

                // Insert the block reference in ModelSpace and transform it
                var msId = bt[BlockTableRecord.ModelSpace];
                var ms = (BlockTableRecord)tr.GetObject(msId, OpenMode.ForWrite);

                var br = new BlockReference(Point3d.Origin, btrId);
                ms.AppendEntity(br);
                tr.AddNewlyCreatedDBObject(br, true);

                // Transform: move contentCenter to origin, scale, rotate if needed (none), move to cellCenter
                var toOrigin = Matrix3d.Displacement(Point3d.Origin - contentCenter);
                var scaleMat = Matrix3d.Scaling(scale, Point3d.Origin);
                var toCell = Matrix3d.Displacement(cellCenter - Point3d.Origin);
                br.TransformBy(toOrigin * scaleMat * toCell);

                // Assign block reference to the table cell
                // nanoCAD McTable supports content as BlockReference via Cell.Content.SetBlock
                var cell = table[row, col];
                if (cell == null)
                {
                    tr.Abort();
                    return false;
                }

                // Ensure cell uses block content and set reference
                cell.Content.Type = TableCellContentType.Block;
                cell.Content.SetBlock(br.ObjectId, true); // true = fit to cell if supported

                // Commit all
                tr.Commit();
                return true;
            }
        }
        catch
        {
            return false;
        }
    }

    // Ensures a text style with the given name exists; returns its ObjectId.
    private static ObjectId EnsureTextStyle(Transaction tr, Database db, string styleName)
    {
        var tsId = ObjectId.Null;
        var ts = (TextStyleTable)tr.GetObject(db.TextStyleTableId, OpenMode.ForRead);
        if (ts.Has(styleName))
        {
            tsId = ts[styleName];
        }
        else
        {
            ts.UpgradeOpen();
            var rec = new TextStyleTableRecord { Name = styleName };
            tsId = ts.Add(rec);
            tr.AddNewlyCreatedDBObject(rec, true);
        }
        return tsId;
    }
}

Below are complete, self-contained additions you can paste into TennisGame.html only. They implement the Front Page registration, login, and game description areas, styled to match a tennis-court vibe, and they will automatically hide once a user is signed in so gameplay can begin.

Where to place the snippets in TennisGame.html:
- CSS: Insert the first snippet inside the <head> section, before </head>.
- HTML: Insert the second snippet immediately after the opening <body> tag, before your game canvas/elements.
- JavaScript: Insert the third snippet just before the closing </body> tag, after your game scripts so we can call into your game if available.

Note: This uses localStorage/sessionStorage for demo authentication (no backend). After a successful sign in, the overlay hides and we call an existing startGame()/initGame() function if found, and also dispatch a frontpage:authenticated event you can listen for in your game code if needed.

