<!-- TennisGame.html (add just before </body>) -->
<script>
  (function () {
    const $ = (sel) => document.querySelector(sel);

    // Elements
    const overlay = $('#fp-overlay');
    const tabLogin = $('#fp-tab-login');
    const tabRegister = $('#fp-tab-register');
    const paneLogin = $('#fp-pane-login');
    const paneRegister = $('#fp-pane-register');
    const toRegister = $('#fp-to-register');
    const toLogin = $('#fp-to-login');

    const loginEmail = $('#fp-login-email');
    const loginPassword = $('#fp-login-password');
    const loginSubmit = $('#fp-login-submit');
    const loginError = $('#fp-login-error');

    const regName = $('#fp-reg-name');
    const regEmail = $('#fp-reg-email');
    const regPassword = $('#fp-reg-password');
    const regSubmit = $('#fp-register-submit');
    const regError = $('#fp-register-error');

    const roomIdInput = $('#fp-room-id');
    const joinRoomBtn = $('#fp-join-room');
    const quickMatchBtn = $('#fp-quick-match');

    // Simple in-browser "auth" store for demo
    const storeKey = 'tennis_demo_users';
    const sessionKey = 'tennis_session';
    const readUsers = () => JSON.parse(localStorage.getItem(storeKey) || '{}');
    const writeUsers = (u) => localStorage.setItem(storeKey, JSON.stringify(u));

    function setTab(which) {
      const isLogin = which === 'login';
      tabLogin.classList.toggle('active', isLogin);
      tabRegister.classList.toggle('active', !isLogin);
      tabLogin.setAttribute('aria-selected', isLogin ? 'true' : 'false');
      tabRegister.setAttribute('aria-selected', !isLogin ? 'true' : 'false');
      paneLogin.style.display = isLogin ? '' : 'none';
      paneRegister.style.display = isLogin ? 'none' : '';
      // reset errors
      loginError.textContent = '';
      regError.textContent = '';
    }

    function signIn(user, pairing) {
      // Persist session
      sessionStorage.setItem(sessionKey, JSON.stringify({ email: user.email, name: user.name, pairing }));
      document.body.classList.add('fp-authenticated');
      overlay.setAttribute('aria-hidden', 'true');

      // Notify game layer
      const evt = new CustomEvent('frontpage:authenticated', { detail: { user, pairing }});
      window.dispatchEvent(evt);

      // Try calling game starters if present
      if (typeof window.startGame === 'function') {
        try { window.startGame(pairing); } catch (_) {}
      } else if (typeof window.initGame === 'function') {
        try { window.initGame(pairing); } catch (_) {}
      }
    }

    function validateEmail(v) {
      return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(v);
    }

    // Tab handlers
    tabLogin.addEventListener('click', () => setTab('login'));
    tabRegister.addEventListener('click', () => setTab('register'));
    toRegister.addEventListener('click', () => setTab('register'));
    toLogin.addEventListener('click', () => setTab('login'));

    // Registration
    paneRegister.addEventListener('submit', (e) => {
      e.preventDefault();
      regError.textContent = '';

      const name = regName.value.trim();
      const email = regEmail.value.trim().toLowerCase();
      const password = regPassword.value;

      if (!name) return (regError.textContent = 'Please enter a display name.');
      if (!validateEmail(email)) return (regError.textContent = 'Please enter a valid email.');
      if ((password || '').length < 6) return (regError.textContent = 'Password must be at least 6 characters.');

      const users = readUsers();
      if (users[email]) {
        regError.textContent = 'An account with this email already exists.';
        return;
      }

      users[email] = { email, name, password };
      writeUsers(users);

      // Auto-login after registration
      setTab('login');
      loginEmail.value = email;
      loginPassword.value = password;
      loginError.textContent = 'Account created. You can log in now.';
    });

    // Login
    paneLogin.addEventListener('submit', (e) => {
      e.preventDefault();
      loginError.textContent = '';

      const email = loginEmail.value.trim().toLowerCase();
      const password = loginPassword.value;

      if (!validateEmail(email)) return (loginError.textContent = 'Please enter a valid email.');
      if (!password) return (loginError.textContent = 'Please enter your password.');

      const users = readUsers();
      const user = users[email];
      if (!user || user.password !== password) {
        loginError.textContent = 'Invalid email or password.';
        return;
      }

      // Default pairing if user just logs in (no explicit choice)
      const pairing = { mode: 'login-only', roomId: null, matched: false };
      signIn(user, pairing);
    });

    // Pairing buttons (work after fields filled or after login)
    function ensureAuthOrInlineLogin(cb) {
      // If already authenticated, run callback directly
      const sess = sessionStorage.getItem(sessionKey);
      if (sess) {
        const s = JSON.parse(sess);
        const users = readUsers();
        const user = users[s.email] || { email: s.email, name: s.name || 'Player' };
        return cb(user);
      }

      // Otherwise, try to login with form fields
      const email = loginEmail.value.trim().toLowerCase();
      const password = loginPassword.value;
      const users = readUsers();
      const user = users[email];

      if (!validateEmail(email) || !password || !user || user.password !== password) {
        loginError.textContent = 'Please log in first (fill email/password), then choose a pairing option.';
        return;
      }
      cb(user);
    }

    joinRoomBtn.addEventListener('click', () => {
      const rid = (roomIdInput.value || '').trim();
      if (!rid) {
        loginError.textContent = 'Enter a Room ID to join a private room.';
        return;
      }
      ensureAuthOrInlineLogin((user) => {
        signIn(user, { mode: 'private', roomId: rid, matched: true });
      });
    });

    quickMatchBtn.addEventListener('click', () => {
      ensureAuthOrInlineLogin((user) => {
        // Simple mock matchmaking token
        const token = 'QM-' + Math.random().toString(36).slice(2, 8).toUpperCase();
        signIn(user, { mode: 'matchmaking', roomId: token, matched: true });
      });
    });

    // Restore session if present (skip overlay)
    try {
      const existing = sessionStorage.getItem(sessionKey);
      if (existing) {
        const s = JSON.parse(existing);
        document.body.classList.add('fp-authenticated');
        overlay.setAttribute('aria-hidden', 'true');
        // Optionally notify game on reload
        const evt = new CustomEvent('frontpage:authenticated', { detail: { user: { email: s.email, name: s.name }, pairing: s.pairing || null } });
        window.dispatchEvent(evt);
      }
    } catch (_) {}
  })();
