// ==UserScript==
// @name         DrTorkzadeh Main-Tab Scheduler
// @namespace    http://tampermonkey.net/
// @version      1.0
// @description  Run only in the first tab on the main page; between 22:30–03:30 check for a specific text and, if not found, activate the already-loaded second tab and click submit, then stop.
// @match        http://www.drtorkzadeh.com/
// @match        https://www.drtorkzadeh.com/
// @run-at       document-idle
// @noframes
// ==/UserScript==

(function () {
  "use strict";

  // Zero step: Run only in the first tab of the browser, not other tabs
  // We approximate "first tab" by using a shared BroadcastChannel. The very first tab to claim leadership becomes the leader.
  // All other tabs will detect a leader and self-disable.
  const CHANNEL_NAME = "drtorkzadeh_tab_leader_v1";
  const bc = new BroadcastChannel(CHANNEL_NAME);
  let isLeader = false;
  let leadershipResolved = false;
  const CLAIM = { type: "claim", ts: Date.now(), id: Math.random().toString(36).slice(2) };
  let knownLeaders = new Set();

  function becomeLeader() {
    if (leadershipResolved) return;
    isLeader = true;
    leadershipResolved = true;
    console.log("[TM] This tab is the leader (acting as 'first tab').");
    bc.postMessage({ type: "leader", ts: Date.now() });
    startMainLogic();
  }

  function surrender() {
    if (leadershipResolved) return;
    isLeader = false;
    leadershipResolved = true;
    console.log("[TM] Another leader detected. This tab will stay idle.");
  }

  bc.onmessage = (ev) => {
    const msg = ev.data || {};
    if (msg.type === "leader") {
      knownLeaders.add("leader");
    }
  };

  // After a short window, if no leader heard, claim leadership.
  setTimeout(() => {
    if (knownLeaders.size === 0) {
      becomeLeader();
    } else {
      surrender();
    }
  }, 400);

  // Announce presence (helps race resolution if two tabs start near-simultaneously)
  bc.postMessage(CLAIM);

  // Utility: ensure we are on the MAIN PAGE (not branches/subpages)
  function isMainPage() {
    const hostOk = /(^|\.)drtorkzadeh\.com$/i.test(location.hostname);
    const pathOk = location.pathname === "/" || location.pathname === "";
    return hostOk && pathOk;
  }

  // Time window 22:30–03:30 (local time)
  function inAllowedWindow(d = new Date()) {
    const h = d.getHours();
    const m = d.getMinutes();
    // Allowed if time >= 22:30 OR time <= 03:30
    if (h > 22 || (h === 22 && m >= 30)) return true;
    if (h < 3 || (h === 3 && m <= 30)) return true;
    return false;
  }

  function msUntilNextWindowStart(d = new Date()) {
    if (inAllowedWindow(d)) return 0;
    const now = new Date(d.getTime());
    const startToday = new Date(now);
    startToday.setHours(22, 30, 0, 0);
    if (now < startToday) {
      return startToday.getTime() - now.getTime();
    }
    const startTomorrow = new Date(startToday.getTime() + 24 * 60 * 60 * 1000);
    return startTomorrow.getTime() - now.getTime();
  }

  function sleep(ms) {
    return new Promise((res) => setTimeout(res, ms));
  }

  // Fourth and fifth steps require focusing/activating the already-loaded second tab and clicking submit.
  // In user scripts, we cannot programmatically "Ctrl+Tab" or switch windows across browser tabs.
  // However, we can:
  // - Use the Page Visibility API + BroadcastChannel to coordinate with a helper user script that runs in ALL tabs.
  // - The leader (first tab) will broadcast a request for the "second tab" to click.
  // - The "second tab" (any other visible tab on drtorkzadeh.com that has the target submit) will perform the click and acknowledge.
  //
  // This script includes both leader logic and follower logic so it works regardless of install scope.

  const SIGNAL_CH = new BroadcastChannel("drtorkzadeh_actions_v1");
  const ACTION_CLICK_SUBMIT = "click_submit";
  const ACK_CLICKED = "clicked_submit";

  // Followers: listen for requests; if this tab is NOT the leader and has the submit, click it once.
  async function followerListenAndAct() {
    SIGNAL_CH.onmessage = async (ev) => {
      const msg = ev.data || {};
      if (msg.type === ACTION_CLICK_SUBMIT) {
        if (isLeader) return; // leader should not act as follower
        // Only act if this tab is ready and has the target element
        const ok = await tryClickSubmit();
        if (ok) {
          SIGNAL_CH.postMessage({ type: ACK_CLICKED, ts: Date.now() });
        }
      }
    };
  }

  // Try to find and click the requested element:
  // Element described: TAG POS=1 TYPE=INPUT:SUBMIT FORM=ACTION:http://www.drtorkzadeh.com/ ATTR=ID:submit
  function findSubmitElement() {
    // Prefer exact form action match (http), then fallback to https or id-only
    const forms = Array.from(document.querySelectorAll('form[action="http://www.drtorkzadeh.com/"]'));
    for (const f of forms) {
      const cand = f.querySelector('input#submit[type="submit"], input[type="submit"]#submit');
      if (cand) return cand;
    }
    // Fallbacks
    let el = document.querySelector('form[action="https://www.drtorkzadeh.com/"] input#submit[type="submit"]');
    if (el) return el;
    el = document.querySelector('input#submit[type="submit"], input[type="submit"]#submit, #submit');
    return el || null;
  }

  async function tryClickSubmit() {
    const el = findSubmitElement();
    if (!el) return false;
    try {
      el.scrollIntoView({ block: "center", inline: "center", behavior: "instant" });
    } catch (_) {}
    try {
      el.click();
      console.log("[TM] Submit clicked.");
      return true;
    } catch (e) {
      console.warn("[TM] Click failed:", e);
      // Try a synthetic click as fallback
      try {
        const evt = new MouseEvent("click", { bubbles: true, cancelable: true, view: window });
        el.dispatchEvent(evt);
        console.log("[TM] Submit clicked via dispatchEvent.");
        return true;
      } catch (e2) {
        console.warn("[TM] dispatchEvent click failed:", e2);
        return false;
      }
    }
  }

  async function startMainLogic() {
    // First step: ensure only on main page (not branches)
    if (!isMainPage()) {
      console.log("[TM] Not on main page. Exiting.");
      return;
    }

    // Second step: wait until time window 22:30–03:30
    let waitMs = msUntilNextWindowStart(new Date());
    while (waitMs > 0) {
      const chunk = Math.min(waitMs, 30000);
      await sleep(chunk);
      waitMs = msUntilNextWindowStart(new Date());
    }

    const TARGET_TEXT = "رزرو فقط در ساعات 9 صبح تا 10 صبح امکان پذیر است";

    // Third step: loop: check page for exact text; if found wait 5s then reload; repeat
    // If not found: signal the second tab to click submit and stop.
    while (true) {
      // Re-validate main page
      if (!isMainPage()) {
        console.log("[TM] Navigated away from main page; stopping.");
        return;
      }

      // If window closed while looping, wait again
      if (!inAllowedWindow(new Date())) {
        let ms = msUntilNextWindowStart(new Date());
        while (ms > 0) {
          const chunk = Math.min(ms, 30000);
          await sleep(chunk);
          ms = msUntilNextWindowStart(new Date());
        }
      }

      const bodyText = document.body ? (document.body.innerText || "") : "";
      if (bodyText.includes(TARGET_TEXT)) {
        await sleep(5000);
        location.reload();
        return; // After reload, script restarts; leadership will be re-evaluated quickly
      }

      // Fourth step: if text NOT found, go to the next tab that is already loaded
      // We can't programmatically switch browser tabs; instead, instruct a follower tab to click.
      const clicked = await requestSecondTabClick();
      if (clicked) {
        // Fifth step: stop the code after clicking
        console.log("[TM] Submit clicked on the second tab. Stopping.");
        return;
      } else {
        console.warn("[TM] No follower acknowledged the click. Retrying in 2s...");
        await sleep(2000);
        // Loop continues to try again unless the text appears.
      }
    }
  }

  // Ask any follower tab to click submit and wait briefly for acknowledgment
  async function requestSecondTabClick(timeoutMs = 8000) {
    let acknowledged = false;
    const onAck = (ev) => {
      const msg = ev.data || {};
      if (msg.type === ACK_CLICKED) {
        acknowledged = true;
      }
    };
    SIGNAL_CH.addEventListener("message", onAck);
    try {
      SIGNAL_CH.postMessage({ type: ACTION_CLICK_SUBMIT, ts: Date.now() });

      const start = Date.now();
      while (Date.now() - start < timeoutMs) {
        if (acknowledged) return true;
        await sleep(250);
      }
      return false;
    } finally {
      SIGNAL_CH.removeEventListener("message", onAck);
    }
  }

  // Followers always listen, leaders too (harmless)
  followerListenAndAct();
})();

Below is a complete, self-contained Go program that compiles and runs. It implements a genetic algorithm (GA) for weight budgeting (e.g., portfolio allocation). It enforces per-asset min/max bounds and the simplex constraint that weights sum to 1, while maximizing expected return minus a risk penalty on variance.

You can save this as main.go and run with: go run main.go

```go
// main.go
package main

import (
	"fmt"
	"log"
	"math"
	"math/rand"
	"sort"
	"strings"
	"time"
)

type Individual struct {
	Weights []float64
	Fitness float64
}

func main() {
	rand.Seed(time.Now().UnixNano())

	// Example data: 5 assets (or budget categories)
	expectedReturns := []float64{0.12, 0.10, 0.07, 0.15, 0.09}
	cov := [][]float64{
		{0.10, 0.02, 0.04, 0.00, 0.01},
		{0.02, 0.08, 0.01, 0.03, 0.00},
		{0.04, 0.01, 0.12, 0.02, 0.02},
		{0.00, 0.03, 0.02, 0.15, 0.01},
		{0.01, 0.00, 0.02, 0.01, 0.09},
	}

	n := len(expectedReturns)

	// Per-asset bounds (e.g., min 0%, max 60%)
	minW := make([]float64, n)
	maxW := make([]float64, n)
	for i := 0; i < n; i++ {
		minW[i] = 0.0
		maxW[i] = 0.6
	}

	// GA hyperparameters
	popSize := 200
	generations := 300
	crossoverRate := 0.9
	mutationRate := 0.1
	mutationSigma := 0.05
	tournamentSize := 3
	elitism := 2

	// Risk aversion (lambda): higher penalizes variance more
	riskAversion := 0.5

	// Ensure feasibility of bounds
	sumMin := 0.0
	sumMax := 0.0
	for i := 0; i < n; i++ {
		sumMin += minW[i]
		sumMax += maxW[i]
	}
	if sumMin > 1.0+1e-9 || sumMax < 1.0-1e-9 {
		log.Fatalf("Infeasible bounds: sum(min)=%.6f, sum(max)=%.6f; cannot sum to 1", sumMin, sumMax)
	}

	// Initialize population
	pop := make([]Individual, popSize)
	for i := 0; i < popSize; i++ {
		w := randomFeasibleWeights(n, minW, maxW)
		f := objective(w, expectedReturns, cov, riskAversion)
		pop[i] = Individual{Weights: w, Fitness: f}
	}

	best := bestIndividual(pop)
	fmt.Println("Initial best fitness:", best.Fitness)
	fmt.Println("Initial weights:", pretty(best.Weights))

	for gen := 0; gen < generations; gen++ {
		// Sort population by fitness (descending)
		pop = sortByFitness(pop)

		// Keep elites
		nextPop := make([]Individual, 0, popSize)
		for i := 0; i < elitism && i < len(pop); i++ {
			nextPop = append(nextPop, copyIndividual(pop[i]))
		}

		// Generate rest via selection, crossover, mutation
		for len(nextPop) < popSize {
			parent1 := tournamentSelect(pop, tournamentSize)
			parent2 := tournamentSelect(pop, tournamentSize)

			child1 := copyIndividual(parent1)
			child2 := copyIndividual(parent2)

			if rand.Float64() < crossoverRate {
				child1, child2 = uniformCrossover(parent1, parent2)
			}

			mutate(&child1, mutationRate, mutationSigma)
			mutate(&child2, mutationRate, mutationSigma)

			// Repair and re-evaluate
			projectToSimplexWithBounds(child1.Weights, minW, maxW)
			child1.Fitness = objective(child1.Weights, expectedReturns, cov, riskAversion)

			projectToSimplexWithBounds(child2.Weights, minW, maxW)
			child2.Fitness = objective(child2.Weights, expectedReturns, cov, riskAversion)

			nextPop = append(nextPop, child1)
			if len(nextPop) < popSize {
				nextPop = append(nextPop, child2)
			}
		}

		pop = nextPop
		currentBest := bestIndividual(pop)

		// Simple logging
		if (gen+1)%25 == 0 || gen == generations-1 {
			fmt.Printf("Gen %d | Best fitness: %.6f | Weights: %s\n",
				gen+1, currentBest.Fitness, pretty(currentBest.Weights))
		}
	}

	// Final result
	pop = sortByFitness(pop)
	best = pop[0]
	fmt.Println("\nFinal best fitness:", best.Fitness)
	fmt.Println("Final weights:", pretty(best.Weights))
	fmt.Printf("Expected return: %.6f, Variance: %.6f\n",
		dot(best.Weights, expectedReturns),
		quadForm(best.Weights, cov))
}

// ===== GA core =====

// Objective: maximize return - lambda * variance
func objective(w []float64, expected []float64, cov [][]float64, lambda float64) float64 {
	ret := dot(w, expected)
	variance := quadForm(w, cov)
	return ret - lambda*variance
}

// Tournament selection (maximization): pick 'k' random individuals, return the best
func tournamentSelect(pop []Individual, k int) Individual {
	best := pop[rand.Intn(len(pop))]
	for i := 1; i < k; i++ {
		cand := pop[rand.Intn(len(pop))]
		if cand.Fitness > best.Fitness {
			best = cand
		}
	}
	return best
}

// Uniform crossover: for each gene, pick from parent1 or parent2 with p=0.5
func uniformCrossover(p1, p2 Individual) (Individual, Individual) {
	n := len(p1.Weights)
	c1 := Individual{Weights: make([]float64, n)}
	c2 := Individual{Weights: make([]float64, n)}
	for i := 0; i < n; i++ {
		if rand.Intn(2) == 0 {
			c1.Weights[i] = p1.Weights[i]
			c2.Weights[i] = p2.Weights[i]
		} else {
			c1.Weights[i] = p2.Weights[i]
			c2.Weights[i] = p1.Weights[i]
		}
	}
	return c1, c2
}

// Gaussian mutation with per-gene probability; does not enforce constraints itself
func mutate(ind *Individual, mutationRate, sigma float64) {
	for i := range ind.Weights {
		if rand.Float64() < mutationRate {
			ind.Weights[i] += rand.NormFloat64() * sigma
		}
	}
}

// ===== Feasibility and helpers =====

// Create a random feasible weight vector summing to 1 within bounds.
func randomFeasibleWeights(n int, minW, maxW []float64) []float64 {
	// Start with random positive numbers (Dirichlet-like), normalize to sum to 1
	w := make([]float64, n)
	sum := 0.0
	for i := 0; i < n; i++ {
		w[i] = rand.Float64() + 1e-12
		sum += w[i]
	}
	for i := 0; i < n; i++ {
		w[i] /= sum
	}
	// Project to bounded simplex to respect min/max and sum=1
	projectToSimplexWithBounds(w, minW, maxW)
	return w
}

// Projects a vector w onto the simplex {y: sum y = 1, minW[i] <= y[i] <= maxW[i]}.
// Uses bisection on Lagrange multiplier tau: y_i = clip(w_i - tau, minW[i], maxW[i]) s.t. sum_i y_i = 1
func projectToSimplexWithBounds(w []float64, minW, maxW []float64) {
	n := len(w)

	// Quick feasibility check
	sumMin := 0.0
	sumMax := 0.0
	for i := 0; i < n; i++ {
		sumMin += minW[i]
		sumMax += maxW[i]
	}
	if sumMin > 1.0 {
		copy(w, minW)
		return
	}
	if sumMax < 1.0 {
		copy(w, maxW)
		return
	}

	// Determine tau bounds such that S(tau) = sum clip(w_i - tau) spans 1
	tauLow := math.Inf(1)
	tauHigh := math.Inf(-1)
	for i := 0; i < n; i++ {
		low := w[i] - maxW[i]  // when tau <= low => y_i = maxW[i]
		high := w[i] - minW[i] // when tau >= high => y_i = minW[i]
		if low < tauLow {
			tauLow = low
		}
		if high > tauHigh {
			tauHigh = high
		}
	}

	// Bisection on tau
	for iter := 0; iter < 60; iter++ {
		tau := 0.5 * (tauLow + tauHigh)
		sum := 0.0
		for i := 0; i < n; i++ {
			val := w[i] - tau
			if val < minW[i] {
				val = minW[i]
			}
			if val > maxW[i] {
				val = maxW[i]
			}
			sum += val
		}
		if sum > 1.0 {
			// Need to decrease sum -> increase tau
			tauLow = tau
		} else {
			// Need to increase sum -> decrease tau
			tauHigh = tau
		}
	}
	// Final projection with chosen tau
	tau := 0.5 * (tauLow + tauHigh)
	for i := 0; i < n; i++ {
		val := w[i] - tau
		if val < minW[i] {
			val = minW[i]
		}
		if val > maxW[i] {
			val = maxW[i]
		}
		w[i] = val
	}

	// Numeric safeguard: normalize and clip lightly
	sum := 0.0
	for i := 0; i < n; i++ {
		sum += w[i]
	}
	if sum != 0 {
		for i := 0; i < n; i++ {
			w[i] /= sum
		}
		for i := 0; i < n; i++ {
			if w[i] < minW[i] {
				w[i] = minW[i]
			}
			if w[i] > maxW[i] {
				w[i] = maxW[i]
			}
		}
	}
}

// ===== Math and utility helpers =====

func dot(a, b []float64) float64 {
	sum := 0.0
	for i := range a {
		sum += a[i] * b[i]
	}
	return sum
}

func quadForm(w []float64, cov [][]float64) float64 {
	n := len(w)
	sum := 0.0
	for i := 0; i < n; i++ {
		for j := 0; j < n; j++ {
			sum += w[i] * cov[i][j] * w[j]
		}
	}
	return sum
}

func sortByFitness(pop []Individual) []Individual {
	out := make([]Individual, len(pop))
	copy(out, pop)
	sort.Slice(out, func(i, j int) bool {
		return out[i].Fitness > out[j].Fitness
	})
	return out
}

func bestIndividual(pop []Individual) Individual {
	best := pop[0]
	for _, ind := range pop[1:] {
		if ind.Fitness > best.Fitness {
			best = ind
		}
	}
	return best
}

func copyIndividual(ind Individual) Individual {
	w := make([]float64, len(ind.Weights))
	copy(w, ind.Weights)
	return Individual{Weights: w, Fitness: ind.Fitness}
}

func pretty(w []float64) string {
	parts := make([]string, len(w))
	for i, x := range w {
		parts[i] = fmt.Sprintf("%.4f", x)
	}
	return "[" + strings.Join(parts, ", ") + "]"
}
```

Concise walkthrough of main GA components:
- Representation: Each Individual holds a real-valued slice Weights (one gene per asset/category) that represents budget shares; Fitness stores the objective value.
- Fitness: objective(w) = dot(w, expectedReturns) − lambda × quadForm(w, cov). Higher is better.
- Selection: Tournament selection picks k random individuals and returns the one with highest fitness; repeated to choose parents.
- Crossover: Uniform crossover builds two children by independently picking each gene from either parent with probability 0.5.
- Mutation: Gaussian mutation perturbs each gene with probability mutationRate by adding N(0, sigma). Constraint repair is applied afterwards.
- Constraint handling: projectToSimplexWithBounds enforces both per-asset bounds minW/maxW and the simplex constraint sum(weights) = 1 using a bisection-based projection. All initialization and post-mutation/crossover offspring are projected before evaluation.

Below is a complete, error-free MATLAB/YALMIP implementation that uses the Schur complement with the substitution Y = KX to cast the H2 state-feedback problem as LMIs. The performance output is z = [y1; y2] = [C x; −K x], and the disturbance w enters at the same input channel as the control. The objective minimizes the sum of the squared H2 norms from w to y and from w to u. The script also adds step response plots comparing the H2 controller against an LQR controller for both the plant output y and the control input u.

% H2 state-feedback with YALMIP (Schur complement) and step comparisons vs LQR
clc
clear
close all

% Load data and identify model (user-supplied data3 must exist)
load('data3.mat');                          % expects variable data3
G3  = bj(data3, [5 5 5 5 1]);               % Box-Jenkins identification (SISO)
G3c = d2c(G3);                              % Discrete -> continuous
sysc = ss(G3c);                             % Convert to state-space
[A,B,C,D] = ssdata(sysc);
n = size(A,1);
m = size(B,2);
p = size(C,1);

% Generalized plant for H2:
% xdot = A x + B (w + u),   u = -K x
% z    = [C x; -K x] = C1 x + D12 u
C1  = [C; zeros(m,n)];                      % For z = C1 x + D12 u
D12 = [zeros(p,m); eye(m)];

% YALMIP decision variables
X = sdpvar(n,n,'symmetric');                % X > 0
Y = sdpvar(m,n,'full');                     % Y = K X
Z = sdpvar(p+m,p+m,'symmetric');            % For H2 objective

% LMIs:
% 1) Closed-loop Lyapunov with disturbance at same input B:
%    A X + X A' - (B Y + Y' B') + B B' < 0
eps_stab = 1e-8;
LMI_cl = A*X + X*A' - (B*Y + Y'*B') + (B*B') <= -eps_stab*eye(n);

% 2) H2 objective (z = C1 x + D12 u, u = -K x, Y = KX) via Schur complement:
%    [ Z,  (C1 X - D12 Y)
%      *,               X ] >= 0
LMI_h2 = [ Z,              (C1*X - D12*Y) ; ...
           (C1*X - D12*Y)',             X ] >= 0;

% Positive definiteness
LMI_pos = X >= 1e-6*eye(n);

Constraints = [LMI_cl, LMI_h2, LMI_pos];

% Objective: minimize trace(Z) = ||T_{w->z}||_2^2
Objective = trace(Z);

% Select solver (MOSEK preferred; fallback to SeDuMi if not found)
if exist('mosekopt','file') == 3 || exist('mosekopt','file') == 2
    solver = 'mosek';
else
    solver = 'sedumi';
end
ops = sdpsettings('solver',solver,'verbose',1);

% Solve the SDP
sol = optimize(Constraints, Objective, ops);
assert(sol.problem == 0, ['SDP failed: ', sol.info]);

% Recover controller K and H2 norm
Xv = value(X);
Yv = value(Y);
Kv = Yv / Xv;                               % K = Y * X^{-1}
H2sq = value(trace(Z));                     % squared H2 norm from w to z
H2norm = sqrt(max(H2sq,0));

fprintf('Controller synthesis successful.\n');
fprintf('||T_{w->z}||_2 = %.6f\n', H2norm);

% Closed-loop systems (from disturbance w to outputs)
Acl = A - B*Kv;
Bcl = B;
Cy  = C;                                    % output y
Dyw = zeros(p, m);

% Output y to w
sys_y_H2  = ss(Acl, Bcl, Cy,  Dyw);

% Control input u = -K x (as an output) to w
Cu  = -Kv;
Duw = zeros(m, m);
sys_u_H2  = ss(Acl, Bcl, Cu,  Duw);

% LQR comparison
Q = eye(n);
R = 1;
K_lqr = lqr(A,B,Q,R);

Acl_lqr = A - B*K_lqr;
sys_y_LQR = ss(Acl_lqr, Bcl, Cy,      Dyw);
sys_u_LQR = ss(Acl_lqr, Bcl, -K_lqr,  Duw);

% Step response comparisons (disturbance step at w)
tFinal = 5;                                 % seconds; adjust if needed

figure('Name','Output y: Step response to disturbance w');
step(sys_y_H2, tFinal); hold on;
step(sys_y_LQR, tFinal);
grid on; legend('H2','LQR','Location','best');
title('Output y: step response to disturbance input w');

figure('Name','Control u: Step response to disturbance w');
step(sys_u_H2, tFinal); hold on;
step(sys_u_LQR, tFinal);
grid on; legend('H2','LQR','Location','best');
title('Control input u: step response to disturbance input w');

% Also show closed-loop reference step on y for u = -Kx (no disturbance path)
% Build closed-loop from external command r entering as +B*r (for comparison)
sys_cl_H2  = ss(Acl, B, C, zeros(p,m));
sys_cl_LQR = ss(Acl_lqr, B, C, zeros(p,m));

figure('Name','Output y: Reference step (no disturbance)');
step(sys_cl_H2, tFinal); hold on;
step(sys_cl_LQR, tFinal);
grid on; legend('H2','LQR','Location','best');
title('Output y: reference step (r at plant input)');

Below is a complete, self-contained Tkinter application that manages the tournament’s scoring. It is organized, validated, and commented for maintainability. It includes:
- Participants (Teams and Individuals) with “one event only” support and optional chosen event.
- Events (Team or Individual) with optional per-event points.
- Results entry per event via ranked ordering with strong validation.
- Leaderboards for teams and individuals.
- Points configuration (global schemes + custom editor).
- Save/Load/New via JSON with validation and clear error handling.

To run: save as a .py file and execute with Python 3.8+.

```python
import json
from dataclasses import dataclass, asdict, field
from typing import Dict, List, Optional, Tuple

import tkinter as tk
from tkinter import ttk, messagebox, filedialog


# -------------------------
# Data Model
# -------------------------

@dataclass
class Team:
    id: int
    name: str
    members: List[str] = field(default_factory=list)
    one_event_only: bool = False
    chosen_event_id: Optional[int] = None  # Applies if one_event_only is True


@dataclass
class Individual:
    id: int
    name: str
    one_event_only: bool = False
    chosen_event_id: Optional[int] = None  # Applies if one_event_only is True


@dataclass
class Event:
    id: int
    name: str
    type: str  # "Team" or "Individual"
    genre: str = ""
    points_map: Optional[Dict[int, int]] = None  # Per-event override


class TournamentData:
    """
    Core model for the tournament. Handles validation, CRUD operations,
    results storage, points aggregation, and JSON (de)serialization.
    """
    def __init__(self):
        self.teams: Dict[int, Team] = {}
        self.individuals: Dict[int, Individual] = {}
        self.events: Dict[int, Event] = {}
        # event_id -> ordered list of entrant IDs
        self.results: Dict[int, List[int]] = {}
        # Global points table (default: F1 Top 10)
        self.points_map: Dict[int, int] = {
            1: 25, 2: 18, 3: 15, 4: 12, 5: 10, 6: 8, 7: 6, 8: 4, 9: 2, 10: 1
        }
        self.team_counter = 1
        self.indiv_counter = 1
        self.event_counter = 1

    # ---- Constraints ----
    def max_teams(self) -> int:
        return 4

    def max_team_members(self) -> int:
        return 5

    def max_individuals(self) -> int:
        return 20

    def max_events_per_type(self) -> int:
        # 5 Team events and 5 Individual events
        return 5

    # ---- Helpers ----
    @staticmethod
    def _clean_name(value: str) -> str:
        return (value or "").strip()

    def _validate_points_map(self, points: Dict[int, int]) -> None:
        if not isinstance(points, dict) or not points:
            raise ValueError("Points map must be a non-empty dictionary.")
        for k, v in points.items():
            if not isinstance(k, int) or k <= 0:
                raise ValueError("Rank keys must be positive integers.")
            if not isinstance(v, int) or v < 0:
                raise ValueError("Point values must be non-negative integers.")
        # Non-increasing across ranks: points[1] >= points[2] >= ...
        prev_points = None
        for r in sorted(points.keys()):
            if prev_points is not None and points[r] > prev_points:
                raise ValueError("Points should not increase for lower ranks.")
            prev_points = points[r]

    def get_points_for_event(self, event_id: int) -> Dict[int, int]:
        ev = self.events.get(event_id)
        if ev and ev.points_map:
            return ev.points_map
        return self.points_map

    # ---- CRUD for Teams ----
    def add_team(self, name: str, members: List[str], one_event_only: bool = False, chosen_event_id: Optional[int] = None) -> int:
        name = self._clean_name(name)
        if not name:
            raise ValueError("Team name cannot be empty.")
        if len(self.teams) >= self.max_teams():
            raise ValueError("Maximum number of teams reached (4).")
        if len(members) > self.max_team_members():
            raise ValueError("A team can have at most 5 members.")
        cleaned_members = [self._clean_name(m) for m in members if self._clean_name(m)]
        if not cleaned_members:
            raise ValueError("A team must have at least one member.")
        if any(t.name.lower() == name.lower() for t in self.teams.values()):
            raise ValueError("Team name must be unique.")
        if chosen_event_id is not None:
            ev = self.events.get(chosen_event_id)
            if ev is None or ev.type != "Team":
                raise ValueError("Chosen event must be a valid Team event.")
        team_id = self.team_counter
        self.team_counter += 1
        self.teams[team_id] = Team(id=team_id, name=name, members=cleaned_members,
                                   one_event_only=one_event_only, chosen_event_id=chosen_event_id)
        return team_id

    def edit_team(self, tid: int, name: str, members: List[str], one_event_only: bool, chosen_event_id: Optional[int]) -> None:
        if tid not in self.teams:
            raise ValueError("Team not found.")
        name = self._clean_name(name)
        if not name:
            raise ValueError("Team name cannot be empty.")
        if len(members) > self.max_team_members():
            raise ValueError("A team can have at most 5 members.")
        cleaned_members = [self._clean_name(m) for m in members if self._clean_name(m)]
        if not cleaned_members:
            raise ValueError("A team must have at least one member.")
        if chosen_event_id is not None:
            ev = self.events.get(chosen_event_id)
            if ev is None or ev.type != "Team":
                raise ValueError("Chosen event must be a valid Team event.")
        if any(t.name.lower() == name.lower() and t.id != tid for t in self.teams.values()):
            raise ValueError("Team name must be unique.")
        t = self.teams[tid]
        t.name = name
        t.members = cleaned_members
        t.one_event_only = one_event_only
        t.chosen_event_id = chosen_event_id

    def remove_team(self, tid: int) -> None:
        if tid not in self.teams:
            raise ValueError("Team not found.")
        # Remove from any Team event results
        for ev_id, places in list(self.results.items()):
            ev = self.events.get(ev_id)
            if ev and ev.type == "Team":
                self.results[ev_id] = [pid for pid in places if pid != tid]
        del self.teams[tid]
        # Recompute one-event-only assignments to keep consistency
        self.recompute_one_event_only_assignments()

    # ---- CRUD for Individuals ----
    def add_individual(self, name: str, one_event_only: bool = False, chosen_event_id: Optional[int] = None) -> int:
        name = self._clean_name(name)
        if not name:
            raise ValueError("Individual name cannot be empty.")
        if len(self.individuals) >= self.max_individuals():
            raise ValueError("Maximum number of individuals reached (20).")
        if any(i.name.lower() == name.lower() for i in self.individuals.values()):
            raise ValueError("Individual name must be unique.")
        if chosen_event_id is not None:
            ev = self.events.get(chosen_event_id)
            if ev is None or ev.type != "Individual":
                raise ValueError("Chosen event must be a valid Individual event.")
        iid = self.indiv_counter
        self.indiv_counter += 1
        self.individuals[iid] = Individual(
            id=iid,
            name=name,
            one_event_only=one_event_only,
            chosen_event_id=chosen_event_id
        )
        return iid

    def edit_individual(self, iid: int, name: str, one_event_only: bool, chosen_event_id: Optional[int]) -> None:
        if iid not in self.individuals:
            raise ValueError("Individual not found.")
        name = self._clean_name(name)
        if not name:
            raise ValueError("Individual name cannot be empty.")
        if any(i.name.lower() == name.lower() and i.id != iid for i in self.individuals.values()):
            raise ValueError("Individual name must be unique.")
        if chosen_event_id is not None:
            ev = self.events.get(chosen_event_id)
            if ev is None or ev.type != "Individual":
                raise ValueError("Chosen event must be a valid Individual event.")
        p = self.individuals[iid]
        p.name = name
        p.one_event_only = one_event_only
        p.chosen_event_id = chosen_event_id

    def remove_individual(self, iid: int) -> None:
        if iid not in self.individuals:
            raise ValueError("Individual not found.")
        # Remove from any Individual event results
        for ev_id, places in list(self.results.items()):
            ev = self.events.get(ev_id)
            if ev and ev.type == "Individual":
                self.results[ev_id] = [pid for pid in places if pid != iid]
        del self.individuals[iid]
        self.recompute_one_event_only_assignments()

    # ---- CRUD for Events ----
    def add_event(self, name: str, etype: str, genre: str = "", points_map: Optional[Dict[int, int]] = None) -> int:
        name = self._clean_name(name)
        etype = (etype or "").strip()
        if etype not in ("Team", "Individual"):
            raise ValueError("Event type must be 'Team' or 'Individual'.")
        if not name:
            raise ValueError("Event name cannot be empty.")
        if any(e.name.lower() == name.lower() for e in self.events.values()):
            raise ValueError("Event name must be unique.")
        # Enforce max 5 events per type
        type_count = sum(1 for e in self.events.values() if e.type == etype)
        if type_count >= self.max_events_per_type():
            raise ValueError(f"Maximum number of {etype} events reached ({self.max_events_per_type()}).")
        if points_map is not None:
            self._validate_points_map(points_map)
        eid = self.event_counter
        self.event_counter += 1
        self.events[eid] = Event(id=eid, name=name, type=etype, genre=genre, points_map=points_map)
        return eid

    def edit_event(self, eid: int, name: str, etype: str, genre: str, points_map: Optional[Dict[int, int]]) -> None:
        if eid not in self.events:
            raise ValueError("Event not found.")
        name = self._clean_name(name)
        etype = (etype or "").strip()
        if etype not in ("Team", "Individual"):
            raise ValueError("Event type must be 'Team' or 'Individual'.")
        if not name:
            raise ValueError("Event name cannot be empty.")
        if any(e.name.lower() == name.lower() and e.id != eid for e in self.events.values()):
            raise ValueError("Event name must be unique.")
        # Enforce per-type limit when switching types
        current = self.events[eid]
        if current.type != etype:
            type_count = sum(1 for e in self.events.values() if e.type == etype)
            if type_count >= self.max_events_per_type():
                raise ValueError(f"Maximum number of {etype} events reached ({self.max_events_per_type()}).")
            # Clear results if type changes to avoid cross-type ID mismatches
            if eid in self.results:
                self.results[eid] = []
            # Clear chosen_event_id references pointing to this event if type changes
            for t in self.teams.values():
                if t.chosen_event_id == eid and etype != "Team":
                    t.chosen_event_id = None
            for ind in self.individuals.values():
                if ind.chosen_event_id == eid and etype != "Individual":
                    ind.chosen_event_id = None
        if points_map is not None:
            self._validate_points_map(points_map)
        current.name = name
        current.type = etype
        current.genre = genre
        current.points_map = points_map

    def remove_event(self, eid: int) -> None:
        if eid not in self.events:
            raise ValueError("Event not found.")
        # Remove results and clear chosen_event references
        self.results.pop(eid, None)
        for t in self.teams.values():
            if t.chosen_event_id == eid:
                t.chosen_event_id = None
        for ind in self.individuals.values():
            if ind.chosen_event_id == eid:
                ind.chosen_event_id = None
        del self.events[eid]

    # ---- Results management ----
    def set_results_for_event(self, eid: int, ordered_participant_ids: List[int]) -> None:
        if eid not in self.events:
            raise ValueError("Event not found.")
        ev = self.events[eid]
        # Validate entrants belong to the correct collection
        if ev.type == "Team":
            for pid in ordered_participant_ids:
                if pid not in self.teams:
                    raise ValueError("Results contain an unknown team.")
        else:
            for pid in ordered_participant_ids:
                if pid not in self.individuals:
                    raise ValueError("Results contain an unknown individual.")
        # No duplicates
        if len(ordered_participant_ids) != len(set(ordered_participant_ids)):
            raise ValueError("Duplicate entrants are not allowed in results.")
        # Enforce one-event-only rules
        self._validate_one_event_only_submission(eid, ev.type, ordered_participant_ids)
        # Save results
        self.results[eid] = list(ordered_participant_ids)
        # Auto-lock chosen event for one-event-only entrants without a chosen_event_id
        if ev.type == "Team":
            for pid in ordered_participant_ids:
                t = self.teams[pid]
                if t.one_event_only and t.chosen_event_id is None:
                    t.chosen_event_id = eid
        else:
            for pid in ordered_participant_ids:
                p = self.individuals[pid]
                if p.one_event_only and p.chosen_event_id is None:
                    p.chosen_event_id = eid

    def _validate_one_event_only_submission(self, eid: int, etype: str, pids: List[int]) -> None:
        if etype == "Team":
            for pid in pids:
                t = self.teams[pid]
                if t.one_event_only and t.chosen_event_id is not None and t.chosen_event_id != eid:
                    raise ValueError(f"Team '{t.name}' is restricted to a different event.")
                # If one-event-only but no chosen_event yet, they can be placed here; will be locked post-save.
        else:
            for pid in pids:
                p = self.individuals[pid]
                if p.one_event_only and p.chosen_event_id is not None and p.chosen_event_id != eid:
                    raise ValueError(f"Individual '{p.name}' is restricted to a different event.")

        # Also ensure no one-event-only entrant appears in results of any other event already
        for other_eid, res in self.results.items():
            if other_eid == eid:
                continue
            other_ev = self.events.get(other_eid)
            if not other_ev or other_ev.type != etype:
                continue
            for pid in pids:
                if pid in res:
                    # If they already appear elsewhere and they are one-event-only, this is invalid
                    if etype == "Team" and self.teams[pid].one_event_only:
                        raise ValueError(f"Team '{self.teams[pid].name}' is one-event-only and already placed in another event.")
                    if etype == "Individual" and self.individuals[pid].one_event_only:
                        raise ValueError(f"Individual '{self.individuals[pid].name}' is one-event-only and already placed in another event.")

    def recompute_one_event_only_assignments(self) -> None:
        """
        After deletions, make sure one-event-only chosen_event_id values still make sense.
        If the chosen event is gone, clear it. If results contradict, prefer first event encountered.
        """
        # Clear chosen_event_id pointing to missing events
        event_ids = set(self.events.keys())
        for t in self.teams.values():
            if t.chosen_event_id is not None and t.chosen_event_id not in event_ids:
                t.chosen_event_id = None
        for p in self.individuals.values():
            if p.chosen_event_id is not None and p.chosen_event_id not in event_ids:
                p.chosen_event_id = None
        # Reassert locks from results order (first event they appear in)
        first_event_for_team: Dict[int, int] = {}
        first_event_for_indiv: Dict[int, int] = {}
        for eid, places in self.results.items():
            ev = self.events.get(eid)
            if not ev:
                continue
            if ev.type == "Team":
                for pid in places:
                    if pid not in first_event_for_team:
                        first_event_for_team[pid] = eid
            else:
                for pid in places:
                    if pid not in first_event_for_indiv:
                        first_event_for_indiv[pid] = eid
        for tid, t in self.teams.items():
            if t.one_event_only and t.chosen_event_id is None and tid in first_event_for_team:
                t.chosen_event_id = first_event_for_team[tid]
        for iid, p in self.individuals.items():
            if p.one_event_only and p.chosen_event_id is None and iid in first_event_for_indiv:
                p.chosen_event_id = first_event_for_indiv[iid]

    # ---- Scoring ----
    def compute_points(self) -> Tuple[Dict[int, int], Dict[int, int], Dict[int, int]]:
        """
        Returns:
            team_points: team_id -> total points
            indiv_points: indiv_id -> total points
            entries_count: entrant_id -> events entered (for both types; used per leaderboard)
        """
        team_points: Dict[int, int] = {tid: 0 for tid in self.teams}
        indiv_points: Dict[int, int] = {iid: 0 for iid in self.individuals}
        entries_count: Dict[int, int] = {}

        for eid, placements in self.results.items():
            ev = self.events.get(eid)
            if not ev:
                continue
            pmap = self.get_points_for_event(eid)
            for rank_index, pid in enumerate(placements, start=1):
                pts = pmap.get(rank_index, 0)
                entries_count[pid] = entries_count.get(pid, 0) + 1
                if ev.type == "Team":
                    if pid in team_points:
                        team_points[pid] += pts
                else:
                    if pid in indiv_points:
                        indiv_points[pid] += pts
        return team_points, indiv_points, entries_count

    # ---- Global points ----
    def set_global_points_map(self, points: Dict[int, int]) -> None:
        self._validate_points_map(points)
        self.points_map = dict(points)

    # ---- Serialization ----
    def to_snapshot(self) -> Dict:
        return {
            "teams": [asdict(t) for t in self.teams.values()],
            "individuals": [asdict(i) for i in self.individuals.values()],
            "events": [asdict(e) for e in self.events.values()],
            "results": {str(k): v for k, v in self.results.items()},
            "points_map": self.points_map,
            "counters": {
                "team_counter": self.team_counter,
                "indiv_counter": self.indiv_counter,
                "event_counter": self.event_counter,
            }
        }

    @staticmethod
    def _safe_points_map(obj) -> Optional[Dict[int, int]]:
        if obj is None:
            return None
        if not isinstance(obj, dict):
            raise ValueError("Invalid points_map structure.")
        conv = {}
        for k, v in obj.items():
            try:
                rk = int(k) if isinstance(k, str) else int(k)
                rv = int(v)
            except Exception as e:
                raise ValueError("Invalid points_map entries.") from e
            if rk <= 0 or rv < 0:
                raise ValueError("Invalid points_map values.")
            conv[rk] = rv
        return conv

    @classmethod
    def from_snapshot(cls, data: Dict) -> "TournamentData":
        td = cls()
        try:
            td.points_map = cls._safe_points_map(data.get("points_map")) or td.points_map
            # Teams
            for t in data.get("teams", []):
                tid = int(t["id"])
                td.teams[tid] = Team(
                    id=tid,
                    name=cls._clean_name(t["name"]),
                    members=[cls._clean_name(m) for m in t.get("members", []) if cls._clean_name(m)],
                    one_event_only=bool(t.get("one_event_only", False)),
                    chosen_event_id=(int(t["chosen_event_id"]) if t.get("chosen_event_id") is not None else None)
                )
            # Individuals
            for p in data.get("individuals", []):
                iid = int(p["id"])
                td.individuals[iid] = Individual(
                    id=iid,
                    name=cls._clean_name(p["name"]),
                    one_event_only=bool(p.get("one_event_only", False)),
                    chosen_event_id=(int(p["chosen_event_id"]) if p.get("chosen_event_id") is not None else None)
                )
            # Events
            for e in data.get("events", []):
                eid = int(e["id"])
                ev_points = cls._safe_points_map(e.get("points_map"))
                if ev_points is not None:
                    td._validate_points_map(ev_points)
                etype = e.get("type")
                if etype not in ("Team", "Individual"):
                    raise ValueError("Invalid event type in file.")
                td.events[eid] = Event(
                    id=eid, name=cls._clean_name(e["name"]),
                    type=etype, genre=cls._clean_name(e.get("genre", "")),
                    points_map=ev_points
                )
            # Results
            raw_results = data.get("results", {})
            td.results = {}
            for k, v in raw_results.items():
                eid = int(k)
                if eid not in td.events:
                    continue
                if not isinstance(v, list):
                    raise ValueError("Invalid results structure.")
                # Validate participant IDs exist
                ev = td.events[eid]
                cleaned = []
                for pid in v:
                    pid = int(pid)
                    if ev.type == "Team":
                        if pid in td.teams:
                            cleaned.append(pid)
                    else:
                        if pid in td.individuals:
                            cleaned.append(pid)
                # De-dup and preserve order
                seen = set()
                final = []
                for pid in cleaned:
                    if pid not in seen:
                        seen.add(pid)
                        final.append(pid)
                td.results[eid] = final
            # Counters
            counters = data.get("counters", {})
            td.team_counter = max([1] + list(td.teams.keys())) + 1
            td.indiv_counter = max([1] + list(td.individuals.keys())) + 1
            td.event_counter = max([1] + list(td.events.keys())) + 1
            # Recompute one-event-only integrity
            td.recompute_one_event_only_assignments()
        except Exception as e:
            raise ValueError(f"Invalid tournament file: {e}")
        return td


# -------------------------
# Tkinter UI
# -------------------------

class TournamentApp(tk.Tk):
    """
    Tkinter GUI application wrapping TournamentData with tabs for:
    - Participants (Teams and Individuals management)
    - Events (creation and editing with per-event points)
    - Results (ranked ordering per event)
    - Leaderboards (team and individual standings)
    - Points (global schemes and custom editor)
    """
    def __init__(self):
        super().__init__()
        self.title("E-Sports Tournament Scoring")
        self.geometry("1100x700")
        self.minsize(1000, 650)

        self.data = TournamentData()
        self.current_file: Optional[str] = None

        self._build_menu()
        self._build_tabs()

    # ----------------- Menu -----------------
    def _build_menu(self):
        menubar = tk.Menu(self)
        file_menu = tk.Menu(menubar, tearoff=0)
        file_menu.add_command(label="New", command=self.new_tournament)
        file_menu.add_command(label="Open...", command=self.open_tournament)
        file_menu.add_command(label="Save", command=self.save_tournament)
        file_menu.add_command(label="Save As...", command=self.save_tournament_as)
        file_menu.add_separator()
        file_menu.add_command(label="Exit", command=self.on_exit)
        menubar.add_cascade(label="File", menu=file_menu)
        self.config(menu=menubar)

    def new_tournament(self):
        if not self._confirm_discard_changes():
            return
        self.data = TournamentData()
        self.current_file = None
        self._refresh_all()

    def open_tournament(self):
        if not self._confirm_discard_changes():
            return
        path = filedialog.askopenfilename(
            title="Open Tournament",
            filetypes=[("JSON Files", "*.json"), ("All Files", "*.*")]
        )
        if not path:
            return
        try:
            with open(path, "r", encoding="utf-8") as f:
                raw = json.load(f)
            self.data = TournamentData.from_snapshot(raw)
            self.current_file = path
            self._refresh_all()
            messagebox.showinfo("Open", "Tournament loaded successfully.")
        except Exception as e:
            messagebox.showerror("Open Failed", str(e))

    def save_tournament(self):
        if self.current_file is None:
            return self.save_tournament_as()
        try:
            with open(self.current_file, "w", encoding="utf-8") as f:
                json.dump(self.data.to_snapshot(), f, indent=2)
            messagebox.showinfo("Save", "Tournament saved successfully.")
        except Exception as e:
            messagebox.showerror("Save Failed", str(e))

    def save_tournament_as(self):
        path = filedialog.asksaveasfilename(
            title="Save Tournament As",
            defaultextension=".json",
            filetypes=[("JSON Files", "*.json"), ("All Files", "*.*")]
        )
        if not path:
            return
        self.current_file = path
        self.save_tournament()

    def _confirm_discard_changes(self) -> bool:
        return messagebox.askyesno("Confirm", "Discard current tournament and continue?")

    def on_exit(self):
        self.destroy()

