    # ----------------- Participants Tab Logic -----------------
    def _update_team_chosen_state(self):
        self.cb_team_chosen.configure(state="readonly" if self.var_team_one.get() else "disabled")

    def _update_ind_chosen_state(self):
        self.cb_ind_chosen.configure(state="readonly" if self.var_ind_one.get() else "disabled")

    def _on_team_select(self, _evt=None):
        idxs = self.teams_list.curselection()
        if not idxs:
            return
        tid = self._team_id_from_index(idxs[0])
        if tid is None:
            return
        t = self.data.teams[tid]
        self.var_team_name.set(t.name)
        # Fill member fields
        for i in range(5):
            self.var_members[i].set(t.members[i] if i < len(t.members) else "")
        self.var_team_one.set(t.one_event_only)
        self._populate_team_chosen_events()
        if t.chosen_event_id is not None and t.chosen_event_id in self.data.events:
            self.var_team_chosen.set(self._event_label(self.data.events[t.chosen_event_id]))
        else:
            self.var_team_chosen.set("")
        self._update_team_chosen_state()

    def _on_ind_select(self, _evt=None):
        idxs = self.ind_list.curselection()
        if not idxs:
            return
        iid = self._ind_id_from_index(idxs[0])
        if iid is None:
            return
        p = self.data.individuals[iid]
        self.var_ind_name.set(p.name)
        self.var_ind_one.set(p.one_event_only)
        self._populate_ind_chosen_events()
        if p.chosen_event_id is not None and p.chosen_event_id in self.data.events:
            self.var_ind_chosen.set(self._event_label(self.data.events[p.chosen_event_id]))
        else:
            self.var_ind_chosen.set("")
        self._update_ind_chosen_state()

    def _populate_team_chosen_events(self):
        team_events = [self._event_label(e) for e in self.data.events.values() if e.type == "Team"]
        self.cb_team_chosen.configure(values=[""] + team_events)

    def _populate_ind_chosen_events(self):
        ind_events = [self._event_label(e) for e in self.data.events.values() if e.type == "Individual"]
        self.cb_ind_chosen.configure(values=[""] + ind_events)

    def _add_team(self):
        try:
            name = self.var_team_name.get()
            members = [v.get() for v in self.var_members if v.get().strip()]
            cho_label = self.var_team_chosen.get().strip()
            chosen_eid = self._event_id_from_label(cho_label) if cho_label else None
            tid = self.data.add_team(name, members, self.var_team_one.get(), chosen_eid)
            self._refresh_teams()
            self._select_team_by_id(tid)
        except Exception as e:
            messagebox.showerror("Add Team Failed", str(e))

    def _update_team(self):
        idxs = self.teams_list.curselection()
        if not idxs:
            messagebox.showwarning("Update Team", "Select a team to update.")
            return
        tid = self._team_id_from_index(idxs[0])
        if tid is None:
            return
        try:
            name = self.var_team_name.get()
            members = [v.get() for v in self.var_members if v.get().strip()]
            cho_label = self.var_team_chosen.get().strip()
            chosen_eid = self._event_id_from_label(cho_label) if (self.var_team_one.get() and cho_label) else None
            self.data.edit_team(tid, name, members, self.var_team_one.get(), chosen_eid)
            self._refresh_teams()
            self._select_team_by_id(tid)
        except Exception as e:
            messagebox.showerror("Update Team Failed", str(e))

    def _remove_team(self):
        idxs = self.teams_list.curselection()
        if not idxs:
            messagebox.showwarning("Remove Team", "Select a team to remove.")
            return
        tid = self._team_id_from_index(idxs[0])
        if tid is None:
            return
        if not messagebox.askyesno("Confirm", "Remove selected team?"):
            return
        try:
            self.data.remove_team(tid)
            self._refresh_teams()
            self._refresh_results_lists()
            self._refresh_leaderboards()
        except Exception as e:
            messagebox.showerror("Remove Team Failed", str(e))

    def _clear_team_form(self):
        self.var_team_name.set("")
        for v in self.var_members:
            v.set("")
        self.var_team_one.set(False)
        self.var_team_chosen.set("")
        self._update_team_chosen_state()
        self.teams_list.selection_clear(0, tk.END)

    def _add_individual(self):
        try:
            name = self.var_ind_name.get()
