    # ---- Points text parsing/formatting ----
    def _parse_points_text(self, text: str) -> Dict[int, int]:
        """
        Parse "1:25,2:18,3:15" into {1:25,2:18,3:15} with validation:
        - Positive integer ranks
        - Non-negative integer points
        - Non-increasing with rank
        """
        mapping: Dict[int, int] = {}
        if not text:
            raise ValueError("Points text cannot be empty.")
        parts = [p.strip() for p in text.split(",") if p.strip()]
        for part in parts:
            if ":" not in part:
                raise ValueError(f"Invalid entry '{part}'. Use rank:points.")
            rank_s, pts_s = [x.strip() for x in part.split(":", 1)]
            rank = int(rank_s)
            pts = int(pts_s)
            if rank <= 0 or pts < 0:
                raise ValueError("Ranks must be > 0 and points >= 0.")
            mapping[rank] = pts
        # Validate non-increasing
        prev = None
        for r in sorted(mapping.keys()):
            if prev is not None and mapping[r] > prev:
                raise ValueError("Points should not increase for lower ranks.")
            prev = mapping[r]
        return mapping

    def _points_map_to_text(self, mapping: Dict[int, int]) -> str:
        items = [f"{r}:{mapping[r]}" for r in sorted(mapping.keys())]
        return ",".join(items)

