    // Compute ballistic preview and update UI dots and optional LineRenderer
    void UpdateTrajectoryPreview(Vector2 initialVelocity)
    {
        if (!_dragging) return;

        // Gravity acceleration from Physics2D
        Vector2 a = Physics2D.gravity * _rb.gravityScale;
        Vector2 p0 = _rb.position;
        float tStep = dotTimeStep;

        // Prepare positions for line renderer
        Vector3[] worldPositions = null;
        int pointCount = Mathf.Max(2, dotsCount);

        if (useLineRenderer && lineRenderer != null)
        {
            worldPositions = new Vector3[pointCount];
        }

        // Update dots and collect world positions
        for (int i = 0; i < dotsCount; i++)
        {
            float t = (i + 1) * tStep;
            Vector2 pt = p0 + initialVelocity * t + 0.5f * a * (t * t);

            if (i < _dots.Count && _dots[i] != null && targetCanvas != null)
            {
                Vector2 canvasPos;
                if (WorldToCanvasPosition(pt, out canvasPos))
                {
                    _dots[i].anchoredPosition = canvasPos;
                    if (!_dots[i].gameObject.activeSelf) _dots[i].gameObject.SetActive(true);
                }
            }

            if (worldPositions != null && i < worldPositions.Length)
            {
                worldPositions[i] = new Vector3(pt.x, pt.y, 0f);
            }
        }

        // Update line renderer
        if (useLineRenderer && lineRenderer != null)
        {
            // Ensure at least two points
            if (worldPositions == null || worldPositions.Length < pointCount)
            {
                worldPositions = new Vector3[pointCount];
            }

            // Fill remaining points if any
            for (int i = 0; i < pointCount; i++)
            {
                if (worldPositions[i] == Vector3.zero)
                {
                    float t = (i + 1) * tStep;
                    Vector2 pt = p0 + initialVelocity * t + 0.5f * a * (t * t);
                    worldPositions[i] = new Vector3(pt.x, pt.y, 0f);
                }
            }

            lineRenderer.enabled = true;
            lineRenderer.positionCount = pointCount;
            lineRenderer.SetPositions(worldPositions);

            // Apply dash tiling based on length
            float length = EstimatePolylineLength(worldPositions);
            ApplyLineRendererStyle(_dashOffsetPhase, length);
        }
    }

    // Apply dashed or solid style; when dashed, tile texture based on world length and multiplier, and animate offset
    void ApplyLineRendererStyle(float offsetPhase, float lineWorldLength = 0f)
    {
        if (!useLineRenderer || lineRenderer == null) return;

        if (dashedLine && dashedLineMaterial != null)
        {
            // Use an instance of dashed material to avoid mutating shared asset
            if (lineRenderer.sharedMaterial != dashedLineMaterial)
            {
                lineRenderer.sharedMaterial = dashedLineMaterial;
            }
            lineRenderer.textureMode = LineTextureMode.Tile;

            if (lineRenderer.material != null)
            {
                float cycles = 1f;
                if (dashLengthWorld > 0f)
                {
                    cycles = Mathf.Max(0.001f, (lineWorldLength > 0f ? lineWorldLength : 1f) / dashLengthWorld) * Mathf.Max(0.001f, dashTilingMultiplier);
                }
                Vector2 scale = new Vector2(cycles, 1f);
                lineRenderer.material.mainTextureScale = scale;

                // Animate along X (u) using offsetPhase
                Vector2 offset = new Vector2(offsetPhase, 0f);
                lineRenderer.material.mainTextureOffset = offset;
            }
        }
        else
        {
            // Solid line; restore original or keep current but reset tiling
            if (_originalLineMaterial != null)
            {
                lineRenderer.sharedMaterial = _originalLineMaterial;
            }
            lineRenderer.textureMode = LineTextureMode.Stretch;
            if (lineRenderer.material != null)
            {
                lineRenderer.material.mainTextureScale = Vector2.one;
                lineRenderer.material.mainTextureOffset = Vector2.zero;
            }
        }

        // Ensure color/width are applied
        lineRenderer.startWidth = lineWidth;
        lineRenderer.endWidth = lineWidth;
        lineRenderer.startColor = lineColor;
        lineRenderer.endColor = lineColor;
    }

    bool WorldToCanvasPosition(Vector2 world, out Vector2 canvasPos)
    {
        canvasPos = Vector2.zero;
        if (targetCanvas == null || _canvasRect == null) return false;

        Camera canvasCam = GetCanvasCamera();
        Vector2 screenPoint = RectTransformUtility.WorldToScreenPoint(cam != null ? cam : Camera.main, new Vector3(world.x, world.y, transform.position.z));
        Vector2 localPoint;
        if (RectTransformUtility.ScreenPointToLocalPointInRectangle(_canvasRect, screenPoint, canvasCam, out localPoint))
        {
            canvasPos = localPoint;
            return true;
        }
        return false;
    }

    Camera GetCanvasCamera()
    {
        if (targetCanvas == null) return null;
        if (targetCanvas.renderMode == RenderMode.ScreenSpaceOverlay) return null;
        return targetCanvas.worldCamera != null ? targetCanvas.worldCamera : cam;
    }

    Vector3 ScreenToWorldWithZ(Vector3 screen)
    {
        if (cam == null) return screen;
        screen.z = _zToCam;
        return cam.ScreenToWorldPoint(screen);
    }

    float EstimatePolylineLength(IList<Vector3> pts)
    {
        if (pts == null || pts.Count < 2) return 0f;
        float len = 0f;
        for (int i = 1; i < pts.Count; i++)
        {
            len += Vector3.Distance(pts[i - 1], pts[i]);
        }
        return len;
    }
