                    Vector3 p = lineRenderer.GetPosition(i);
                    length += Vector3.Distance(prev, p);
                    prev = p;
                }
            }

            if (lineRenderer.material != null && dashLengthWorld > 0f)
            {
                float tiles = Mathf.Max(1f, (length / dashLengthWorld) * Mathf.Max(0.0001f, dashTilingMultiplier));
                Vector2 scale = new Vector2(tiles, 1f);
                lineRenderer.material.mainTextureScale = scale;

                if (dashScrollSpeed != 0f && deltaTime > 0f)
                {
                    _dashOffsetPhase += dashScrollSpeed * deltaTime;
                    Vector2 offset = new Vector2(_dashOffsetPhase, 0f);
                    lineRenderer.material.mainTextureOffset = offset;
                }
                else
                {
                    // keep current offset if not scrolling
                }
            }
        }
        else
        {
            // Restore defaults when dashed is disabled
            if (_originalLineMaterial != null)
            {
                lineRenderer.sharedMaterial = _originalLineMaterial;
            }
            lineRenderer.textureMode = LineTextureMode.Stretch;
            if (lineRenderer.material != null)
            {
                lineRenderer.material.mainTextureScale = Vector2.one;
                lineRenderer.material.mainTextureOffset = Vector2.zero;
            }
        }
    }

    // Update and show the direction arrow aligned to the launch velocity
    void UpdateDirectionImage(Vector2 launchVelocity)
    {
        if (directionImage == null || targetCanvas == null || _canvasRect == null) return;

        // Position: at the object's screen-to-canvas position
        Vector2 screenPos = cam != null ? (Vector2)cam.WorldToScreenPoint(transform.position) : Vector2.zero;
        Vector2 anchoredPos;
        if (RectTransformUtility.ScreenPointToLocalPointInRectangle(_canvasRect, screenPos, GetCanvasCamera(), out anchoredPos))
        {
            directionImage.rectTransform.anchoredPosition = anchoredPos;
        }

        // Rotation: face the launch velocity direction (if non-zero)
        if (launchVelocity.sqrMagnitude > 1e-6f)
        {
            float angle = Mathf.Atan2(launchVelocity.y, launchVelocity.x) * Mathf.Rad2Deg;
            directionImage.rectTransform.rotation = Quaternion.Euler(0f, 0f, angle);
        }

        // Scale length by speed if enabled
        if (arrowLengthScale > 0f)
        {
            float lengthPx = Mathf.Clamp(launchVelocity.magnitude * arrowLengthScale, arrowMinLength, arrowMaxLength);
            Vector2 size = directionImage.rectTransform.sizeDelta;
            // Assume arrow points along +X; scale X as length, keep Y as original
            directionImage.rectTransform.sizeDelta = new Vector2(lengthPx, size.y);
        }

        // Ensure visible while dragging
        directionImage.enabled = _dragging;
    }

    // Helper: get canvas camera for targetCanvas (null for Screen Space - Overlay)
    Camera GetCanvasCamera()
    {
        if (targetCanvas == null) return null;
        return targetCanvas.renderMode == RenderMode.ScreenSpaceOverlay ? null : targetCanvas.worldCamera;
    }

    // Helper: Screen to world using stored Z distance from camera
    Vector3 ScreenToWorldWithZ(Vector3 screenPos)
    {
        if (cam == null) return transform.position;
        screenPos.z = _zToCam;
        return cam.ScreenToWorldPoint(screenPos);
    }
