        Vector2 v0 = launchVelocity;
        Vector2 a = Physics2D.gravity * _rb.gravityScale;

        // Prepare line renderer positions if in use
        Vector3[] linePositions = null;
        int lineCount = Mathf.Max(0, dotsCount);
        if (useLineRenderer && lineRenderer != null)
        {
            linePositions = new Vector3[lineCount];
        }

        // Canvas camera for screen-to-canvas conversion
        Camera canvasCam = GetCanvasCamera();

        for (int i = 0; i < dotsCount; i++)
        {
            float t = (i + 1) * dotTimeStep; // start after small dt so first dot isn't at p0
            Vector2 worldPos = p0 + v0 * t + 0.5f * a * (t * t);

            // Place UI dots (convert world -> screen -> canvas local point)
            if (i < _dots.Count && _dots[i] != null && targetCanvas != null && _canvasRect != null)
            {
                Vector2 screen = WorldToScreen(worldPos, cam);
                Vector2 canvasPos;
                RectTransformUtility.ScreenPointToLocalPointInRectangle(_canvasRect, screen, canvasCam, out canvasPos);
                _dots[i].anchoredPosition = canvasPos;
            }

            // Feed positions to LineRenderer
            if (linePositions != null && i < linePositions.Length)
            {
                linePositions[i] = new Vector3(worldPos.x, worldPos.y, transform.position.z);
            }
        }

        if (useLineRenderer && lineRenderer != null)
        {
            if (linePositions != null && linePositions.Length > 0)
            {
                lineRenderer.positionCount = linePositions.Length;
                lineRenderer.SetPositions(linePositions);
            }
            else
            {
                lineRenderer.positionCount = 0;
            }

            // If dashed, animate texture offset based on path length and time
            if (dashedLine && dashedLineMaterial != null && lineRenderer.material != null)
            {
                // Scroll along the line's V direction when textureMode = Tile
                if (dashScrollSpeed != 0f)
                {
                    Vector2 ofs = lineRenderer.material.mainTextureOffset;
                    ofs.y = Mathf.Repeat(ofs.y + dashScrollSpeed * Time.deltaTime, 1f);
                    lineRenderer.material.mainTextureOffset = ofs;
                }
            }
        }
    }

    void UpdateDirectionImage(Vector2 launchVelocity)
    {
        if (directionImage == null || targetCanvas == null) return;

        // Ensure visible while dragging
        if (_dragging && !directionImage.gameObject.activeSelf)
            directionImage.gameObject.SetActive(true);

        // Position at object's screen-to-canvas position
        Vector2 screen = WorldToScreen(transform.position, cam);
        Camera canvasCam = GetCanvasCamera();
        Vector2 canvasPos;
        RectTransformUtility.ScreenPointToLocalPointInRectangle(_canvasRect, screen, canvasCam, out canvasPos);
        directionImage.rectTransform.anchoredPosition = canvasPos;

        // Rotate to match launch direction
        if (launchVelocity.sqrMagnitude > 0.0001f)
        {
            float angle = Mathf.Atan2(launchVelocity.y, launchVelocity.x) * Mathf.Rad2Deg;
            directionImage.rectTransform.rotation = Quaternion.Euler(0f, 0f, angle);
        }

        // Scale length by speed if enabled
        if (arrowLengthScale > 0f)
        {
            float speed = launchVelocity.magnitude;
            Vector2 size = _directionBaseSize;
            size.x = _directionBaseSize.x + speed * arrowLengthScale;
            directionImage.rectTransform.sizeDelta = size;
        }
        else
        {
            directionImage.rectTransform.sizeDelta = _directionBaseSize;
        }
    }

    void ApplyLineRendererStyle()
    {
        if (lineRenderer == null) return;

        lineRenderer.startWidth = lineWidth;
        lineRenderer.endWidth = lineWidth;
        lineRenderer.startColor = lineColor;
        lineRenderer.endColor = lineColor;

        if (useLineRenderer && dashedLine && dashedLineMaterial != null)
        {
            // Assign dashed material and enable tiling
            lineRenderer.sharedMaterial = dashedLineMaterial;
            lineRenderer.textureMode = LineTextureMode.Tile;

            // Compute tiling so that one V tile spans approximately dashLengthWorld
            // When textureMode = Tile, the V-axis of the texture maps along the line length.
            // We control tiling via mainTextureScale.y (more tiles => more, smaller dashes).
            if (lineRenderer.material != null)
            {
                float tilingV = (dashLengthWorld > 0f) ? (1f / Mathf.Max(0.0001f, dashLengthWorld)) : 1f;
                tilingV *= Mathf.Max(0.0001f, dashTilingMultiplier);
                Vector2 scale = lineRenderer.material.mainTextureScale;
                scale.y = tilingV;
                lineRenderer.material.mainTextureScale = scale;

                // Reset offset so scroll starts consistent
                Vector2 ofs = lineRenderer.material.mainTextureOffset;
                ofs.y = 0f;
                lineRenderer.material.mainTextureOffset = ofs;
            }
        }
        else
        {
            // Restore original material and defaults when dashed disabled/hidden
            if (_originalLineMaterial != null)
            {
                lineRenderer.sharedMaterial = _originalLineMaterial;
            }
            lineRenderer.textureMode = LineTextureMode.Stretch;
            if (lineRenderer.material != null)
            {
                lineRenderer.material.mainTextureScale = new Vector2(1f, 1f);
                lineRenderer.material.mainTextureOffset = Vector2.zero;
            }
        }
    }

    Camera GetCanvasCamera()
    {
        if (targetCanvas == null) return null;
        if (targetCanvas.renderMode == RenderMode.ScreenSpaceOverlay) return null;
        return targetCanvas.worldCamera != null ? targetCanvas.worldCamera : cam;
    }

    Vector3 ScreenToWorldWithZ(Vector3 screenPos)
    {
        if (cam == null) return screenPos;
        screenPos.z = _zToCam;
        return cam.ScreenToWorldPoint(screenPos);
    }

    Vector2 WorldToScreen(Vector2 worldPos, Camera worldCam)
    {
        if (worldCam == null) return worldPos;
        return worldCam.WorldToScreenPoint(new Vector3(worldPos.x, worldPos.y, transform.position.z));
    }
}
