// ---------------- URL parser ----------------
struct ParsedUrl {
    std::wstring host;
    std::wstring path_query;
    INTERNET_PORT port{0};
    bool https{false};
};
static bool CrackUrl(const std::wstring& url, ParsedUrl& out) {
    URL_COMPONENTS uc{};
    wchar_t host[512]{};
    wchar_t path[4096]{};
    wchar_t extra[4096]{};
    uc.dwStructSize = sizeof(uc);
    uc.lpszHostName = host; uc.dwHostNameLength = ARRAYSIZE(host);
    uc.lpszUrlPath = path; uc.dwUrlPathLength = ARRAYSIZE(path);
    uc.lpszExtraInfo = extra; uc.dwExtraInfoLength = ARRAYSIZE(extra);
    uc.dwSchemeLength = (DWORD)-1;

    if (!WinHttpCrackUrl(url.c_str(), 0, 0, &uc)) {
        std::wcerr << L"WinHttpCrackUrl failed: " << FormatLastError() << L"\n";
        return false;
    }
    out.host.assign(uc.lpszHostName, uc.dwHostNameLength);
    std::wstring p; p.assign(uc.lpszUrlPath, uc.dwUrlPathLength);
    std::wstring e; e.assign(uc.lpszExtraInfo, uc.dwExtraInfoLength);
    out.path_query = p + e;
    out.port = uc.nPort ? uc.nPort : (uc.nScheme == INTERNET_SCHEME_HTTPS ? 443 : 80);
    out.https = (uc.nScheme == INTERNET_SCHEME_HTTPS);
    if (out.path_query.empty()) out.path_query = L"/";
    return true;
}

// ---------------- Small helpers ----------------
static std::string ToLower(std::string s) {
    std::transform(s.begin(), s.end(), s.begin(), [](unsigned char c){ return (char)std::tolower(c); });
    return s;
}
static bool IsOnionHost(const std::wstring& host) {
    std::string h = ToLower(WideToUtf8(host));
    return h.size() > 6 && h.rfind(".onion") == h.size() - 6;
