// ---------- UTF helpers ----------
static std::wstring Utf8ToWide(const std::string& s) {
    if (s.empty()) return L"";
    int len = MultiByteToWideChar(CP_UTF8, 0, s.c_str(), (int)s.size(), nullptr, 0);
    std::wstring out(len, 0);
    MultiByteToWideChar(CP_UTF8, 0, s.c_str(), (int)s.size(), &out[0], len);
    return out;
}
static std::string WideToUtf8(const std::wstring& ws) {
    if (ws.empty()) return "";
    int len = WideCharToMultiByte(CP_UTF8, 0, ws.c_str(), (int)ws.size(), nullptr, 0, nullptr, nullptr);
    std::string out(len, 0);
    WideCharToMultiByte(CP_UTF8, 0, ws.c_str(), (int)ws.size(), &out[0], len, nullptr, nullptr);
    return out;
}

// ---------- Error helpers ----------
static std::wstring FormatWinHttpError(DWORD err) {
    LPWSTR buf = nullptr;
    DWORD len = FormatMessageW(FORMAT_MESSAGE_FROM_HMODULE | FORMAT_MESSAGE_ALLOCATE_BUFFER | FORMAT_MESSAGE_IGNORE_INSERTS,
                               GetModuleHandleW(L"winhttp.dll"), err, 0, (LPWSTR)&buf, 0, nullptr);
    std::wstring s = (len && buf) ? std::wstring(buf, len) : L"(unknown WinHTTP error)";
    if (buf) LocalFree(buf);
    return s;
}
static std::wstring FormatLastError() {
    DWORD err = GetLastError();
    LPWSTR buf = nullptr;
    DWORD len = FormatMessageW(FORMAT_MESSAGE_FROM_SYSTEM | FORMAT_MESSAGE_ALLOCATE_BUFFER | FORMAT_MESSAGE_IGNORE_INSERTS,
                               nullptr, err, 0, (LPWSTR)&buf, 0, nullptr);
    std::wstring s = (len && buf) ? std::wstring(buf, len) : L"(unknown error)";
    if (buf) LocalFree(buf);
    return s;
}

// ---------- RAII ----------
struct WinHttpHandle {
    HINTERNET h{nullptr};
    WinHttpHandle() = default;
    explicit WinHttpHandle(HINTERNET handle) : h(handle) {}
    ~WinHttpHandle() { if (h) WinHttpCloseHandle(h); }
    WinHttpHandle(WinHttpHandle&& o) noexcept : h(o.h) { o.h = nullptr; }
    WinHttpHandle& operator=(WinHttpHandle&& o) noexcept { if (this!=&o){ if(h) WinHttpCloseHandle(h); h=o.h; o.h=nullptr;} return *this; }
    WinHttpHandle(const WinHttpHandle&) = delete;
    WinHttpHandle& operator=(const WinHttpHandle&) = delete;
    operator HINTERNET() const { return h; }
};

// ---------- OpenSSL helpers ----------
struct OpenSSLInit {
    OpenSSLInit() { OPENSSL_init_crypto(0, nullptr); }
    ~OpenSSLInit() {}
} g_openssl_init;

static std::vector<uint8_t> Sha3_256(const std::vector<uint8_t>& data) {
    std::vector<uint8_t> out(32);
#if OPENSSL_VERSION_NUMBER >= 0x10100000L
    EVP_MD_CTX* ctx = EVP_MD_CTX_new();
    if (!ctx) throw std::runtime_error("EVP_MD_CTX_new failed");
    const EVP_MD* md = EVP_sha3_256();
    if (!md) { EVP_MD_CTX_free(ctx); throw std::runtime_error("EVP_sha3_256 not available"); }
    if (EVP_DigestInit_ex(ctx, md, nullptr) != 1) { EVP_MD_CTX_free(ctx); throw std::runtime_error("DigestInit"); }
    if (EVP_DigestUpdate(ctx, data.data(), data.size()) != 1) { EVP_MD_CTX_free(ctx); throw std::runtime_error("DigestUpdate"); }
    unsigned int len = 0;
    if (EVP_DigestFinal_ex(ctx, out.data(), &len) != 1 || len != 32) { EVP_MD_CTX_free(ctx); throw std::runtime_error("DigestFinal"); }
    EVP_MD_CTX_free(ctx);
#else
    // Fallback not expected on modern OpenSSL; included for completeness
    SHA3_256(data.data(), data.size(), out.data());
#endif
    return out;
}

static std::vector<uint8_t> Base64Decode(const std::string& in) {
    BIO* b64 = BIO_new(BIO_f_base64());
    BIO* bio = BIO_new_mem_buf(in.data(), (int)in.size());
    if (!b64 || !bio) { if (b64) BIO_free(b64); if (bio) BIO_free(bio); throw std::runtime_error("BIO_new failed"); }
    BIO_set_flags(b64, BIO_FLAGS_BASE64_NO_NL);
    bio = BIO_push(b64, bio);
    std::vector<uint8_t> out(in.size());
    int n = BIO_read(bio, out.data(), (int)out.size());
    if (n < 0) { BIO_free_all(bio); throw std::runtime_error("BIO_read failed"); }
    out.resize((size_t)n);
    BIO_free_all(bio);
    return out;
}

// RFC 4648 base32 (lowercase) for onion; returns empty on error
static std::vector<uint8_t> Base32DecodeLowerNoPad(const std::string& s) {
    static const int8_t mapTbl[256] = []{
        int8_t m[256]; std::fill(std::begin(m), std::end(m), int8_t(-1));
        const char* alpha = "abcdefghijklmnopqrstuvwxyz234567";
        for (int i=0;i<32;i++) m[(uint8_t)alpha[i]] = (int8_t)i;
        return *reinterpret_cast<int8_t(*)[256]>(m);
    }();
    uint32_t buffer = 0; int bits = 0;
    std::vector<uint8_t> out;
    for (char c : s) {
        if (c=='=') break;
        uint8_t uc = (uint8_t)std::tolower((unsigned char)c);
        int8_t v = mapTbl[uc];
        if (v < 0) return {};
        buffer = (buffer << 5) | (uint32_t)v;
        bits += 5;
        if (bits >= 8) {
            bits -= 8;
            out.push_back((uint8_t)((buffer >> bits) & 0xFF));
        }
    }
    // allow leftover zero bits only
    if (bits > 0 && ((buffer & ((1u<<bits)-1)) != 0)) return {};
    return out;
}

// ---------- Onion address validation (v3) ----------
static bool ValidateOnionV3(const std::string& host) {
    // Expect 56-char base32 + ".onion"
    std::string h = host;
    std::transform(h.begin(), h.end(), h.begin(), [](unsigned char c){ return (char)std::tolower(c); });
    if (h.size() != 62 || h.substr(h.size()-6) != ".onion") return false;
    std::string label = h.substr(0, 56);
    auto dec = Base32DecodeLowerNoPad(label);
    if (dec.size() != 35) return false;
    std::vector<uint8_t> pubkey(dec.begin(), dec.begin()+32);
    std::array<uint8_t, 2> csumExp{dec[32], dec[33]};
    uint8_t version = dec[34];
    if (version != 0x03) return false;
    // checksum = SHA3-256(".onion checksum" || pubkey || version) first 2 bytes
    const char prefix[] = ".onion checksum";
    std::vector<uint8_t> buf;
    buf.insert(buf.end(), prefix, prefix + sizeof(prefix)-1);
    buf.insert(buf.end(), pubkey.begin(), pubkey.end());
    buf.push_back(version);
    auto d = Sha3_256(buf);
    if (d[0] != csumExp[0] || d[1] != csumExp[1]) return false;
    return true;
}

// ---------- URL parser ----------
struct ParsedUrl {
    std::wstring scheme;
    std::wstring host;
    INTERNET_PORT port{0};
    std::wstring pathQuery;
    bool isHttps{false};
};

static ParsedUrl ParseUrl(const std::wstring& url) {
    ParsedUrl pu;
    URL_COMPONENTS uc{0};
    uc.dwStructSize = sizeof(uc);
    wchar_t scheme[16]{}, host[256]{}, path[2048]{};
    uc.lpszScheme = scheme; uc.dwSchemeLength = _countof(scheme);
    uc.lpszHostName = host; uc.dwHostNameLength = _countof(host);
    uc.lpszUrlPath = path; uc.dwUrlPathLength = _countof(path);
    uc.dwFlags = ICU_DECODE;
    if (!WinHttpCrackUrl(url.c_str(), (DWORD)url.size(), 0, &uc)) {
        throw std::runtime_error("WinHttpCrackUrl failed");
    }
    pu.scheme.assign(uc.lpszScheme, uc.dwSchemeLength);
    pu.host.assign(uc.lpszHostName, uc.dwHostNameLength);
    pu.port = uc.nPort;
    pu.pathQuery.assign(uc.lpszUrlPath, uc.dwUrlPathLength);
    if (uc.lpszExtraInfo && uc.dwExtraInfoLength) {
        pu.pathQuery.append(uc.lpszExtraInfo, uc.dwExtraInfoLength);
    }
    std::wstring lower = pu.scheme; std::transform(lower.begin(), lower.end(), lower.begin(), ::towlower);
    pu.isHttps = (lower == L"https");
    if (pu.port == 0) pu.port = pu.isHttps ? 443 : 80;
    return pu;
}

// ---------- WinHTTP request ----------
struct HttpResponse {
    DWORD status{0};
    std::map<std::wstring,std::wstring> headers;
    std::vector<uint8_t> body;
};

static void SetProxyIfAny(HINTERNET h, const std::wstring& proxyStr) {
    if (proxyStr.empty()) return;
    WINHTTP_PROXY_INFO pi{};
    pi.dwAccessType = WINHTTP_ACCESS_TYPE_NAMED_PROXY;
    pi.lpszProxy = (LPWSTR)proxyStr.c_str(); // lifetime valid during call
    if (!WinHttpSetOption(h, WINHTTP_OPTION_PROXY, &pi, sizeof(pi))) {
        throw std::runtime_error("WinHttpSetOption(WINHTTP_OPTION_PROXY) failed");
    }
}

static void RelaxCertErrorsIfOnion(HINTERNET hRequest, const std::wstring& host) {
    std::wstring h = host; std::transform(h.begin(), h.end(), h.begin(), ::towlower);
    if (h.size() >= 6 && h.substr(h.size()-6)==L".onion") {
        DWORD flags =
            SECURITY_FLAG_IGNORE_UNKNOWN_CA |
            SECURITY_FLAG_IGNORE_CERT_CN_INVALID |
            SECURITY_FLAG_IGNORE_CERT_DATE_INVALID |
            SECURITY_FLAG_IGNORE_CERT_WRONG_USAGE;
        WinHttpSetOption(hRequest, WINHTTP_OPTION_SECURITY_FLAGS, &flags, sizeof(flags));
    }
}

static HttpResponse HttpRequestWinHttp(const std::wstring& url, const std::wstring& method,
                                       const std::wstring& proxyStr,
                                       const std::wstring& extraHeaders, const std::vector<uint8_t>* postBody) {
    ParsedUrl pu = ParseUrl(url);

    WinHttpHandle hSession(WinHttpOpen(L"tor-onion-client/1.0",
                                       WINHTTP_ACCESS_TYPE_NO_PROXY,
                                       WINHTTP_NO_PROXY_NAME,
                                       WINHTTP_NO_PROXY_BYPASS, 0));
    if (!hSession.h) throw std::runtime_error("WinHttpOpen failed");

    // SOCKS5 support via "socks=host:port" proxy string (Windows 10 1709+)
    if (!proxyStr.empty()) {
        SetProxyIfAny(hSession.h, proxyStr);
    }

    WinHttpHandle hConnect(WinHttpConnect(hSession.h, pu.host.c_str(), pu.port, 0));
    if (!hConnect.h) throw std::runtime_error("WinHttpConnect failed");

    WinHttpHandle hRequest(WinHttpOpenRequest(hConnect.h, method.c_str(),
                                              pu.pathQuery.empty() ? L"/" : pu.pathQuery.c_str(),
                                              nullptr,
                                              WINHTTP_NO_REFERER,
                                              WINHTTP_DEFAULT_ACCEPT_TYPES,
                                              pu.isHttps ? WINHTTP_FLAG_SECURE : 0));
    if (!hRequest.h) throw std::runtime_error("WinHttpOpenRequest failed");

    RelaxCertErrorsIfOnion(hRequest.h, pu.host);

    if (!extraHeaders.empty()) {
        if (!WinHttpAddRequestHeaders(hRequest.h, extraHeaders.c_str(), (DWORD)-1L, WINHTTP_ADDREQ_FLAG_ADD)) {
            throw std::runtime_error("WinHttpAddRequestHeaders failed");
        }
    }

    LPCVOID bodyPtr = nullptr;
    DWORD bodyLen = 0;
    if (postBody && !postBody->empty()) {
        bodyPtr = postBody->data();
        bodyLen = (DWORD)postBody->size();
    }

    if (!WinHttpSendRequest(hRequest.h, WINHTTP_NO_ADDITIONAL_HEADERS, 0,
                            (LPVOID)bodyPtr, bodyLen, bodyLen, 0)) {
        DWORD err = GetLastError();
        std::wstring msg = L"WinHttpSendRequest failed: " + FormatWinHttpError(err);
        throw std::runtime_error(WideToUtf8(msg));
    }

    if (!WinHttpReceiveResponse(hRequest.h, nullptr)) {
        DWORD err = GetLastError();
        std::wstring msg = L"WinHttpReceiveResponse failed: " + FormatWinHttpError(err);
        throw std::runtime_error(WideToUtf8(msg));
    }

    // Status code
    HttpResponse resp;
    DWORD status = 0, size = sizeof(status);
    if (WinHttpQueryHeaders(hRequest.h,
                            WINHTTP_QUERY_STATUS_CODE | WINHTTP_QUERY_FLAG_NUMBER,
                            WINHTTP_HEADER_NAME_BY_INDEX,
                            &status, &size, WINHTTP_NO_HEADER_INDEX)) {
        resp.status = status;
    }

    // Headers
    DWORD hdrSize = 0;
    WinHttpQueryHeaders(hRequest.h, WINHTTP_QUERY_RAW_HEADERS_CRLF, WINHTTP_HEADER_NAME_BY_INDEX, nullptr, &hdrSize, WINHTTP_NO_HEADER_INDEX);
    if (GetLastError() == ERROR_INSUFFICIENT_BUFFER) {
        std::wstring headers;
        headers.resize(hdrSize / sizeof(wchar_t));
        if (WinHttpQueryHeaders(hRequest.h, WINHTTP_QUERY_RAW_HEADERS_CRLF, WINHTTP_HEADER_NAME_BY_INDEX, &headers[0], &hdrSize, WINHTTP_NO_HEADER_INDEX)) {
            std::wstringstream ss(headers);
            std::wstring line;
            while (std::getline(ss, line)) {
                auto pos = line.find(L':');
                if (pos != std::wstring::npos) {
                    std::wstring name = line.substr(0, pos);
                    std::wstring value = line.substr(pos+1);
                    // trim
                    auto ltrim=[&](std::wstring& s){ s.erase(s.begin(), std::find_if(s.begin(), s.end(), [](wchar_t ch){return !iswspace(ch);})); };
                    auto rtrim=[&](std::wstring& s){ s.erase(std::find_if(s.rbegin(), s.rend(), [](wchar_t ch){return !iswspace(ch);}).base(), s.end()); };
                    ltrim(value); rtrim(value);
                    resp.headers[name]=value;
                }
            }
        }
    }

    // Body
    for (;;) {
        DWORD avail = 0;
        if (!WinHttpQueryDataAvailable(hRequest.h, &avail)) {
            throw std::runtime_error("WinHttpQueryDataAvailable failed");
        }
        if (avail == 0) break;
        size_t off = resp.body.size();
        resp.body.resize(off + avail);
        DWORD read = 0;
        if (!WinHttpReadData(hRequest.h, resp.body.data() + off, avail, &read)) {
            throw std::runtime_error("WinHttpReadData failed");
        }
        resp.body.resize(off + read);
    }

    return resp;
}

// ---------- Simple consensus parser ----------
struct Consensus {
    std::string validAfter;
    std::string freshUntil;
    std::string validUntil;
    struct Router {
        std::string name;
        std::string address;
        uint16_t orPort{0};
        uint16_t dirPort{0};
        std::string identityHex;
    };
    std::vector<Router> routers;
};

static Consensus ParseConsensus(const std::string& text) {
    Consensus c;
    std::istringstream ss(text);
    std::string line;
    Consensus::Router current{};
    bool inRouter = false;

    auto hexOfB64ID = [](const std::string& b64)->std::string{
        // Router identity in consensus is base64-encoded 20-byte SHA1 digest typically; we just keep base64 or decode to hex
        try {
            auto dec = Base64Decode(b64);
            std::ostringstream os;
            for (auto ch : dec) os << std::hex << std::setfill('0') << std::setw(2) << (int)ch;
            return os.str();
        } catch (...) { return ""; }
    };

    while (std::getline(ss, line)) {
        if (!line.empty() && (line.back()=='\r' || line.back()=='\n')) line.pop_back();
        if (line.rfind("valid-after ", 0) == 0) c.validAfter = line.substr(12);
        else if (line.rfind("fresh-until ", 0) == 0) c.freshUntil = line.substr(12);
        else if (line.rfind("valid-until ", 0) == 0) c.validUntil = line.substr(12);
        else if (line.rfind("r ", 0) == 0) {
            // r name identity digest publication address orport dirport
            // Example: r Unnamed 6qg1... Q0Yg... 2024-01-01 00:00:00 1.2.3.4 9001 0
            std::istringstream rs(line);
            std::string tag; rs >> tag;
            Consensus::Router r{};
            rs >> r.name;
            std::string identityB64, digestB64, date, time;
            rs >> identityB64 >> digestB64 >> date >> time >> r.address >> r.orPort >> r.dirPort;
            r.identityHex = hexOfB64ID(identityB64);
            c.routers.push_back(std::move(r));
            inRouter = true;
        } else if (inRouter && (line.rfind("s ", 0) == 0 || line.rfind("v ", 0) == 0)) {
            // Flags/version lines can be ignored for this demo.
        } else if (line.empty() || line[0] != ' ') {
            inRouter = false;
        }
    }
    return c;
}

// ---------- v3 descriptor parser (minimal but working) ----------
struct HSDescriptorV3 {
    std::string hsType;
    std::string version;
    std::string lifetime;
    std::string superencrypted; // base64 decoded size
    std::vector<uint8_t> superencBlob;
    std::string create2Formats;
    std::string introAuthRequired;
    std::string singleOnion;
};

static std::string Trim(const std::string& s) {
    size_t a = 0, b = s.size();
    while (a < b && std::isspace((unsigned char)s[a])) ++a;
    while (b > a && std::isspace((unsigned char)s[b-1])) --b;
    return s.substr(a, b-a);
}

static HSDescriptorV3 ParseDescriptorV3(const std::string& text) {
    HSDescriptorV3 d;
    std::istringstream ss(text);
    std::string line;

    auto readBlock = [&](const std::string& beginTag, const std::string& endTag)->std::string {
        std::ostringstream os;
        bool in=false;
        std::istringstream s2(text);
        std::string l;
        while (std::getline(s2, l)) {
            if (!l.empty() && (l.back()=='\r' || l.back()=='\n')) l.pop_back();
            if (!in) {
                if (l == beginTag) in = true;
            } else {
                if (l == endTag) break;
                os << l << "\n";
            }
        }
        return os.str();
    };

    // Key-value lines
    while (std::getline(ss, line)) {
        if (!line.empty() && (line.back()=='\r' || line.back()=='\n')) line.pop_back();
        if (line.rfind("hs-descriptor ", 0) == 0) d.hsType = Trim(line.substr(13));
        else if (line.rfind("descriptor-lifetime ", 0) == 0) d.lifetime = Trim(line.substr(20));
        else if (line.rfind("revision-counter ", 0) == 0) {/*ignored*/}
        else if (line.rfind("descriptor-signing-key-cert", 0) == 0) {/*block below*/}
        else if (line.rfind("superencrypted", 0) == 0) {/*block below*/}
        else if (line.rfind("create2-formats ", 0) == 0) d.create2Formats = Trim(line.substr(16));
        else if (line.rfind("intro-auth-required ", 0) == 0) d.introAuthRequired = Trim(line.substr(20));
        else if (line.rfind("single-onion ", 0) == 0) d.singleOnion = Trim(line.substr(13));
        else if (line.rfind("version ", 0) == 0) d.version = Trim(line.substr(8));
    }

    // Extract superencrypted block (base64)
    std::string b64 = readBlock("-----BEGIN MESSAGE-----", "-----END MESSAGE-----");
    if (!b64.empty()) {
        try {
            d.superencBlob = Base64Decode(b64);
            d.superencrypted = std::to_string(d.superencBlob.size()) + " bytes";
        } catch (...) {
            d.superencrypted = "decode failed";
        }
    }
    return d;
}

