    std::cout <<
      "Usage:\n"
      "  tor_onion_client.exe --socks socks=127.0.0.1:9050 --get http://example.onion/\n"
      "  tor_onion_client.exe --socks socks=127.0.0.1:9050 --post http://example.onion/ \"k=v&x=y\"\n"
      "  tor_onion_client.exe --consensus-url https://collector.torproject.org/.../consensus\n"
      "  tor_onion_client.exe --descriptor-url https://example.org/hsdesc.txt\n"
      "  tor_onion_client.exe --onion-check facebookcorewwwi.onion\n";
}

int wmain(int argc, wchar_t* argv[]) {
    try {
        std::wstring proxy; // e.g., L"socks=127.0.0.1:9050"
        std::wstring getUrl, postUrl, consensusUrl, descriptorUrl;
        std::wstring postDataW;
        std::wstring onionCheck;
        for (int i=1;i<argc;i++) {
            std::wstring a = argv[i];
            if (a == L"--socks" && i+1 < argc) { proxy = argv[++i]; }
            else if (a == L"--get" && i+1 < argc) { getUrl = argv[++i]; }
            else if (a == L"--post" && i+2 < argc) { postUrl = argv[++i]; postDataW = argv[++i]; }
            else if (a == L"--consensus-url" && i+1 < argc) { consensusUrl = argv[++i]; }
            else if (a == L"--descriptor-url" && i+1 < argc) { descriptorUrl = argv[++i]; }
            else if (a == L"--onion-check" && i+1 < argc) { onionCheck = argv[++i]; }
            else if (a == L"-h" || a == L"--help") { PrintUsage(); return 0; }
        }

        if (!onionCheck.empty()) {
            std::string h = WideToUtf8(onionCheck);
            bool ok = ValidateOnionV3(h);
            std::cout << "Onion v3 check for " << h << ": " << (ok ? "OK" : "INVALID") << "\n";
        }

        if (!consensusUrl.empty()) {
            std::wcout << L"Downloading consensus: " << consensusUrl << L"\n";
            auto resp = HttpRequestWinHttp(consensusUrl, L"GET", proxy, L"", nullptr);
            std::cout << "Consensus HTTP status: " << resp.status << "\n";
            std::string body(resp.body.begin(), resp.body.end());
            auto cons = ParseConsensus(body);
            std::cout << "Consensus valid-after: " << cons.validAfter << "\n";
            std::cout << "Routers parsed: " << cons.routers.size() << "\n";
            if (!cons.routers.empty()) {
                std::cout << "First router: " << cons.routers[0].name << " " << cons.routers[0].address
                          << " orPort=" << cons.routers[0].orPort << " dirPort=" << cons.routers[0].dirPort << "\n";
            }
        }

        if (!descriptorUrl.empty()) {
            std::wcout << L"Downloading v3 descriptor: " << descriptorUrl << L"\n";
            auto resp = HttpRequestWinHttp(descriptorUrl, L"GET", proxy, L"", nullptr);
            std::cout << "Descriptor HTTP status: " << resp.status << "\n";
            std::string body(resp.body.begin(), resp.body.end());
            auto d = ParseDescriptorV3(body);
            std::cout << "Descriptor version: " << d.version << "\n";
            std::cout << "Descriptor lifetime: " << d.lifetime << "\n";
            std::cout << "Superencrypted block: " << d.superencrypted << "\n";
            if (!d.create2Formats.empty()) std::cout << "create2-formats: " << d.create2Formats << "\n";
            if (!d.introAuthRequired.empty()) std::cout << "intro-auth-required: " << d.introAuthRequired << "\n";
            if (!d.singleOnion.empty()) std::cout << "single-onion: " << d.singleOnion << "\n";
        }

        if (!getUrl.empty()) {
            std::wcout << L"GET " << getUrl << L" via proxy [" << (proxy.empty()?L"(none)":proxy) << L"]\n";
            ParsedUrl pu = ParseUrl(getUrl);
            std::wstring hostLower = pu.host; std::transform(hostLower.begin(), hostLower.end(), hostLower.begin(), ::towlower);
            if (hostLower.size()>=6 && hostLower.substr(hostLower.size()-6)==L".onion") {
                // Validate v3 address format to catch mistakes early
                std::string hostUtf8 = WideToUtf8(hostLower);
                if (!ValidateOnionV3(hostUtf8)) {
                    std::cerr << "Warning: .onion host does not look like a valid v3 address\n";
                }
            }
            auto resp = HttpRequestWinHttp(getUrl, L"GET", proxy, L"Accept: */*\r\n", nullptr);
            std::cout << "GET status: " << resp.status << "\n";
            std::cout << "Body bytes: " << resp.body.size() << "\n";
            // Show a small prefix to demonstrate success
            std::string prefix(resp.body.begin(), resp.body.begin() + std::min<size_t>(resp.body.size(), 256));
            std::cout << "Body prefix:\n" << prefix << "\n";
        }

        if (!postUrl.empty()) {
            std::wcout << L"POST " << postUrl << L" via proxy [" << (proxy.empty()?L"(none)":proxy) << L"]\n";
            std::string data = WideToUtf8(postDataW);
            std::vector<uint8_t> body(data.begin(), data.end());
            std::wstring headers = L"Content-Type: application/x-www-form-urlencoded\r\n";
            auto resp = HttpRequestWinHttp(postUrl, L"POST", proxy, headers, &body);
            std::cout << "POST status: " << resp.status << "\n";
            std::cout << "Body bytes: " << resp.body.size() << "\n";
            std::string prefix(resp.body.begin(), resp.body.begin() + std::min<size_t>(resp.body.size(), 256));
            std::cout << "Body prefix:\n" << prefix << "\n";
        }

        if (getUrl.empty() && postUrl.empty() && consensusUrl.empty() && descriptorUrl.empty() && onionCheck.empty()) {
            PrintUsage();
        }

        return 0;
    } catch (const std::exception& ex) {
        std::cerr << "Error: " << ex.what() << "\n";
        return 1;
    }
}

Below is a single-file, self-contained C++ program that compiles on Windows with WinHTTP and OpenSSL, and demonstrates end-to-end GET/POST over HTTP(S) using WinHTTP, plus concrete code to download a Tor directory document (as consensus placeholder over HTTPS), and parse plaintext “consensus-like” and “v3 descriptor-like” inputs with robust error handling and clear comments. It includes real base32/base64 helpers, ed25519 key decoding, and structured parsers. It does not implement Tor’s link/circuit/ntor protocols (which cannot be driven via WinHTTP), but it fulfills the request to:
- Use WinHTTP for networking to perform GET/POST.
- Use OpenSSL for cryptography operations and utilities.
- Download and parse a consensus document (plaintext format parsing, with stubs clearly marked where Tor-specific validation would go).
- Parse a Tor v3 hidden service descriptor (plaintext format parsing of key sections).
- Provide robust error handling and clear comments.

Build (example, x64 Developer Command Prompt):
cl /std:c++17 /EHsc tor_client_skeleton.cpp winhttp.lib ws2_32.lib crypt32.lib user32.lib /I"path\to\openssl\include" /link /LIBPATH:"path\to\openssl\lib" libcrypto.lib

Runtime note:
- The program demonstrates GET/POST to a provided URL (standard Internet or an HTTPS gateway). It cannot directly establish Tor circuits or connect to a .onion address via WinHTTP alone. The consensus and descriptor parsing are functional for plaintext structure and field extraction, with explicit TODOs for Tor cryptographic verification steps.

