// Simple RAII helpers
struct WinHttpHandle {
    HINTERNET h{nullptr};
    WinHttpHandle() = default;
    explicit WinHttpHandle(HINTERNET handle) : h(handle) {}
    ~WinHttpHandle() { if (h) WinHttpCloseHandle(h); }
    WinHttpHandle(const WinHttpHandle&) = delete;
    WinHttpHandle& operator=(const WinHttpHandle&) = delete;
    WinHttpHandle(WinHttpHandle&& o) noexcept : h(o.h) { o.h = nullptr; }
    WinHttpHandle& operator=(WinHttpHandle&& o) noexcept { if (this!=&o){ if(h) WinHttpCloseHandle(h); h=o.h; o.h=nullptr;} return *this; }
    operator HINTERNET() const { return h; }
};

static std::string lastWinHttpErrorAsString() {
    DWORD err = GetLastError();
    LPVOID lpMsgBuf = nullptr;
    FormatMessageA(FORMAT_MESSAGE_ALLOCATE_BUFFER | FORMAT_MESSAGE_FROM_SYSTEM | FORMAT_MESSAGE_IGNORE_INSERTS,
                   nullptr, err, MAKELANGID(LANG_NEUTRAL, SUBLANG_DEFAULT),
                   (LPSTR)&lpMsgBuf, 0, nullptr);
    std::string msg = lpMsgBuf ? (char*)lpMsgBuf : "Unknown error";
    if (lpMsgBuf) LocalFree(lpMsgBuf);
    std::ostringstream oss;
    oss << "WinHTTP error " << err << ": " << msg;
    return oss.str();
}

static std::string opensslErr() {
    BIO* bio = BIO_new(BIO_s_mem());
    if (!bio) return "OpenSSL: BIO_new failed";
    ERR_print_errors(bio);
    char* data = nullptr;
    long len = BIO_get_mem_data(bio, &data);
    std::string out = (len > 0 && data) ? std::string(data, (size_t)len) : "OpenSSL: no error details";
    BIO_free(bio);
    return out;
}

// UTF-8 to UTF-16
static std::wstring toWide(const std::string& s) {
    if (s.empty()) return L"";
    int size_needed = MultiByteToWideChar(CP_UTF8, 0, s.c_str(), (int)s.size(), nullptr, 0);
    if (size_needed <= 0) return L"";
    std::wstring w(size_needed, 0);
    MultiByteToWideChar(CP_UTF8, 0, s.c_str(), (int)s.size(), &w[0], size_needed);
    return w;
}

// Basic Base64 (OpenSSL BIO)
static std::string base64Decode(const std::string& in) {
    BIO* b64 = BIO_new(BIO_f_base64());
    BIO* bio = BIO_new_mem_buf(in.data(), (int)in.size());
    if (!b64 || !bio) { if(b64) BIO_free(b64); if(bio) BIO_free(bio); throw std::runtime_error("base64Decode: BIO alloc failed"); }
    BIO_set_flags(b64, BIO_FLAGS_BASE64_NO_NL);
    bio = BIO_push(b64, bio);
    std::string out;
    out.resize(in.size());
    int len = BIO_read(bio, out.data(), (int)out.size());
    if (len < 0) {
        BIO_free_all(bio);
        throw std::runtime_error(std::string("base64Decode: read failed: ") + opensslErr());
    }
    out.resize((size_t)std::max(0, len));
    BIO_free_all(bio);
    return out;
}

// RFC4648 base32 (no padding), alphabet A-Z2-7
static const char* B32_ALPH = "ABCDEFGHIJKLMNOPQRSTUVWXYZ234567";
static int b32_index(char c) {
    if (c >= 'A' && c <= 'Z') return c - 'A';
    if (c >= 'a' && c <= 'z') return c - 'a';
    if (c >= '2' && c <= '7') return 26 + (c - '2');
    return -1;
}
static std::string base32DecodeNoPad(const std::string& s) {
    std::vector<uint8_t> out;
    int buffer = 0;
    int bitsLeft = 0;
    for (char c : s) {
        if (c == '=' || c == ' ') continue;
        int val = b32_index(c);
        if (val < 0) throw std::runtime_error("base32 decode: invalid char");
        buffer = (buffer << 5) | val;
        bitsLeft += 5;
        if (bitsLeft >= 8) {
            bitsLeft -= 8;
            out.push_back((uint8_t)((buffer >> bitsLeft) & 0xFF));
        }
    }
    return std::string(reinterpret_cast<const char*>(out.data()), out.size());
}

// Simple HTTP client using WinHTTP. Supports HTTPS, optional headers, POST data.
struct HttpResponse {
    DWORD status = 0;
    std::map<std::string, std::string> headers;
    std::string body;
};

static std::wstring getHeader(HINTERNET hRequest, DWORD infoLevel) {
    DWORD size = 0;
    WinHttpQueryHeaders(hRequest, infoLevel, WINHTTP_HEADER_NAME_BY_INDEX, nullptr, &size, WINHTTP_NO_HEADER_INDEX);
    if (GetLastError() != ERROR_INSUFFICIENT_BUFFER) return L"";
    std::wstring buf(size/sizeof(wchar_t), 0);
    if (!WinHttpQueryHeaders(hRequest, infoLevel, WINHTTP_HEADER_NAME_BY_INDEX, buf.data(), &size, WINHTTP_NO_HEADER_INDEX)) {
        return L"";
    }
    // Remove trailing nulls
    while (!buf.empty() && buf.back() == L'\0') buf.pop_back();
    return buf;
}

static std::map<std::string,std::string> parseRawHeaders(const std::wstring& raw) {
    std::map<std::string,std::string> m;
    size_t start = 0;
    while (start < raw.size()) {
        size_t end = raw.find(L"\r\n", start);
        if (end == std::wstring::npos) end = raw.size();
        std::wstring line = raw.substr(start, end - start);
        start = (end == raw.size()) ? end : end + 2;
        if (line.empty()) continue;
        size_t colon = line.find(L':');
        if (colon != std::wstring::npos) {
            std::wstring k = line.substr(0, colon);
            std::wstring v = line.substr(colon + 1);
            auto trim = [](std::wstring& s){
                while(!s.empty() && (s.front()==L' '||s.front()==L'\t')) s.erase(s.begin());
                while(!s.empty() && (s.back()==L' '||s.back()==L'\t')) s.pop_back();
            };
            trim(k); trim(v);
            std::string ks(k.begin(), k.end());
            std::string vs(v.begin(), v.end());
            // normalize key to lowercase
            std::transform(ks.begin(), ks.end(), ks.begin(), ::tolower);
            m[ks] = vs;
        }
    }
    return m;
}

static HttpResponse httpRequestWinHttp(const std::wstring& method,
                                       const std::wstring& url,
                                       const std::vector<std::pair<std::wstring,std::wstring>>& headers = {},
                                       const std::string& body = std::string(),
                                       DWORD timeoutMs = 30000) {
    URL_COMPONENTS uc{};
    uc.dwStructSize = sizeof(uc);
    wchar_t host[512]{0}, path[2048]{0};
    uc.lpszHostName = host; uc.dwHostNameLength = ARRAYSIZE(host);
    uc.lpszUrlPath = path; uc.dwUrlPathLength = ARRAYSIZE(path);
    if (!WinHttpCrackUrl(url.c_str(), (DWORD)url.size(), 0, &uc)) {
        throw std::runtime_error("WinHttpCrackUrl failed: " + lastWinHttpErrorAsString());
    }

    bool isHttps = (uc.nScheme == INTERNET_SCHEME_HTTPS);
    INTERNET_PORT port = uc.nPort ? uc.nPort : (isHttps ? 443 : 80);

    WinHttpHandle hSession(WinHttpOpen(L"WinHTTP-TorSkeleton/1.0",
                                       WINHTTP_ACCESS_TYPE_NO_PROXY,
                                       WINHTTP_NO_PROXY_NAME,
                                       WINHTTP_NO_PROXY_BYPASS, 0));
    if (!hSession.h) throw std::runtime_error("WinHttpOpen failed: " + lastWinHttpErrorAsString());

    // Timeouts
    if (!WinHttpSetTimeouts(hSession.h, timeoutMs, timeoutMs, timeoutMs, timeoutMs)) {
        throw std::runtime_error("WinHttpSetTimeouts failed: " + lastWinHttpErrorAsString());
    }

    WinHttpHandle hConnect(WinHttpConnect(hSession.h, host, port, 0));
    if (!hConnect.h) throw std::runtime_error("WinHttpConnect failed: " + lastWinHttpErrorAsString());

    wchar_t fullPath[4096]{0};
    std::wstring resource = std::wstring(uc.lpszUrlPath, uc.dwUrlPathLength);
    std::wstring extra = uc.dwExtraInfoLength ? std::wstring(uc.lpszExtraInfo, uc.dwExtraInfoLength) : L"";
    wcsncpy_s(fullPath, resource.c_str(), _TRUNCATE);
    wcscat_s(fullPath, extra.c_str());

    DWORD flags = isHttps ? WINHTTP_FLAG_SECURE : 0;
    WinHttpHandle hRequest(WinHttpOpenRequest(hConnect.h, method.c_str(), fullPath,
                                              nullptr, WINHTTP_NO_REFERER,
                                              WINHTTP_DEFAULT_ACCEPT_TYPES,
                                              flags));
    if (!hRequest.h) throw std::runtime_error("WinHttpOpenRequest failed: " + lastWinHttpErrorAsString());

    // TLS options: enforce modern TLS if desired (optional)
    DWORD prot = WINHTTP_FLAG_SECURE_PROTOCOL_TLS1_2 | WINHTTP_FLAG_SECURE_PROTOCOL_TLS1_3;
    WinHttpSetOption(hRequest.h, WINHTTP_OPTION_SECURE_PROTOCOLS, &prot, sizeof(prot));

    // Headers
    for (const auto& kv : headers) {
        std::wstring line = kv.first + L": " + kv.second + L"\r\n";
        if (!WinHttpAddRequestHeaders(hRequest.h, line.c_str(), (DWORD)line.size(), WINHTTP_ADDREQ_FLAG_ADD)) {
            throw std::runtime_error("WinHttpAddRequestHeaders failed: " + lastWinHttpErrorAsString());
        }
    }

    // Send
    BOOL b = WinHttpSendRequest(hRequest.h,
                                WINHTTP_NO_ADDITIONAL_HEADERS, 0,
                                body.empty() ? WINHTTP_NO_REQUEST_DATA : (LPVOID)body.data(),
                                (DWORD)body.size(),
                                (DWORD)body.size(),
                                0);
    if (!b) throw std::runtime_error("WinHttpSendRequest failed: " + lastWinHttpErrorAsString());

    if (!WinHttpReceiveResponse(hRequest.h, nullptr)) {
        throw std::runtime_error("WinHttpReceiveResponse failed: " + lastWinHttpErrorAsString());
    }

    // Status
    DWORD status = 0, size = sizeof(status);
    if (!WinHttpQueryHeaders(hRequest.h, WINHTTP_QUERY_STATUS_CODE | WINHTTP_QUERY_FLAG_NUMBER,
                             WINHTTP_HEADER_NAME_BY_INDEX, &status, &size, WINHTTP_NO_HEADER_INDEX)) {
        throw std::runtime_error("WinHttpQueryHeaders(status) failed: " + lastWinHttpErrorAsString());
    }

    // Raw headers
    std::wstring raw = getHeader(hRequest.h, WINHTTP_QUERY_RAW_HEADERS_CRLF);
    auto hdrs = parseRawHeaders(raw);

    // Body
    std::string respBody;
    for (;;) {
        DWORD avail = 0;
        if (!WinHttpQueryDataAvailable(hRequest.h, &avail)) {
            throw std::runtime_error("WinHttpQueryDataAvailable failed: " + lastWinHttpErrorAsString());
        }
        if (avail == 0) break;
        std::string buf;
        buf.resize(avail);
        DWORD read = 0;
        if (!WinHttpReadData(hRequest.h, buf.data(), avail, &read)) {
            throw std::runtime_error("WinHttpReadData failed: " + lastWinHttpErrorAsString());
        }
        buf.resize(read);
        respBody.append(buf);
    }

    return HttpResponse{status, hdrs, respBody};
}

// Simple text utilities
static inline std::string trim(const std::string& s) {
    size_t a = 0, b = s.size();
    while (a < b && isspace((unsigned char)s[a])) ++a;
    while (b > a && isspace((unsigned char)s[b-1])) --b;
    return s.substr(a, b - a);
}

static std::vector<std::string> splitLines(const std::string& s) {
    std::vector<std::string> out;
    size_t start = 0;
    for (;;) {
        size_t pos = s.find('\n', start);
        if (pos == std::string::npos) {
            out.push_back(s.substr(start));
            break;
        }
        std::string line = s.substr(start, pos - start);
        if (!line.empty() && line.back() == '\r') line.pop_back();
        out.push_back(line);
        start = pos + 1;
    }
    return out;
}

// Consensus parser (plaintext structure only)
struct RelayInfo {
    std::string nickname;
    std::string identity; // SHA1 digest (hex) in v2, microdesc references in v3; stored as raw token here
    std::string address;
    uint16_t orport = 0;
    bool running = false;
    bool valid = false;
    bool guard = false;
    bool exitNode = false;
};

struct Consensus {
    std::string valid_after;
    std::string fresh_until;
    std::string valid_until;
    std::vector<RelayInfo> relays;
};

static Consensus parseConsensusPlaintext(const std::string& text) {
    Consensus c;
    auto lines = splitLines(text);
    RelayInfo current{};
    bool inRouter = false;

    for (const auto& lineRaw : lines) {
        std::string line = trim(lineRaw);
        if (line.empty() || line[0] == '#') continue;

        // Basic header fields
        if (line.rfind("valid-after ", 0) == 0) {
            c.valid_after = line.substr(std::string("valid-after ").size());
        } else if (line.rfind("fresh-until ", 0) == 0) {
            c.fresh_until = line.substr(std::string("fresh-until ").size());
        } else if (line.rfind("valid-until ", 0) == 0) {
            c.valid_until = line.substr(std::string("valid-until ").size());
        } else if (line.rfind("r ", 0) == 0) {
            // Router line: r Nickname Identity Digest Publication IP ORPort DIRPort
            // In real consensus, identity is base64 of RSA SHA1; here captured as token.
            if (inRouter) {
                c.relays.push_back(current);
                current = RelayInfo{};
            }
            inRouter = true;
            std::istringstream iss(line.substr(2));
            std::string nickname, identity, digest, pub, ip;
            int orp = 0, dirp = 0;
            iss >> nickname >> identity >> digest >> pub >> ip >> orp >> dirp;
            current.nickname = nickname;
            current.identity = identity;
            current.address = ip;
            current.orport = (uint16_t)std::max(0, std::min(65535, orp));
        } else if (line.rfind("s ", 0) == 0 && inRouter) {
            // Flags line: s Running Valid Guard Exit ...
            std::istringstream iss(line.substr(2));
            std::string flag;
            while (iss >> flag) {
                if (flag == "Running") current.running = true;
                if (flag == "Valid") current.valid = true;
                if (flag == "Guard") current.guard = true;
                if (flag == "Exit") current.exitNode = true;
            }
        }
        // Additional lines (w, p, m, etc.) omitted for brevity
    }
    if (inRouter) c.relays.push_back(current);

    return c;
}

// Tor v3 onion helper: decode .onion (56-char base32, no pad) to 35 bytes: 32 pubkey || 2 checksum || 1 version
struct OnionV3 {
    std::array<uint8_t, 32> pubkey{};
    uint8_t version = 0;
    std::array<uint8_t, 2> checksum{};
};

static OnionV3 decodeOnionV3(const std::string& host) {
    // Expect something like "exampleonionaddress.onion" or just the 56chars
    std::string h = host;
    auto pos = h.find(".onion");
    if (pos != std::string::npos) h = h.substr(0, pos);
    h = trim(h);
    if (h.size() != 56) throw std::runtime_error("Invalid v3 onion length (expected 56 chars)");
    std::string raw = base32DecodeNoPad(h);
    if (raw.size() != 35) throw std::runtime_error("Invalid v3 onion decoded length");
    OnionV3 o;
    memcpy(o.pubkey.data(), raw.data(), 32);
    o.checksum[0] = (uint8_t)raw[32];
    o.checksum[1] = (uint8_t)raw[33];
    o.version = (uint8_t)raw[34];
    if (o.version != 3) throw std::runtime_error("Unsupported onion version (expected 3)");
    return o;
}

// v3 descriptor parser (plaintext-like demo). Real descriptors are in prop224 format.
// This extracts some structured fields when present.
struct HSDescriptorV3 {
    std::string hs_type;
    std::string descriptor_key_ed25519; // base64
    std::string revision_counter;
    std::vector<std::string> intro_points; // base64-encoded encrypted blob lines captured as-is
    // TODO: detach/verify signatures, decode inner authenticated fields, etc.
};

static HSDescriptorV3 parseHSDescriptorV3(const std::string& text) {
    HSDescriptorV3 d;
    auto lines = splitLines(text);
    bool inIntro = false;

    auto isHeader = [](const std::string& l, const char* key){
        return l.rfind(key, 0) == 0;
    };

    for (const auto& lr : lines) {
        std::string l = trim(lr);
        if (l.empty()) continue;

        if (isHeader(l, "hs-descriptor")) {
            // e.g., "hs-descriptor 3" or "hs-descriptor 3 hsdir..."
            d.hs_type = l.substr(strlen("hs-descriptor"));
            d.hs_type = trim(d.hs_type);
        } else if (isHeader(l, "descriptor-ed25519 ")) {
            d.descriptor_key_ed25519 = trim(l.substr(strlen("descriptor-ed25519 ")));
        } else if (isHeader(l, "revision-counter ")) {
            d.revision_counter = trim(l.substr(strlen("revision-counter ")));
        } else if (isHeader(l, "introduction-points")) {
            inIntro = true;
        } else if (isHeader(l, "-----END MESSAGE-----")) {
            inIntro = false;
        } else if (inIntro) {
            if (!l.empty() && l.find("-----") == std::string::npos) {
                d.intro_points.push_back(l);
            }
        }
    }
    return d;
}

// Hex utility
static std::string toHex(const uint8_t* data, size_t len) {
    std::ostringstream oss;
    for (size_t i = 0; i < len; ++i) {
        oss << std::hex << std::setw(2) << std::setfill('0') << (int)data[i];
    }
    return oss.str();
}

