// Demo: download a "consensus-like" doc from a URL and parse
static Consensus fetchAndParseConsensus(const std::wstring& url) {
    auto resp = httpRequestWinHttp(L"GET", url, {
        {L"User-Agent", L"WinHTTP-TorSkeleton/1.0"},
        {L"Accept", L"text/plain, */*"}
    });
    if (resp.status != 200) {
        std::ostringstream oss;
        oss << "Consensus fetch failed: HTTP " << resp.status;
        throw std::runtime_error(oss.str());
    }
    // In real Tor: verify signatures of consensus and microdescriptors
    Consensus c = parseConsensusPlaintext(resp.body);
    if (c.relays.empty()) {
        // Not necessarily an error for placeholder text, but we flag it
        fprintf(stderr, "Warning: parsed 0 relays from consensus document\n");
    }
    return c;
}

// Demo: download v3 descriptor from an HTTPS endpoint (placeholder). Real Tor uses HSDirs.
// You can point this to a local test file served over HTTPS with descriptor content.
static HSDescriptorV3 fetchAndParseHSDescriptor(const std::wstring& url) {
    auto resp = httpRequestWinHttp(L"GET", url, {
        {L"User-Agent", L"WinHTTP-TorSkeleton/1.0"},
        {L"Accept", L"text/plain, */*"}
    });
    if (resp.status != 200) {
        std::ostringstream oss;
        oss << "Descriptor fetch failed: HTTP " << resp.status;
        throw std::runtime_error(oss.str());
    }
    HSDescriptorV3 d = parseHSDescriptorV3(resp.body);
    if (d.hs_type.empty()) {
        fprintf(stderr, "Warning: descriptor did not include hs-descriptor header\n");
    }
    return d;
}

