        printf("  PubKey (ed25519) hex: %s\n", toHex(v3.pubkey.data(), v3.pubkey.size()).c_str());
        printf("  Version: %u\n", (unsigned)v3.version);
        printf("  Checksum: %02x%02x\n", v3.checksum[0], v3.checksum[1]);
    } catch (const std::exception& ex) {
        fprintf(stderr, "Onion decode error: %s\n", ex.what());
    }
}

