int wmain(int argc, wchar_t* argv[]) {
    OpenSSLGlobal openssl; // Initialize OpenSSL

    try {
        if (argc <= 1) {
            usage();
            return 0;
        }

        std::map<std::wstring, std::wstring> args;
        for (int i = 1; i < argc; ++i) {
            std::wstring k = argv[i];
            std::wstring v;
            if ((k == L"--get" || k == L"--post" || k == L"--consensus" || k == L"--descriptor" || k == L"--onion") && i + 1 < argc) {
                v = argv[++i];
            } else if (k == L"--data" && i + 1 < argc) {
                v = argv[++i];
            }
            args[k] = v;
        }

        if (args.count(L"--get")) {
            demoHttpGet(args[L"--get"]);
        }
        if (args.count(L"--post")) {
            std::wstring wurl = args[L"--post"];
            std::wstring wdata = args.count(L"--data") ? args[L"--data"] : L"{}";
            std::string data(wdata.begin(), wdata.end());
            demoHttpPost(wurl, data);
        }
        if (args.count(L"--consensus")) {
            Consensus c = fetchAndParseConsensus(args[L"--consensus"]);
            printf("Consensus summary:\n");
            printf("  valid-after: %s\n", c.valid_after.c_str());
            printf("  fresh-until: %s\n", c.fresh_until.c_str());
            printf("  valid-until: %s\n", c.valid_until.c_str());
            printf("  relays: %zu\n", c.relays.size());
            size_t shown = 0;
            for (const auto& r : c.relays) {
                if (shown++ >= 5) break;
                printf("    - %s @ %s:%u flags:[%s%s%s%s]\n",
                    r.nickname.c_str(), r.address.c_str(), r.orport,
                    r.running ? "Running " : "",
                    r.valid ? "Valid " : "",
                    r.guard ? "Guard " : "",
                    r.exitNode ? "Exit " : "");
            }
            if (c.relays.empty()) {
                printf("Note: The fetched document may not be a real Tor consensus.\n");
            }
        }
        if (args.count(L"--descriptor")) {
            HSDescriptorV3 d = fetchAndParseHSDescriptor(args[L"--descriptor"]);
            printf("Descriptor summary:\n");
            printf("  hs-descriptor: %s\n", d.hs_type.c_str());
            printf("  descriptor-ed25519: %s\n", d.descriptor_key_ed25519.c_str());
            printf("  revision-counter: %s\n", d.revision_counter.c_str());
            printf("  intro-points lines: %zu\n", d.intro_points.size());
            if (!d.intro_points.empty()) {
                printf("    first line: %s\n", d.intro_points.front().c_str());
            }
            if (d.hs_type.empty()) {
                printf("Note: The fetched document may not be a real Tor v3 descriptor or uses different formatting.\n");
            }
        }
        if (args.count(L"--onion")) {
            std::wstring wonion = args[L"--onion"];
            std::string onion(wonion.begin(), wonion.end());
            demoOnionDecode(onion);
        }

        if (!args.count(L"--get") && !args.count(L"--post") &&
            !args.count(L"--consensus") && !args.count(L"--descriptor") &&
            !args.count(L"--onion")) {
            usage();
        }
    } catch (const std::exception& ex) {
        fprintf(stderr, "Fatal error: %s\n", ex.what());
        fprintf(stderr, "OpenSSL errs (if any): %s\n", opensslErr().c_str());
        return 1;
    }
    return 0;
}
