// Base64 decode using OpenSSL
static bool Base64Decode(const std::string& in, std::vector<unsigned char>& out) {
    BIO* b64 = BIO_new(BIO_f_base64());
    BIO* mem = BIO_new_mem_buf(in.data(), (int)in.size());
    if (!b64 || !mem) { if (b64) BIO_free(b64); if (mem) BIO_free(mem); return false; }
    BIO_set_flags(b64, BIO_FLAGS_BASE64_NO_NL);
    BIO* chain = BIO_push(b64, mem);
    out.resize(in.size()); // upper bound
    int n = BIO_read(chain, out.data(), (int)out.size());
    if (n <= 0) { BIO_free_all(chain); out.clear(); return false; }
    out.resize((size_t)n);
    BIO_free_all(chain);
    return true;
}

// Simple URL parser for http/https schemes
struct ParsedUrl {
    bool https{false};
    std::wstring host;
    INTERNET_PORT port{0};
    std::wstring path; // includes leading '/'
};
static bool ParseUrl(const std::wstring& url, ParsedUrl& out) {
    out = ParsedUrl{};
    const std::wstring http = L"http://";
    const std::wstring https = L"https://";
    size_t pos = std::wstring::npos;
    if (url.rfind(http, 0) == 0) { out.https = false; pos = http.size(); out.port = 80; }
    else if (url.rfind(https, 0) == 0) { out.https = true; pos = https.size(); out.port = 443; }
    else {
        // For .onion via Tor SOCKS, permit "http://", not raw ".onion" without scheme.
        return false;
    }
    size_t slash = url.find(L'/', pos);
    std::wstring hostport = (slash == std::wstring::npos) ? url.substr(pos) : url.substr(pos, slash - pos);
    out.path = (slash == std::wstring::npos) ? L"/" : url.substr(slash);
    size_t colon = hostport.find(L':');
    if (colon == std::wstring::npos) {
        out.host = hostport;
    } else {
        out.host = hostport.substr(0, colon);
        std::wstring p = hostport.substr(colon + 1);
        out.port = (INTERNET_PORT)_wtoi(p.c_str());
        if (out.port == 0) return false;
    }
    if (out.host.empty()) return false;
    return true;
}

// Proxy configuration helper: set explicit proxy string like "socks=127.0.0.1:9050"
static bool SetExplicitProxy(HINTERNET hSession, const std::wstring& proxy) {
    WINHTTP_PROXY_INFO pi{};
    pi.dwAccessType = WINHTTP_ACCESS_TYPE_NAMED_PROXY;
    pi.lpszProxy = const_cast<wchar_t*>(proxy.c_str());
    return WinHttpSetOption(hSession, WINHTTP_OPTION_PROXY, &pi, sizeof(pi));
}

// HTTP(S) request helper
static bool HttpRequest(const std::wstring& url, const std::wstring& method, const std::string* body,
                        std::map<std::wstring, std::wstring>* resp_headers, std::string& resp_body,
                        bool force_proxy = false, const std::wstring& proxy_str = L"") {
    resp_body.clear();
    if (resp_headers) resp_headers->clear();

    ParsedUrl pu;
    if (!ParseUrl(url, pu)) {
        std::wcerr << L"Invalid URL: " << url << L"\n";
        return false;
    }

    WinHttpHandle hSession(WinHttpOpen(L"WinHTTP-Tor-Client/1.0",
                                       WINHTTP_ACCESS_TYPE_DEFAULT_PROXY,
                                       WINHTTP_NO_PROXY_NAME,
                                       WINHTTP_NO_PROXY_BYPASS, 0));
    if (!hSession) {
        std::wcerr << L"WinHttpOpen failed: " << FormatLastError() << L"\n";
        return false;
    }

    if (force_proxy && !proxy_str.empty()) {
        if (!SetExplicitProxy(hSession, proxy_str)) {
            std::wcerr << L"WinHttpSetOption(PROXY) failed: " << FormatLastError() << L"\n";
            return false;
        }
    }

    WinHttpHandle hConnect(WinHttpConnect(hSession, pu.host.c_str(), pu.port, 0));
    if (!hConnect) {
        std::wcerr << L"WinHttpConnect failed: " << FormatLastError() << L"\n";
        return false;
    }

    DWORD flags = pu.https ? WINHTTP_FLAG_SECURE : 0;
    WinHttpHandle hRequest(WinHttpOpenRequest(hConnect, method.c_str(), pu.path.c_str(),
                                              nullptr, WINHTTP_NO_REFERER,
                                              WINHTTP_DEFAULT_ACCEPT_TYPES, flags));
    if (!hRequest) {
        std::wcerr << L"WinHttpOpenRequest failed: " << FormatLastError() << L"\n";
        return false;
    }

    // For HTTPS, enforce modern TLS where possible
    DWORD secFlags = SECURITY_FLAG_IGNORE_UNKNOWN_CA | SECURITY_FLAG_IGNORE_CERT_CN_INVALID |
                     SECURITY_FLAG_IGNORE_CERT_DATE_INVALID | SECURITY_FLAG_IGNORE_CERT_WRONG_USAGE;
    // Comment the next line to enforce strict cert validation.
    WinHttpSetOption(hRequest, WINHTTP_OPTION_SECURITY_FLAGS, &secFlags, sizeof(secFlags));

    std::wstring headers = L"User-Agent: WinHTTP-Tor-Client/1.0\r\nAccept: */*\r\n";
    LPCVOID optBody = WINHTTP_NO_REQUEST_DATA;
    DWORD bodyLen = 0;
    if (body) {
        headers += L"Content-Type: application/x-www-form-urlencoded\r\n";
        optBody = body->data();
        bodyLen = (DWORD)body->size();
    }

    if (!WinHttpSendRequest(hRequest, headers.c_str(), (DWORD)-1, (LPVOID)optBody, bodyLen, bodyLen, 0)) {
        std::wcerr << L"WinHttpSendRequest failed: " << FormatLastError() << L"\n";
        return false;
    }
    if (!WinHttpReceiveResponse(hRequest, nullptr)) {
        std::wcerr << L"WinHttpReceiveResponse failed: " << FormatLastError() << L"\n";
        return false;
    }

    // Read headers
    DWORD dwSize = 0;
    WinHttpQueryHeaders(hRequest, WINHTTP_QUERY_RAW_HEADERS_CRLF, WINHTTP_HEADER_NAME_BY_INDEX, nullptr, &dwSize, WINHTTP_NO_HEADER_INDEX);
    if (GetLastError() == ERROR_INSUFFICIENT_BUFFER) {
        std::wstring hdrs(dwSize / sizeof(wchar_t), L'\0');
        if (WinHttpQueryHeaders(hRequest, WINHTTP_QUERY_RAW_HEADERS_CRLF, WINHTTP_HEADER_NAME_BY_INDEX, &hdrs[0], &dwSize, WINHTTP_NO_HEADER_INDEX)) {
            if (resp_headers) {
                std::wstringstream ss(hdrs);
                std::wstring line;
                while (std::getline(ss, line)) {
                    if (line.size() && (line.back() == L'\r' || line.back() == L'\n')) line.pop_back();
                    size_t colon = line.find(L':');
                    if (colon != std::wstring::npos) {
                        std::wstring k = line.substr(0, colon);
                        std::wstring v = line.substr(colon + 1);
                        // trim
                        auto ltrim = [](std::wstring& s) {
                            s.erase(s.begin(), std::find_if(s.begin(), s.end(), [](wchar_t c){return !iswspace(c);}));};
                        auto rtrim = [](std::wstring& s) {
                            s.erase(std::find_if(s.rbegin(), s.rend(), [](wchar_t c){return !iswspace(c);}).base(), s.end());};
                        ltrim(v); rtrim(v);
                        (*resp_headers)[k] = v;
                    }
                }
            }
        }
    }

    // Read body
    std::string buffer;
    for (;;) {
        DWORD avail = 0;
        if (!WinHttpQueryDataAvailable(hRequest, &avail)) {
            std::wcerr << L"WinHttpQueryDataAvailable failed: " << FormatLastError() << L"\n";
            return false;
        }
        if (!avail) break;
        std::string tmp(avail, '\0');
        DWORD read = 0;
        if (!WinHttpReadData(hRequest, &tmp[0], avail, &read)) {
            std::wcerr << L"WinHttpReadData failed: " << FormatLastError() << L"\n";
            return false;
        }
        tmp.resize(read);
        buffer.append(tmp);
    }
    resp_body.swap(buffer);
    return true;
}

// Simple Tor consensus parser: extract valid-after, fresh-until, and relay fingerprints/names
struct TorConsensus {
    std::string valid_after;
    std::string fresh_until;
    struct Relay { std::string nick; std::string fp_hex; std::string address; int or_port{0}; };
    std::vector<Relay> relays;
};
static TorConsensus ParseConsensus(const std::string& text) {
    TorConsensus c{};
    std::istringstream ss(text);
    std::string line;
    TorConsensus::Relay cur{};
    bool in_router = false;
    while (std::getline(ss, line)) {
        if (line.rfind("valid-after ", 0) == 0) {
            c.valid_after = line.substr(12);
        } else if (line.rfind("fresh-until ", 0) == 0) {
            c.fresh_until = line.substr(12);
        } else if (line.rfind("r ", 0) == 0) {
            // r Nickname Identity Digest Publication IP ORPort DirPort
            std::istringstream ls(line);
            std::string tag; ls >> tag;
            ls >> cur.nick;
            std::string fp_b64; ls >> fp_b64;
            std::string digest; ls >> digest;
            std::string pub1, pub2; ls >> pub1 >> pub2; // ignore publication date/time
            ls >> cur.address;
            ls >> cur.or_port;
            // Decode the 20-byte identity fingerprint (base64), then hex-encode
            std::vector<unsigned char> id;
            cur.fp_hex.clear();
            if (Base64Decode(fp_b64, id)) {
                std::ostringstream hx;
                for (unsigned char b : id) hx << std::hex << std::setw(2) << std::setfill('0') << (int)b;
                cur.fp_hex = hx.str();
            }
            in_router = true;
        } else if (in_router && (line.rfind("a ", 0) == 0 || line.rfind("s ", 0) == 0 || line.rfind("v ", 0) == 0)) {
            // ignore auxiliary lines for brevity
            (void)0;
        } else if (in_router && (line.rfind("w ", 0) == 0 || line.rfind("p ", 0) == 0)) {
            // end of router block (heuristic); push and reset
            c.relays.push_back(cur);
            cur = TorConsensus::Relay{};
            in_router = false;
        }
    }
    if (in_router) c.relays.push_back(cur);
    return c;
}

// Tor v3 HS descriptor minimal parser: extracts onion address, blinded pubkey, intro points count
struct HsDescriptorV3 {
    std::string onion_address;
    std::string blinded_key_b64;
    int intro_point_count{0};
};
static HsDescriptorV3 ParseHsDescriptorV3(const std::string& text) {
    HsDescriptorV3 d{};
    std::istringstream ss(text);
    std::string line;
    bool in_intro = false;
    while (std::getline(ss, line)) {
        if (line.rfind("hs-descriptor ", 0) == 0) {
            // version and encoded address may follow in some dumps
        } else if (line.rfind("descriptor-signing-key", 0) == 0) {
            // skip block
        } else if (line.rfind("superencrypted", 0) == 0) {
            // skip
        } else if (line.rfind("create2-formats ", 0) == 0) {
            // skip
        } else if (line.rfind("blinded-key ", 0) == 0) {
            // e.g., "blinded-key ntor <base64>"
            std::istringstream ls(line);
            std::string t, alg, b64;
            ls >> t >> alg >> b64;
            d.blinded_key_b64 = b64;
        } else if (line.rfind("introduction-point", 0) == 0) {
            in_intro = true;
            d.intro_point_count++;
        } else if (in_intro && line == "-----END MESSAGE-----") {
            in_intro = false;
        } else if (line.rfind("onion-address ", 0) == 0) {
            d.onion_address = line.substr(std::string("onion-address ").size());
        }
    }
    return d;
}

