// CLI
static void PrintUsage() {
    std::wcout << L"Usage:\n"
               << L"  --consensus <https-url>\n"
               << L"  --descriptor <https-url>\n"
               << L"  --get <http[s]://host[:port]/path>\n"
               << L"  --post <http[s]://host[:port]/path> <data>\n"
               << L"  --onion-get <http://name.onion[:port]/path> [socks=127.0.0.1:9050]\n"
               << L"  --onion-post <http://name.onion[:port]/path> <data> [socks=127.0.0.1:9050]\n";
}

int wmain(int argc, wchar_t* argv[]) {
    OpenSSLInit ossl;

    if (argc < 3) {
        PrintUsage();
        return 1;
    }

    std::wstring cmd = argv[1];

    if (cmd == L"--consensus" && argc >= 3) {
        std::wstring url = argv[2];
        std::string body;
        if (!DownloadText(url, body)) {
            std::wcerr << L"Failed to download consensus from " << url << L"\n";
            return 2;
        }
        TorConsensus c = ParseConsensus(body);
        std::wcout << L"Consensus valid-after: " << Utf8ToWide(c.valid_after) << L"\n";
        std::wcout << L"Consensus fresh-until: " << Utf8ToWide(c.fresh_until) << L"\n";
        std::wcout << L"Relays parsed: " << c.relays.size() << L"\n";
        if (!c.relays.empty()) {
            std::wcout << L"First relay: " << Utf8ToWide(c.relays[0].nick) << L" "
                       << Utf8ToWide(c.relays[0].address) << L":" << c.relays[0].or_port
                       << L" fp=" << Utf8ToWide(c.relays[0].fp_hex) << L"\n";
        }
        return 0;
    } else if (cmd == L"--descriptor" && argc >= 3) {
        std::wstring url = argv[2];
        std::string body;
        if (!DownloadText(url, body)) {
            std::wcerr << L"Failed to download descriptor from " << url << L"\n";
            return 2;
        }
        HsDescriptorV3 d = ParseHsDescriptorV3(body);
        std::wcout << L"Descriptor onion-address: " << Utf8ToWide(d.onion_address) << L"\n";
        std::wcout << L"Blinded key (b64) length: " << d.blinded_key_b64.size() << L"\n";
        std::wcout << L"Introduction points: " << d.intro_point_count << L"\n";
        return 0;
    } else if (cmd == L"--get" && argc >= 3) {
        std::wstring url = argv[2];
        std::string body;
        if (!HttpGetSimple(url, body)) {
            std::wcerr << L"GET failed for " << url << L"\n";
            return 2;
        }
        std::wcout << L"Body (" << body.size() << L" bytes):\n";
        std::wcout << Utf8ToWide(body) << L"\n";
        return 0;
    } else if (cmd == L"--post" && argc >= 4) {
        std::wstring url = argv[2];
        std::wstring dataW = argv[3];
        std::string data = WideToUtf8(dataW);
        std::string body;
        if (!HttpPostSimple(url, data, body)) {
            std::wcerr << L"POST failed for " << url << L"\n";
            return 2;
        }
        std::wcout << L"Body (" << body.size() << L" bytes):\n";
        std::wcout << Utf8ToWide(body) << L"\n";
        return 0;
    } else if (cmd == L"--onion-get" && (argc == 3 || argc == 4)) {
        std::wstring url = argv[2];
        std::wstring socks = (argc == 4) ? argv[3] : L"socks=127.0.0.1:9050";
        std::string body;
        if (!OnionGetViaTor(url, body, socks)) {
            std::wcerr << L"Onion GET failed for " << url << L" via " << socks << L"\n";
            return 3;
        }
        std::wcout << L"Body (" << body.size() << L" bytes):\n";
        std::wcout << Utf8ToWide(body) << L"\n";
        return 0;
    } else if (cmd == L"--onion-post" && (argc == 4 || argc == 5)) {
        std::wstring url = argv[2];
        std::wstring dataW = argv[3];
        std::wstring socks = (argc == 5) ? argv[4] : L"socks=127.0.0.1:9050";
        std::string data = WideToUtf8(dataW);
        std::string body;
        if (!OnionPostViaTor(url, data, body, socks)) {
            std::wcerr << L"Onion POST failed for " << url << L" via " << socks << L"\n";
            return 3;
        }
        std::wcout << L"Body (" << body.size() << L" bytes):\n";
        std::wcout << Utf8ToWide(body) << L"\n";
        return 0;
    } else {
        PrintUsage();
        return 1;
    }
}

