//   tor_client.exe --consensus-url https://collector.torproject.org/.../consensus
//   tor_client.exe --descriptor-url https://example.com/hsdesc.txt
//   tor_client.exe --onion abcdef...onion --get /path --post /path "key=value"
// Notes:
//   - This program demonstrates parsing and HTTP(S) I/O via WinHTTP.
//   - Real Tor circuit construction and rendezvous is not implemented here.

