// -------------------- Error helpers --------------------
static std::wstring Utf8ToWide(const std::string& s) {
    if (s.empty()) return L"";
    int len = MultiByteToWideChar(CP_UTF8, 0, s.c_str(), (int)s.size(), nullptr, 0);
    std::wstring w(len, 0);
    MultiByteToWideChar(CP_UTF8, 0, s.c_str(), (int)s.size(), &w[0], len);
    return w;
}
static std::string WideToUtf8(const std::wstring& w) {
    if (w.empty()) return "";
    int len = WideCharToMultiByte(CP_UTF8, 0, w.c_str(), (int)w.size(), nullptr, 0, nullptr, nullptr);
    std::string s(len, 0);
    WideCharToMultiByte(CP_UTF8, 0, w.c_str(), (int)w.size(), &s[0], len, nullptr, nullptr);
    return s;
}
static std::string LastErrorMessage(DWORD err = GetLastError()) {
    LPWSTR buf = nullptr;
    DWORD n = FormatMessageW(FORMAT_MESSAGE_ALLOCATE_BUFFER | FORMAT_MESSAGE_FROM_SYSTEM | FORMAT_MESSAGE_IGNORE_INSERTS,
                             nullptr, err, 0, (LPWSTR)&buf, 0, nullptr);
    std::wstring w = (n && buf) ? std::wstring(buf, n) : L"Unknown error";
    if (buf) LocalFree(buf);
    std::string s = WideToUtf8(w);
    // trim newline
    while (!s.empty() && (s.back() == '\r' || s.back() == '\n')) s.pop_back();
    return s;
}
struct WinHttpDeleter {
    void operator()(HINTERNET h) const { if (h) WinHttpCloseHandle(h); }
};
using WinHttpHandle = std::unique_ptr<std::remove_pointer<HINTERNET>::type, WinHttpDeleter>;

// -------------------- OpenSSL helpers --------------------
struct OpenSSLGlobal {
    OpenSSLGlobal() {
        OPENSSL_init_ssl(OPENSSL_INIT_LOAD_SSL_STRINGS | OPENSSL_INIT_LOAD_CRYPTO_STRINGS, nullptr);
        ERR_load_crypto_strings();
    }
    ~OpenSSLGlobal() {
        ERR_free_strings();
    }
} openssl_global_init;

static std::vector<uint8_t> Sha3_256(const std::vector<uint8_t>& data) {
    std::vector<uint8_t> out(32);
#if OPENSSL_VERSION_NUMBER >= 0x10100000L
    EVP_MD_CTX* ctx = EVP_MD_CTX_new();
    if (!ctx) return {};
    if (EVP_DigestInit_ex(ctx, EVP_sha3_256(), nullptr) != 1) { EVP_MD_CTX_free(ctx); return {}; }
    if (EVP_DigestUpdate(ctx, data.data(), data.size()) != 1) { EVP_MD_CTX_free(ctx); return {}; }
    unsigned int len=0;
    if (EVP_DigestFinal_ex(ctx, out.data(), &len) != 1) { EVP_MD_CTX_free(ctx); return {}; }
    EVP_MD_CTX_free(ctx);
    out.resize(len);
    return out;
#else
    return {};
#endif
}

// -------------------- Base32 (RFC4648, lowercase) for onion --------------------
static int Base32Val(char c) {
    if (c >= 'a' && c <= 'z') return c - 'a';
    if (c >= 'A' && c <= 'Z') return c - 'A';
    if (c >= '2' && c <= '7') return 26 + (c - '2');
    return -1;
}
static std::vector<uint8_t> Base32Decode(const std::string& s_in) {
    std::string s; s.reserve(s_in.size());
    for (char c : s_in) if (c != '=') s.push_back(c);
    int bits = 0;
    uint32_t acc = 0;
    std::vector<uint8_t> out;
    for (char c : s) {
        int v = Base32Val(c);
        if (v < 0) return {};
        acc = (acc << 5) | (uint32_t)v;
        bits += 5;
        if (bits >= 8) {
            bits -= 8;
            out.push_back((acc >> bits) & 0xFF);
        }
    }
    return out;
}

// -------------------- Simple HTTP(S) via WinHTTP --------------------
struct HttpResponse {
    DWORD status = 0;
    std::map<std::string, std::string> headers;
    std::vector<uint8_t> body;
};

static std::optional<std::tuple<std::wstring,std::wstring,INTERNET_PORT,std::wstring>> ParseUrl(const std::wstring& url) {
    URL_COMPONENTS uc{};
    uc.dwStructSize = sizeof(uc);
    wchar_t scheme[16]{}, host[256]{}, path[2048]{};
    uc.lpszScheme = scheme; uc.dwSchemeLength = _countof(scheme);
    uc.lpszHostName = host; uc.dwHostNameLength = _countof(host);
    uc.lpszUrlPath = path; uc.dwUrlPathLength = _countof(path);
    if (!WinHttpCrackUrl(url.c_str(), (DWORD)url.size(), 0, &uc)) return std::nullopt;
    std::wstring wscheme(uc.lpszScheme, uc.dwSchemeLength);
    std::wstring whost(uc.lpszHostName, uc.dwHostNameLength);
    std::wstring wpath(uc.lpszUrlPath, uc.dwUrlPathLength);
    INTERNET_PORT port = uc.nPort ? uc.nPort : ((wscheme == L"https") ? 443 : 80);
    return std::make_tuple(wscheme, whost, port, wpath.empty() ? L"/" : wpath);
}

static HttpResponse HttpRequest(const std::wstring& method, const std::wstring& url, const std::string* body=nullptr, const std::map<std::wstring,std::wstring>& extra_headers = {}) {
    HttpResponse resp;
    auto parsed = ParseUrl(url);
    if (!parsed) { resp.status = 0; return resp; }
    auto [scheme, host, port, path] = *parsed;

    DWORD flags = 0;
    if (scheme == L"https") flags |= WINHTTP_FLAG_SECURE;

    WinHttpHandle hSession(WinHttpOpen(L"WinHTTP-TorClient/1.0", WINHTTP_ACCESS_TYPE_DEFAULT_PROXY, WINHTTP_NO_PROXY_NAME, WINHTTP_NO_PROXY_BYPASS, 0));
    if (!hSession) { return resp; }

    WinHttpHandle hConnect(WinHttpConnect(hSession.get(), host.c_str(), port, 0));
    if (!hConnect) { return resp; }

    WinHttpHandle hRequest(WinHttpOpenRequest(hConnect.get(), method.c_str(), path.c_str(), nullptr, WINHTTP_NO_REFERER, WINHTTP_DEFAULT_ACCEPT_TYPES, flags));
    if (!hRequest) { return resp; }

    DWORD secFlags = SECURITY_FLAG_IGNORE_CERT_CN_INVALID | SECURITY_FLAG_IGNORE_CERT_DATE_INVALID | SECURITY_FLAG_IGNORE_UNKNOWN_CA;
    WinHttpSetOption(hRequest.get(), WINHTTP_OPTION_SECURITY_FLAGS, &secFlags, sizeof(secFlags));

    std::wstringstream hdrs;
    for (auto& kv : extra_headers) {
        hdrs << kv.first << L": " << kv.second << L"\r\n";
    }
    if (body && extra_headers.find(L"Content-Type") == extra_headers.end())
        hdrs << L"Content-Type: application/x-www-form-urlencoded\r\n";

    const void* pBody = body ? body->data() : nullptr;
    DWORD cbBody = body ? (DWORD)body->size() : 0;

    if (!WinHttpSendRequest(hRequest.get(),
                            hdrs.str().empty() ? WINHTTP_NO_ADDITIONAL_HEADERS : hdrs.str().c_str(),
                            (DWORD)-1L,
                            const_cast<void*>(pBody),
                            cbBody,
                            cbBody,
                            0)) {
        return resp;
    }

    if (!WinHttpReceiveResponse(hRequest.get(), nullptr)) {
        return resp;
    }

    DWORD status=0, len=sizeof(status);
    WinHttpQueryHeaders(hRequest.get(), WINHTTP_QUERY_STATUS_CODE | WINHTTP_QUERY_FLAG_NUMBER, WINHTTP_HEADER_NAME_BY_INDEX, &status, &len, WINHTTP_NO_HEADER_INDEX);
    resp.status = status;

    // Headers
    DWORD dwSize = 0;
    WinHttpQueryHeaders(hRequest.get(), WINHTTP_QUERY_RAW_HEADERS_CRLF, WINHTTP_HEADER_NAME_BY_INDEX, WINHTTP_NO_OUTPUT_BUFFER, &dwSize, WINHTTP_NO_HEADER_INDEX);
    if (GetLastError() == ERROR_INSUFFICIENT_BUFFER) {
        std::wstring raw(dwSize/sizeof(wchar_t), L'\0');
        if (WinHttpQueryHeaders(hRequest.get(), WINHTTP_QUERY_RAW_HEADERS_CRLF, WINHTTP_HEADER_NAME_BY_INDEX, &raw[0], &dwSize, WINHTTP_NO_HEADER_INDEX)) {
            std::wistringstream iss(raw);
            std::wstring line;
            // first status line
            std::getline(iss, line);
            while (std::getline(iss, line)) {
                if (!line.empty() && (line.back()=='\r' || line.back()=='\n')) line.pop_back();
                if (line.empty()) continue;
                auto pos = line.find(L':');
                if (pos != std::wstring::npos) {
                    std::string k = WideToUtf8(line.substr(0, pos));
                    std::string v = WideToUtf8(line.substr(pos+1));
                    // trim leading space
                    while (!v.empty() && (v.front()==' ' || v.front()=='\t')) v.erase(v.begin());
                    resp.headers.emplace(k, v);
                }
            }
        }
    }

    // Body
    std::vector<uint8_t> buf;
    for (;;) {
        DWORD avail = 0;
        if (!WinHttpQueryDataAvailable(hRequest.get(), &avail)) break;
        if (avail == 0) break;
        size_t off = buf.size();
        buf.resize(off + avail);
        DWORD read = 0;
        if (!WinHttpReadData(hRequest.get(), buf.data() + off, avail, &read)) break;
        buf.resize(off + read);
        if (read == 0) break;
    }
    resp.body = std::move(buf);
    return resp;
}

static HttpResponse HttpGet(const std::wstring& url, const std::map<std::wstring,std::wstring>& headers = {}) {
    return HttpRequest(L"GET", url, nullptr, headers);
}
static HttpResponse HttpPost(const std::wstring& url, const std::string& body, const std::map<std::wstring,std::wstring>& headers = {}) {
    return HttpRequest(L"POST", url, &body, headers);
}

// -------------------- Minimal Tor consensus parsing --------------------
struct RelayInfo {
    std::string nickname;
    std::string identity; // hex fingerprint
    std::string address;
    uint16_t or_port = 0;
};

static std::vector<std::string> SplitLines(const std::string& s) {
    std::vector<std::string> lines;
    std::string cur;
    std::istringstream iss(s);
    while (std::getline(iss, cur)) {
        if (!cur.empty() && cur.back()=='\r') cur.pop_back();
        lines.push_back(cur);
    }
    return lines;
}

static std::vector<RelayInfo> ParseConsensus(const std::string& text) {
    auto lines = SplitLines(text);
    std::vector<RelayInfo> relays;
    RelayInfo cur;
    bool in_router = false;
    for (const auto& line : lines) {
        if (line.size() >= 2 && line[0] == 'r' && line[1] == ' ') {
            std::istringstream ss(line);
            std::string tag; ss >> tag;
            std::string nickname, ident_b64, sk_b64, published, ip; int orport=0, dirport=0;
            ss >> nickname >> ident_b64 >> sk_b64 >> published >> ip >> orport >> dirport;
            cur = {};
            cur.nickname = nickname;
            cur.address = ip;
            cur.or_port = (uint16_t)std::max(0, std::min(orport, 65535));
            in_router = true;
        } else if (in_router && line.size() >= 2 && line[0]=='s' && line[1]==' ') {
            // flags line, ignore
        } else if (in_router && line.size() >= 2 && line[0]=='w' && line[1]==' ') {
            // bandwidth line, ignore
        } else if (in_router && !line.empty() && line[0] == 'm' && line[1]==' ') {
            // digest line, ignore
        } else if (in_router && !line.empty() && line[0] == 'r' && line[1]=='a') {
            // rare alt lines
        } else if (in_router && !line.empty() && line[0] == 'r' && line[1]==' ') {
            // new router starts (handled above)
        } else if (!line.empty() && line[0] == 'r' && line[1] == 's') {
            // end of section marker in some formats
        } else if (line.size() >= 2 && line[0]=='directory-footer' ) {
            // stop
            break;
        } else if (!line.empty() && line[0] == 'r') {
            // ignore
        } else if (!in_router) {
            // header lines; we could parse "dir-source", "valid-after", etc.
        } else if (line.empty()) {
            // end of router block
            if (in_router) {
                relays.push_back(cur);
                in_router = false;
            }
        }
    }
    if (in_router) relays.push_back(cur);
    return relays;
}

// -------------------- v3 onion address decode/validate --------------------
// v3 address: base32(lowercase) of 35 bytes: [32-byte ed25519 pubkey][2-byte checksum][1-byte version=3]
static bool DecodeOnionV3(const std::string& onion, std::vector<uint8_t>& pubkey32) {
    std::string n = onion;
    // strip suffix
    if (n.size() > 6 && n.substr(n.size()-6) == ".onion") n = n.substr(0, n.size()-6);
    std::string low; low.reserve(n.size());
    for (char c : n) if (!isspace((unsigned char)c)) low.push_back((char)tolower((unsigned char)c));
    if (low.size() != 56) return false;
    auto decoded = Base32Decode(low);
    if (decoded.size() != 35) return false;
    uint8_t ver = decoded[34];
    if (ver != 3) return false;
    pubkey32.assign(decoded.begin(), decoded.begin()+32);
    // verify checksum = first 2 bytes of SHA3-256(".onion checksum" || pubkey || version)
    std::vector<uint8_t> chkdata;
    const char prefix[] = ".onion checksum";
    chkdata.insert(chkdata.end(), (const uint8_t*)prefix, (const uint8_t*)prefix + sizeof(prefix)-1);
    chkdata.insert(chkdata.end(), pubkey32.begin(), pubkey32.end());
    chkdata.push_back(ver);
    auto digest = Sha3_256(chkdata);
    if (digest.size() < 2) return false;
    if (digest[0] != decoded[32] || digest[1] != decoded[33]) return false;
    return true;
}

// -------------------- Hidden service descriptor parsing (minimal) --------------------
// This is a minimal, non-validating parser that extracts top-level fields for demonstration.
struct HSDescriptor {
    std::string version;
    std::string hs_type;
    std::string blinded_pubkey;
    std::string created;
    std::string revision_counter;
    std::vector<std::string> intro_points_base64; // raw base64 blocks if present
};

static HSDescriptor ParseHSDescriptor(const std::string& text) {
    HSDescriptor d;
    auto lines = SplitLines(text);
    std::string curBlockName;
    std::string curBlock;
    auto flushBlock = [&]() {
        if (curBlockName == "introduction-point") {
            d.intro_points_base64.push_back(curBlock);
        }
        curBlockName.clear();
        curBlock.clear();
    };
    for (size_t i=0;i<lines.size();++i) {
        const auto& line = lines[i];
        if (line.rfind("hs-descriptor ", 0) == 0) {
            d.version = line.substr(std::string("hs-descriptor ").size());
        } else if (line.rfind("descriptor-lifetime ", 0) == 0) {
        } else if (line.rfind("descriptor-signing-key-cert", 0) == 0) {
            // next lines until "-----END" will be a cert block; skip
        } else if (line.rfind("revision-counter ", 0) == 0) {
            d.revision_counter = line.substr(18);
        } else if (line.rfind("created ", 0) == 0) {
            d.created = line.substr(8);
        } else if (line.rfind("blinded-pubkey ", 0) == 0) {
            d.blinded_pubkey = line.substr(15);
        } else if (line.rfind("hs-type ", 0) == 0) {
            d.hs_type = line.substr(8);
        } else if (line == "-----BEGIN MESSAGE-----") {
            // could be inner signed message; skip for brevity
        } else if (line.rfind("introduction-point ", 0) == 0) {
            if (!curBlockName.empty()) flushBlock();
            curBlockName = "introduction-point";
        } else if (line == "-----BEGIN INTRODUCTION POINT-----") {
            if (!curBlockName.empty()) flushBlock();
            curBlockName = "introduction-point";
        } else if (line == "-----END INTRODUCTION POINT-----") {
            flushBlock();
        } else if (!curBlockName.empty()) {
            if (!line.empty() && line[0] != '#') {
                if (!curBlock.empty()) curBlock.push_back('\n');
                curBlock.append(line);
            }
        }
    }
    if (!curBlockName.empty()) flushBlock();
    return d;
}

// -------------------- Driver / CLI --------------------
static void PrintHex(const std::vector<uint8_t>& v) {
    std::ios::fmtflags f(std::cout.flags());
    for (auto b : v) std::cout << std::hex << std::setw(2) << std::setfill('0') << (int)b;
    std::cout.flags(f);
}

static void PrintUsage() {
    std::cout << "Options:\n"
              << "  --consensus-url <url>          Download and parse Tor consensus\n"
              << "  --descriptor-url <url>         Download and parse Tor v3 descriptor\n"
              << "  --onion <address>              Validate v3 .onion address\n"
              << "  --get <path>                   Perform HTTPS GET to https://<host><path>\n"
              << "  --post <path> <data>           Perform HTTPS POST to https://<host><path>\n"
              << "Examples:\n"
              << "  tor_client.exe --consensus-url https://collector.torproject.org/.../consensus\n"
              << "  tor_client.exe --descriptor-url https://example.com/hsdesc.txt\n";
}

int wmain(int argc, wchar_t* argv[]) {
    std::wstring consensusUrl, descriptorUrl;
    std::string onionAddr;
    std::wstring reqHost; // used when composing GET/POST absolute URLs if user supplies full
    std::optional<std::wstring> getPath;
    std::optional<std::pair<std::wstring,std::string>> postData;

    for (int i=1;i<argc;i++) {
        std::wstring a = argv[i];
        if (a == L"--consensus-url" && i+1<argc) {
            consensusUrl = argv[++i];
        } else if (a == L"--descriptor-url" && i+1<argc) {
            descriptorUrl = argv[++i];
        } else if (a == L"--onion" && i+1<argc) {
            onionAddr = WideToUtf8(argv[++i]);
        } else if (a == L"--get" && i+1<argc) {
            getPath = argv[++i];
        } else if (a == L"--post" && i+2<argc) {
            std::wstring p = argv[++i];
            std::string data = WideToUtf8(argv[++i]);
            postData = std::make_pair(p, data);
        } else if ((a == L"-h") || (a == L"--help")) {
            PrintUsage();
            return 0;
        }
    }

    if (!consensusUrl.empty()) {
        std::wcout << L"[+] Downloading consensus: " << consensusUrl << L"\n";
        auto r = HttpGet(consensusUrl);
        if (r.status != 200) {
            std::cout << "[-] HTTP error: " << r.status << "\n";
        } else {
            std::string body(r.body.begin(), r.body.end());
            auto relays = ParseConsensus(body);
            std::cout << "[+] Parsed relays: " << relays.size() << "\n";
            for (size_t i=0;i<relays.size() && i<5;i++) {
                std::cout << "  - " << relays[i].nickname << " " << relays[i].address << ":" << relays[i].or_port << "\n";
            }
        }
    }

    if (!descriptorUrl.empty()) {
        std::wcout << L"[+] Downloading descriptor: " << descriptorUrl << L"\n";
        auto r = HttpGet(descriptorUrl);
        if (r.status != 200) {
            std::cout << "[-] HTTP error: " << r.status << "\n";
        } else {
            std::string body(r.body.begin(), r.body.end());
            auto d = ParseHSDescriptor(body);
            std::cout << "[+] Descriptor fields:\n";
            std::cout << "  version: " << d.version << "\n";
            std::cout << "  hs-type: " << d.hs_type << "\n";
            std::cout << "  created: " << d.created << "\n";
            std::cout << "  blinded-pubkey: " << d.blinded_pubkey << "\n";
            std::cout << "  revision-counter: " << d.revision_counter << "\n";
            std::cout << "  intro-points: " << d.intro_points_base64.size() << "\n";
        }
    }

    if (!onionAddr.empty()) {
        std::vector<uint8_t> pk;
        bool ok = DecodeOnionV3(onionAddr, pk);
        std::cout << "[+] Onion address: " << (ok ? "valid v3" : "invalid") << "\n";
        if (ok) {
            std::cout << "  ed25519 pubkey: ";
            PrintHex(pk);
            std::cout << "\n";
        }
    }

    // Demonstration of GET/POST using WinHTTP. For a real .onion, Tor circuits are required.
    // Here we accept an absolute URL as --get/--post path for flexibility.
    if (getPath) {
        std::wstring url = *getPath;
        if (url.rfind(L"http://",0)!=0 && url.rfind(L"https://",0)!=0) {
            std::wcout << L"[-] Please provide an absolute URL for --get (http/https)\n";
        } else {
            auto r = HttpGet(url);
            std::cout << "[GET] status: " << r.status << " bytes: " << r.body.size() << "\n";
        }
    }
    if (postData) {
        std::wstring url = postData->first;
        if (url.rfind(L"http://",0)!=0 && url.rfind(L"https://",0)!=0) {
            std::wcout << L"[-] Please provide an absolute URL for --post (http/https)\n";
        } else {
            auto r = HttpPost(url, postData->second);
            std::cout << "[POST] status: " << r.status << " bytes: " << r.body.size() << "\n";
        }
    }

    return 0;
}

