// UTF-8/UTF-16 helpers
static std::wstring Utf8ToWide(const std::string& s) {
    if (s.empty()) return L"";
    int len = MultiByteToWideChar(CP_UTF8, 0, s.c_str(), (int)s.size(), nullptr, 0);
    std::wstring out(len, 0);
    MultiByteToWideChar(CP_UTF8, 0, s.c_str(), (int)s.size(), &out[0], len);
    return out;
}
static std::string WideToUtf8(const std::wstring& ws) {
    if (ws.empty()) return "";
    int len = WideCharToMultiByte(CP_UTF8, 0, ws.c_str(), (int)ws.size(), nullptr, 0, nullptr, nullptr);
    std::string out(len, 0);
    WideCharToMultiByte(CP_UTF8, 0, ws.c_str(), (int)ws.size(), &out[0], len, nullptr, nullptr);
    return out;
}

// Error formatters
static std::wstring FormatWinHttpError(DWORD err) {
    LPWSTR buf = nullptr;
    DWORD len = FormatMessageW(FORMAT_MESSAGE_FROM_HMODULE | FORMAT_MESSAGE_ALLOCATE_BUFFER | FORMAT_MESSAGE_IGNORE_INSERTS,
                               GetModuleHandleW(L"winhttp.dll"), err, 0, (LPWSTR)&buf, 0, nullptr);
    std::wstring s = (len && buf) ? std::wstring(buf, len) : L"(unknown WinHTTP error)";
    if (buf) LocalFree(buf);
    return s;
}
static std::wstring FormatLastError() {
    DWORD err = GetLastError();
    LPWSTR buf = nullptr;
    DWORD len = FormatMessageW(FORMAT_MESSAGE_FROM_SYSTEM | FORMAT_MESSAGE_ALLOCATE_BUFFER | FORMAT_MESSAGE_IGNORE_INSERTS,
                               nullptr, err, 0, (LPWSTR)&buf, 0, nullptr);
    std::wstring s = (len && buf) ? std::wstring(buf, len) : L"(unknown error)";
    if (buf) LocalFree(buf);
    return s;
}

// WinHTTP RAII handle
struct WinHttpHandle {
    HINTERNET h{nullptr};
    WinHttpHandle() = default;
    explicit WinHttpHandle(HINTERNET handle) : h(handle) {}
    ~WinHttpHandle() { if (h) WinHttpCloseHandle(h); }
    WinHttpHandle(const WinHttpHandle&) = delete;
    WinHttpHandle& operator=(const WinHttpHandle&) = delete;
    WinHttpHandle(WinHttpHandle&& o) noexcept : h(o.h) { o.h = nullptr; }
    WinHttpHandle& operator=(WinHttpHandle&& o) noexcept {
        if (this != &o) {
            if (h) WinHttpCloseHandle(h);
            h = o.h; o.h = nullptr;
        }
        return *this;
    }
    operator HINTERNET() const { return h; }
};

// URL parser
struct ParsedUrl {
    std::wstring host;
    std::wstring path;
    INTERNET_PORT port{0};
    bool https{false};
};
static bool CrackUrl(const std::wstring& url, ParsedUrl& out) {
    URL_COMPONENTS uc{};
    wchar_t host[512]{};
    wchar_t path[4096]{};
    uc.dwStructSize = sizeof(uc);
    uc.lpszHostName = host; uc.dwHostNameLength = ARRAYSIZE(host);
    uc.lpszUrlPath = path; uc.dwUrlPathLength = ARRAYSIZE(path);
    uc.dwSchemeLength = (DWORD)-1;

    if (!WinHttpCrackUrl(url.c_str(), 0, 0, &uc)) {
        std::wcerr << L"WinHttpCrackUrl failed: " << FormatLastError() << L"\n";
        return false;
    }
    out.host.assign(uc.lpszHostName, uc.dwHostNameLength);
    out.path.clear();
    if (uc.lpszUrlPath && uc.dwUrlPathLength) out.path.append(uc.lpszUrlPath, uc.dwUrlPathLength);
    if (uc.lpszExtraInfo && uc.dwExtraInfoLength) out.path.append(uc.lpszExtraInfo, uc.dwExtraInfoLength);
    out.port = uc.nPort;
    out.https = (uc.nScheme == INTERNET_SCHEME_HTTPS);
    if (out.path.empty()) out.path = L"/";
    return true;
}

// WinHTTP request helpers
static bool WinHttpSimpleRequest(const std::wstring& method, const std::wstring& url, const std::wstring& headers,
                                 const std::string* body, DWORD& status, std::wstring& statusText, std::string& outBody) {
    ParsedUrl u{};
    if (!CrackUrl(url, u)) return false;

    WinHttpHandle hSession(WinHttpOpen(L"tor-onion-tool/1.0",
                                       WINHTTP_ACCESS_TYPE_DEFAULT_PROXY,
                                       WINHTTP_NO_PROXY_NAME,
                                       WINHTTP_NO_PROXY_BYPASS, 0));
    if (!hSession) {
        std::wcerr << L"WinHttpOpen failed: " << FormatLastError() << L"\n";
        return false;
    }

    WinHttpHandle hConnect(WinHttpConnect(hSession, u.host.c_str(), u.port ? u.port : (u.https ? INTERNET_DEFAULT_HTTPS_PORT : INTERNET_DEFAULT_HTTP_PORT), 0));
    if (!hConnect) {
        std::wcerr << L"WinHttpConnect failed: " << FormatLastError() << L"\n";
        return false;
    }

    WinHttpHandle hRequest(WinHttpOpenRequest(hConnect, method.c_str(), u.path.c_str(),
                                              nullptr, WINHTTP_NO_REFERER,
                                              WINHTTP_DEFAULT_ACCEPT_TYPES,
                                              u.https ? WINHTTP_FLAG_SECURE : 0));
    if (!hRequest) {
        std::wcerr << L"WinHttpOpenRequest failed: " << FormatLastError() << L"\n";
        return false;
    }

    // Enforce TLS 1.2+ and certificate validation for HTTPS
    if (u.https) {
        DWORD flags = SECURITY_FLAG_IGNORE_UNKNOWN_CA; // 0 to enforce strict; leave 0 for prod
        // If needed: WinHttpSetOption(hRequest, WINHTTP_OPTION_SECURITY_FLAGS, &flags, sizeof(flags));
        DWORD protocols = WINHTTP_FLAG_SECURE_PROTOCOL_TLS1_2 | WINHTTP_FLAG_SECURE_PROTOCOL_TLS1_3;
        WinHttpSetOption(hRequest, WINHTTP_OPTION_SECURE_PROTOCOLS, &protocols, sizeof(protocols));
    }

    BOOL ok = WinHttpSendRequest(hRequest,
                                 headers.empty() ? WINHTTP_NO_ADDITIONAL_HEADERS : headers.c_str(),
                                 headers.empty() ? 0 : (DWORD)-1,
                                 (LPVOID)(body ? body->data() : nullptr),
                                 body ? (DWORD)body->size() : 0,
                                 body ? (DWORD)body->size() : 0,
                                 0);
    if (!ok) {
        std::wcerr << L"WinHttpSendRequest failed: " << FormatLastError() << L"\n";
        return false;
    }

    if (!WinHttpReceiveResponse(hRequest, nullptr)) {
        std::wcerr << L"WinHttpReceiveResponse failed: " << FormatLastError() << L"\n";
        return false;
    }

    // Status code and text
    DWORD dwStatus = 0, dwSize = sizeof(dwStatus);
    if (!WinHttpQueryHeaders(hRequest, WINHTTP_QUERY_STATUS_CODE | WINHTTP_QUERY_FLAG_NUMBER, WINHTTP_HEADER_NAME_BY_INDEX,
                             &dwStatus, &dwSize, WINHTTP_NO_HEADER_INDEX)) {
        std::wcerr << L"WinHttpQueryHeaders(status) failed: " << FormatLastError() << L"\n";
        return false;
    }
    status = dwStatus;

    wchar_t szStatusText[256]{};
    dwSize = sizeof(szStatusText);
    if (WinHttpQueryHeaders(hRequest, WINHTTP_QUERY_STATUS_TEXT, WINHTTP_HEADER_NAME_BY_INDEX, szStatusText, &dwSize, WINHTTP_NO_HEADER_INDEX)) {
        statusText.assign(szStatusText);
    } else {
        statusText.assign(L"");
    }

    // Read body
    outBody.clear();
    for (;;) {
        DWORD avail = 0;
        if (!WinHttpQueryDataAvailable(hRequest, &avail)) {
            std::wcerr << L"WinHttpQueryDataAvailable failed: " << FormatLastError() << L"\n";
            return false;
        }
        if (avail == 0) break;
        std::string chunk(avail, '\0');
        DWORD read = 0;
        if (!WinHttpReadData(hRequest, &chunk[0], avail, &read)) {
            std::wcerr << L"WinHttpReadData failed: " << FormatLastError() << L"\n";
            return false;
        }
        chunk.resize(read);
        outBody.append(chunk);
    }

    return true;
}

static bool HttpGet(const std::wstring& url, std::string& bodyOut, DWORD& statusOut) {
    std::wstring statusText;
    std::wstring hdrs; // default
    return WinHttpSimpleRequest(L"GET", url, hdrs, nullptr, statusOut, statusText, bodyOut);
}

static bool HttpPostForm(const std::wstring& url, const std::string& formBody, std::string& bodyOut, DWORD& statusOut) {
    std::wstring statusText;
    std::wstring hdrs = L"Content-Type: application/x-www-form-urlencoded\r\n";
    return WinHttpSimpleRequest(L"POST", url, hdrs, &formBody, statusOut, statusText, bodyOut);
}

// OpenSSL helpers
struct OpenSSLInit {
    OpenSSLInit() { OPENSSL_init_ssl(0, nullptr); OpenSSL_add_all_algorithms(); ERR_load_crypto_strings(); }
    ~OpenSSLInit() { EVP_cleanup(); ERR_free_strings(); }
} g_openssl_init;

static bool Sha3_256(const std::vector<unsigned char>& in, std::array<unsigned char, 32>& out) {
    EVP_MD_CTX* ctx = EVP_MD_CTX_new();
    if (!ctx) return false;
    bool ok = EVP_DigestInit_ex(ctx, EVP_sha3_256(), nullptr) == 1 &&
              EVP_DigestUpdate(ctx, in.data(), in.size()) == 1 &&
              EVP_DigestFinal_ex(ctx, out.data(), nullptr) == 1;
    EVP_MD_CTX_free(ctx);
    return ok;
}

// Base32 (RFC 4648 without padding) for .onion v3
static int B32Val(int c) {
    if (c >= 'A' && c <= 'Z') return c - 'A';
    if (c >= 'a' && c <= 'z') return c - 'a';
    if (c >= '2' && c <= '7') return 26 + (c - '2');
    return -1;
}
static bool Base32NoPadDecode(const std::string& in, std::vector<unsigned char>& out) {
    out.clear();
    int buffer = 0, bitsLeft = 0;
    for (char ch : in) {
        if (ch == '=') break;
        int v = B32Val((unsigned char)ch);
        if (v < 0) return false;
        buffer = (buffer << 5) | v;
        bitsLeft += 5;
        if (bitsLeft >= 8) {
            bitsLeft -= 8;
            out.push_back((unsigned char)((buffer >> bitsLeft) & 0xFF));
        }
    }
    return true;
}

// Onion v3 address validator/decoder: returns pubkey (32), checksum(2), version(1)
struct OnionV3Parts {
    std::array<unsigned char, 32> pubkey{};
    std::array<unsigned char, 2> checksum{};
    unsigned char version{3};
};

static bool DecodeOnionV3(const std::string& onionHost, OnionV3Parts& parts) {
    std::string host = onionHost;
    // strip scheme and path if provided
    auto pos = host.find("://");
    if (pos != std::string::npos) host = host.substr(pos + 3);
    pos = host.find('/');
    if (pos != std::string::npos) host = host.substr(0, pos);
    if (host.size() >= 6 && host.substr(host.size()-6) == ".onion")
        host = host.substr(0, host.size()-6);

    if (host.size() != 56) return false;
    for (char c : host) {
        if (!(std::isalnum((unsigned char)c))) return false;
    }
    std::vector<unsigned char> dec;
    if (!Base32NoPadDecode(host, dec)) return false;
    if (dec.size() != 35) return false;
    std::copy(dec.begin(), dec.begin()+32, parts.pubkey.begin());
    parts.checksum[0] = dec[32];
    parts.checksum[1] = dec[33];
    parts.version = dec[34];
    if (parts.version != 3) return false;

    // Verify checksum = H(".onion checksum" | pubkey | version)[:2]
    std::vector<unsigned char> msg;
    const char prefix[] = ".onion checksum";
    msg.insert(msg.end(), prefix, prefix + sizeof(prefix) - 1);
    msg.insert(msg.end(), parts.pubkey.begin(), parts.pubkey.end());
    msg.push_back(parts.version);
    std::array<unsigned char, 32> hash{};
    if (!Sha3_256(msg, hash)) return false;
    if (hash[0] != parts.checksum[0] || hash[1] != parts.checksum[1]) return false;
    return true;
}

// Tor consensus parsing (very small subset)
struct RelayInfo {
    std::string nickname;
    std::string identity; // base64-ed25519 or sha1 depending on line; kept raw here
    std::string address;
    int orPort{0};
    bool isGuard{false};
    bool isExit{false};
    bool isHSDir{false};
};

static std::vector<RelayInfo> ParseConsensus(const std::string& consensus) {
    std::vector<RelayInfo> relays;
    std::istringstream iss(consensus);
    std::string line;
    RelayInfo cur{};
    bool inRouter = false;
    while (std::getline(iss, line)) {
        if (!line.empty() && line.back() == '\r') line.pop_back();
        if (line.size() >= 2 && line[0] == 'r' && line[1] == ' ') {
            // router line: r Nickname Identity Digest IP ORPort DirPort
            std::istringstream ls(line);
            std::string tag; ls >> tag;
            RelayInfo r{};
            ls >> r.nickname;
            std::string id, digest;
            ls >> id >> digest;
            r.identity = id;
            ls >> r.address >> r.orPort;
            cur = r;
            inRouter = true;
        } else if (inRouter && line.size() >= 2 && line[0] == 's' && line[1] == ' ') {
            // flags line
            cur.isGuard = (line.find(" Guard") != std::string::npos || line.find("Guard") == 2);
            cur.isExit = (line.find(" Exit") != std::string::npos || line.find("Exit") == 2);
            cur.isHSDir = (line.find(" HSDir") != std::string::npos || line.find("HSDir") == 2);
            // finalize this relay entry
            relays.push_back(cur);
            inRouter = false;
        }
    }
    return relays;
}

// Tor v3 descriptor parsing (simplified, extracts header key/values and BEGIN/END sections)
struct HSDescriptor {
    std::map<std::string, std::string> headers;
    std::map<std::string, std::string> pemBlocks; // name -> base64 body
};

static HSDescriptor ParseHSDescriptor(const std::string& text) {
    HSDescriptor d;
    std::istringstream iss(text);
    std::string line;
    std::string currentBegin;
    std::ostringstream curPem;

    auto finishPem = [&]() {
        if (!currentBegin.empty()) {
            d.pemBlocks[currentBegin] = curPem.str();
            currentBegin.clear();
            curPem.str("");
            curPem.clear();
        }
    };

    while (std::getline(iss, line)) {
        if (!line.empty() && line.back() == '\r') line.pop_back();
        if (line.rfind("-----BEGIN ", 0) == 0) {
            finishPem();
            size_t p = line.find("-----", 11);
            std::string name = (p != std::string::npos) ? line.substr(11, p - 11) : "UNKNOWN";
            currentBegin = name;
        } else if (line.rfind("-----END ", 0) == 0) {
            finishPem();
        } else if (!currentBegin.empty()) {
            if (!line.empty())
                curPem << line << "\n";
        } else {
            // header lines e.g. hs-descriptor 3, descriptor-lifetime 180
            auto sp = line.find(' ');
            if (sp != std::string::npos) {
                std::string k = line.substr(0, sp);
                std::string v = line.substr(sp + 1);
                d.headers[k] = v;
            }
        }
    }
    finishPem();
    return d;
}

// Simple GET/POST to onion via tor2web-like gateway
// - subdomain mode: https://<onion>.<gateway>/<path>
// - path mode:      https://<gateway>/<onion>/<path>
static std::wstring BuildGatewayUrl(const std::string& onionUrl, const std::wstring& gatewayHost, const std::wstring& mode) {
    // Parse onionUrl: scheme://host[:port]/path
    std::string url = onionUrl;
    std::string scheme = "http";
    if (url.rfind("http://", 0) == 0) { scheme = "http"; url = url.substr(7); }
    else if (url.rfind("https://", 0) == 0) { scheme = "https"; url = url.substr(8); }
    std::string host = url;
    std::string path = "/";
    auto slash = url.find('/');
    if (slash != std::string::npos) {
        host = url.substr(0, slash);
        path = url.substr(slash);
    }
    if (host.size() >= 6 && host.substr(host.size()-6) == ".onion") {
        host = host.substr(0, host.size()-6);
    }
    std::wstring gw = gatewayHost;
    std::wstring full;
    if (mode == L"subdomain") {
        // https://<onion>.<gateway>/<path>
        full = L"https://" + Utf8ToWide(host) + L"." + gw + Utf8ToWide(path);
    } else {
        // path
        // https://<gateway>/<onion>/<path>
        std::wstring p = L"/" + Utf8ToWide(host) + L".onion";
        if (!path.empty() && path[0] != '/') p += L"/";
        p += Utf8ToWide(path);
        full = L"https://" + gw + p;
    }
    return full;
}

static void PrintHex(const unsigned char* p, size_t n) {
    for (size_t i = 0; i < n; ++i) {
        std::cout << std::hex << std::setfill('0') << std::setw(2) << (int)p[i];
        if ((i + 1) % 16 == 0) std::cout << "\n";
        else std::cout << " ";
    }
    std::cout << std::dec << "\n";
}

// CLI
static void PrintUsage() {
    std::wcout << L"Usage:\n"
                  L"  --consensus-url <https_url>\n"
                  L"  --descriptor-url <https_url>\n"
                  L"  --onion-check <v3.onion>\n"
                  L"  --get <https_url>\n"
                  L"  --post <https_url> <form_body>\n"
                  L"  --get-onion <http(s)://v3.onion[/path]> --gateway <host> --gateway-mode <subdomain|path>\n"
                  L"  --post-onion <http(s)://v3.onion[/path]> <form_body> --gateway <host> --gateway-mode <subdomain|path>\n";
}

int wmain(int argc, wchar_t* argv[]) {
    if (argc < 2) {
        PrintUsage();
        return 1;
    }

    std::map<std::wstring, std::wstring> opt;
    std::vector<std::wstring> args(argv + 1, argv + argc);

    // Simple parser: flags with optional next-value
    for (size_t i = 0; i < args.size(); ++i) {
        std::wstring k = args[i];
        if (k.rfind(L"--", 0) == 0) {
            std::wstring v;
            if (i + 1 < args.size() && args[i + 1].rfind(L"--", 0) != 0) {
                v = args[++i];
            }
            opt[k] = v;
        }
    }

    // --get
    if (opt.count(L"--get")) {
        std::string body;
        DWORD status = 0;
        std::wstring url = opt[L"--get"];
        if (!HttpGet(url, body, status)) return 2;
        std::wcout << L"GET status: " << status << L"\n";
        std::cout << body << "\n";
        return 0;
    }

    // --post
    if (opt.count(L"--post")) {
        std::string body;
        DWORD status = 0;
        std::wstring url = opt[L"--post"];
        std::wstring wform = opt.count(L"--post") ? opt[L"--post"] : L"";
        // Our simple parser collides; use positional for form: last arg
        std::wstring formW;
        if (!args.empty()) formW = args.back();
        std::string form = WideToUtf8(formW);
        if (!HttpPostForm(url, form, body, status)) return 2;
        std::wcout << L"POST status: " << status << L"\n";
        std::cout << body << "\n";
        return 0;
    }

    // --consensus-url
    if (opt.count(L"--consensus-url")) {
        std::string body;
        DWORD status = 0;
        if (!HttpGet(opt[L"--consensus-url"], body, status)) return 2;
        std::wcout << L"Consensus HTTP status: " << status << L"\n";
        auto relays = ParseConsensus(body);
        std::wcout << L"Parsed relays: " << relays.size() << L"\n";
        size_t shown = 0;
        for (const auto& r : relays) {
            std::wcout << L"- " << Utf8ToWide(r.nickname) << L" " << Utf8ToWide(r.address) << L":" << r.orPort
                       << L" [G:" << (r.isGuard?L"Y":L"N") << L" E:" << (r.isExit?L"Y":L"N")
                       << L" HSDir:" << (r.isHSDir?L"Y":L"N") << L"]\n";
            if (++shown >= 20) break;
        }
        return 0;
    }

    // --descriptor-url
    if (opt.count(L"--descriptor-url")) {
        std::string body;
        DWORD status = 0;
        if (!HttpGet(opt[L"--descriptor-url"], body, status)) return 2;
        std::wcout << L"Descriptor HTTP status: " << status << L"\n";
        auto desc = ParseHSDescriptor(body);
        std::wcout << L"Descriptor headers:\n";
        for (auto& kv : desc.headers) {
            std::wcout << L"  " << Utf8ToWide(kv.first) << L": " << Utf8ToWide(kv.second) << L"\n";
        }
        std::wcout << L"PEM blocks:\n";
        for (auto& kv : desc.pemBlocks) {
            std::wcout << L"  " << Utf8ToWide(kv.first) << L" (" << kv.second.size() << L" bytes base64)\n";
        }
        return 0;
    }

    // --onion-check
    if (opt.count(L"--onion-check")) {
        std::string onion = WideToUtf8(opt[L"--onion-check"]);
        OnionV3Parts p{};
        if (!DecodeOnionV3(onion, p)) {
            std::wcout << L"Invalid v3 onion: " << opt[L"--onion-check"] << L"\n";
            return 3;
        }
        std::wcout << L"Valid v3 onion: " << opt[L"--onion-check"] << L"\n";
        std::wcout << L"Public key (ed25519) 32 bytes:\n";
        PrintHex(p.pubkey.data(), p.pubkey.size());
        std::wcout << L"Checksum: ";
        PrintHex(p.checksum.data(), 2);
        return 0;
    }

    // --get-onion via gateway
    if (opt.count(L"--get-onion") && opt.count(L"--gateway") && opt.count(L"--gateway-mode")) {
        std::string onionUrl = WideToUtf8(opt[L"--get-onion"]);
        std::wstring gw = opt[L"--gateway"];
        std::wstring mode = opt[L"--gateway-mode"];
        std::wstring tgt = BuildGatewayUrl(onionUrl, gw, mode);
        std::wcout << L"Gateway URL: " << tgt << L"\n";
        std::string body;
        DWORD status = 0;
        if (!HttpGet(tgt, body, status)) return 2;
        std::wcout << L"GET status: " << status << L"\n";
        std::cout << body << "\n";
        return 0;
    }

    // --post-onion via gateway
    if (opt.count(L"--post-onion") && opt.count(L"--gateway") && opt.count(L"--gateway-mode")) {
        std::string onionUrl = WideToUtf8(opt[L"--post-onion"]);
        std::wstring gw = opt[L"--gateway"];
        std::wstring mode = opt[L"--gateway-mode"];
        std::wstring formW;
        if (!args.empty()) formW = args.back();
        std::string form = WideToUtf8(formW);
        std::wstring tgt = BuildGatewayUrl(onionUrl, gw, mode);
        std::wcout << L"Gateway URL: " << tgt << L"\n";
        std::string body;
        DWORD status = 0;
        if (!HttpPostForm(tgt, form, body, status)) return 2;
        std::wcout << L"POST status: " << status << L"\n";
        std::cout << body << "\n";
        return 0;
    }

    PrintUsage();
    return 0;
}

Below is an incremental improvement of the earlier toy translator (SQL AST -> Relational Algebra AST) with focused error handling and practical notes about pitfalls. It includes:

- A stricter translation pipeline that validates tables, aliases, and columns.
- A basic name-resolution pass that qualifies unqualified columns and catches ambiguity.
- Clear exceptions for common problems (unknown/ambiguous columns, duplicate aliases, missing FROM, etc.).
- Examples of input SQL queries (as strings for readability) and their corresponding RA trees or raised errors.

Note: We still assume you start from an existing SQL AST, not raw SQL text. Small catalogs are optional but enable much better error messages.

```python
from __future__ import annotations
from dataclasses import dataclass
from typing import Dict, List, Optional, Set, Tuple, Union, Iterable

# ---------- Exceptions: explicit, precise messages ----------

class TranslationError(Exception):
    pass

class EmptyFromError(TranslationError):
    pass

class EmptySelectListError(TranslationError):
    pass

class DuplicateAliasError(TranslationError):
    pass

class UnknownTableError(TranslationError):
    pass

class UnknownColumnError(TranslationError):
    pass

class AmbiguousColumnError(TranslationError):
    pass

class UnsupportedFeatureError(TranslationError):
    pass


# ---------- SQL AST (minimal) ----------

class SQLExpr:
    pass

@dataclass
class Column(SQLExpr):
    name: str
    table: Optional[str] = None  # qualified as table.column if given

@dataclass
class Literal(SQLExpr):
    value: object

@dataclass
class Comparison(SQLExpr):
    op: str  # e.g., '=', '<', '>', '<=', '>=', '!='
    left: SQLExpr
    right: SQLExpr

@dataclass
class BooleanOp(SQLExpr):
    op: str  # 'AND' or 'OR'
    left: SQLExpr
    right: SQLExpr

@dataclass
class Not(SQLExpr):
    expr: SQLExpr

@dataclass
class SelectItem:
    expr: SQLExpr
    alias: Optional[str] = None

@dataclass
class AllColumns(SQLExpr):
    # Represents SELECT *
    pass

@dataclass
class TableRef:
    name: str
    alias: Optional[str] = None

@dataclass
class SelectStmt:
    select_list: List[SelectItem]  # or items including AllColumns()
    from_tables: List[TableRef]
    where: Optional[SQLExpr] = None


# ---------- Relational Algebra AST (minimal) ----------

class RAExpr:
    pass

@dataclass
class RATable(RAExpr):
    name: str
    alias: Optional[str] = None

@dataclass
class RAProduct(RAExpr):
    left: RAExpr
    right: RAExpr

@dataclass
class RASelection(RAExpr):
    predicate: SQLExpr
    child: RAExpr

@dataclass
class RAProjection(RAExpr):
    items: List[SelectItem]  # project expressions (and aliases) from SQL AST
    child: RAExpr


# ---------- Pretty printing helpers ----------

def expr_to_str(e: SQLExpr) -> str:
    if isinstance(e, Column):
        return f"{e.table}.{e.name}" if e.table else e.name
    if isinstance(e, Literal):
        return repr(e.value)
    if isinstance(e, Comparison):
        return f"({expr_to_str(e.left)} {e.op} {expr_to_str(e.right)})"
    if isinstance(e, BooleanOp):
        return f"({expr_to_str(e.left)} {e.op} {expr_to_str(e.right)})"
    if isinstance(e, Not):
        return f"(NOT {expr_to_str(e.expr)})"
    if isinstance(e, AllColumns):
        return "*"
    return f"<expr:{e.__class__.__name__}>"

def ra_to_str(ra: RAExpr, indent: int = 0) -> str:
    pad = "  " * indent
    if isinstance(ra, RATable):
        alias = f" AS {ra.alias}" if ra.alias else ""
        return f"{pad}Table({ra.name}{alias})"
    if isinstance(ra, RAProduct):
        return f"{pad}Product\n{ra_to_str(ra.left, indent+1)}\n{ra_to_str(ra.right, indent+1)}"
    if isinstance(ra, RASelection):
        return f"{pad}Select[{expr_to_str(ra.predicate)}]\n{ra_to_str(ra.child, indent+1)}"
    if isinstance(ra, RAProjection):
        items = ", ".join(
            f"{expr_to_str(i.expr)}" + (f" AS {i.alias}" if i.alias else "")
            for i in ra.items
        )
        return f"{pad}Project[{items}]\n{ra_to_str(ra.child, indent+1)}"
    return f"{pad}<RA:{ra.__class__.__name__}>"


# ---------- Helpers: expression traversal and name resolution ----------

def walk_expr(e: SQLExpr) -> Iterable[SQLExpr]:
    yield e
    if isinstance(e, Comparison):
        yield from walk_expr(e.left)
        yield from walk_expr(e.right)
    elif isinstance(e, BooleanOp):
        yield from walk_expr(e.left)
        yield from walk_expr(e.right)
    elif isinstance(e, Not):
        yield from walk_expr(e.expr)
    elif isinstance(e, (Column, Literal, AllColumns)):
        return
    else:
        raise UnsupportedFeatureError(f"Unsupported SQL expression node: {type(e).__name__}")

def map_expr(e: SQLExpr, f) -> SQLExpr:
    if isinstance(e, Comparison):
        left = map_expr(e.left, f)
        right = map_expr(e.right, f)
        e2 = Comparison(e.op, left, right)
        return f(e2)
    elif isinstance(e, BooleanOp):
        left = map_expr(e.left, f)
        right = map_expr(e.right, f)
        e2 = BooleanOp(e.op, left, right)
        return f(e2)
    elif isinstance(e, Not):
        child = map_expr(e.expr, f)
        e2 = Not(child)
        return f(e2)
    elif isinstance(e, (Column, Literal, AllColumns)):
        return f(e)
    else:
        raise UnsupportedFeatureError(f"Unsupported SQL expression node: {type(e).__name__}")

class NameResolver:
    """
    Resolves unqualified columns to a unique table alias, validates existence of tables/columns,
    and catches ambiguity. If a catalog is provided, it enables strong column validation.

    catalog shape: {table_name: {col1, col2, ...}}
    """
    def __init__(self, from_tables: List[TableRef], catalog: Optional[Dict[str, Set[str]]] = None, strict: bool = True):
        self.from_tables = from_tables
        self.catalog = catalog
        self.strict = strict
        self.alias_to_table: Dict[str, str] = {}
        self._init_aliases()

    def _alias_key(self, t: TableRef) -> str:
        return t.alias if t.alias else t.name

    def _init_aliases(self) -> None:
        if not self.from_tables:
            raise EmptyFromError("No tables in FROM clause")
        seen: Set[str] = set()
        for t in self.from_tables:
            alias_key = self._alias_key(t)
            if alias_key in seen:
                raise DuplicateAliasError(f"Duplicate table alias/name in FROM: '{alias_key}'")
            seen.add(alias_key)
            self.alias_to_table[alias_key] = t.name

    def check_tables_exist(self) -> None:
        if not self.catalog:
            return
        for tr in self.from_tables:
            if tr.name not in self.catalog:
                raise UnknownTableError(f"Unknown table '{tr.name}'")

    def all_aliases(self) -> List[str]:
        return [self._alias_key(t) for t in self.from_tables]

    def table_columns(self, alias: str) -> Optional[Set[str]]:
        if not self.catalog:
            return None
        table = self.alias_to_table[alias]
        return self.catalog.get(table)

    def resolve_column(self, col: Column) -> Column:
        # If qualified, validate alias and column
        if col.table:
            alias = col.table
            if alias not in self.alias_to_table:
                # Could be a table name referred without alias; allow if matches a base name with no conflicting alias
                # Map table names to alias if unaliased
                names = {t.name for t in self.from_tables}
                if alias in names and alias not in self.alias_to_table:
                    # This path won't occur because _init_aliases always registers the base name when no alias
                    pass
                raise UnknownTableError(f"Unknown table/alias '{alias}' for column '{alias}.{col.name}'")
            cols = self.table_columns(alias)
            if cols is not None and col.name not in cols:
                raise UnknownColumnError(f"Unknown column '{alias}.{col.name}'")
            return Column(name=col.name, table=alias)

        # Unqualified: try to bind to a unique alias where the column exists (if catalog present)
        candidate_aliases: List[str] = []
        if self.catalog:
            for alias in self.all_aliases():
                cols = self.table_columns(alias)
                # If a table is missing in catalog, be conservative: treat as possibly containing the column
                if cols is None or col.name in cols:
                    candidate_aliases.append(alias)
        else:
            # Without catalog, ambiguity arises if more than one table; pick unique only when exactly one table
            if len(self.from_tables) == 1:
                candidate_aliases = [self.all_aliases()[0]]
            else:
                # Ambiguous without qualification
                raise AmbiguousColumnError(f"Ambiguous unqualified column '{col.name}' (multiple tables in scope)")

        # Filter out duplicates and decide
        unique_aliases = list(dict.fromkeys(candidate_aliases))
        if len(unique_aliases) == 0:
            # With catalog we know it's unknown; without catalog this should not occur (handled above)
            raise UnknownColumnError(f"Unknown unqualified column '{col.name}'")
        if len(unique_aliases) > 1:
            raise AmbiguousColumnError(f"Ambiguous unqualified column '{col.name}' (appears in {unique_aliases})")
        return Column(name=col.name, table=unique_aliases[0])

    def resolve_expr(self, e: SQLExpr) -> SQLExpr:
        def resolve(node: SQLExpr) -> SQLExpr:
            if isinstance(node, Column):
                return self.resolve_column(node)
            return node
        return map_expr(e, resolve)

    def resolve_select_list(self, items: List[SelectItem]) -> List[SelectItem]:
        if not items:
            raise EmptySelectListError("Empty SELECT list")
        resolved: List[SelectItem] = []
        for it in items:
            if isinstance(it.expr, AllColumns):
                # Keep as-is; '*' expands during planning/execution; we preserve here
                resolved.append(it)
            else:
                resolved.append(SelectItem(expr=self.resolve_expr(it.expr), alias=it.alias))
        return resolved


# ---------- Translator: multi-table (implicit product), WHERE, projection ----------

def build_from_product(tables: List[TableRef]) -> RAExpr:
    if not tables:
        raise EmptyFromError("No tables in FROM clause")
    ra: RAExpr = RATable(name=tables[0].name, alias=tables[0].alias)
    for tr in tables[1:]:
        ra = RAProduct(left=ra, right=RATable(name=tr.name, alias=tr.alias))
    return ra

def translate_select(stmt: SelectStmt, catalog: Optional[Dict[str, Set[str]]] = None, strict: bool = True) -> RAExpr:
    # 1) Validate FROM and aliases
    resolver = NameResolver(stmt.from_tables, catalog=catalog, strict=strict)
    resolver.check_tables_exist()

    # 2) Name-resolution for WHERE and SELECT list
    where_resolved = resolver.resolve_expr(stmt.where) if stmt.where is not None else None
    select_resolved = resolver.resolve_select_list(stmt.select_list)

    # 3) Build RA: FROM product -> Selection -> Projection
    ra_tree: RAExpr = build_from_product(stmt.from_tables)
    if where_resolved is not None:
        ra_tree = RASelection(predicate=where_resolved, child=ra_tree)

    # If select list is a single '*', we can omit projection
    if len(select_resolved) == 1 and isinstance(select_resolved[0].expr, AllColumns):
        return ra_tree
    else:
        return RAProjection(items=select_resolved, child=ra_tree)


# ---------- Examples: SQL strings (for readability) + expected RA ----------

if __name__ == "__main__":
    # A tiny catalog for validation:
    catalog = {
        "users": {"id", "name", "age", "dept_id"},
        "departments": {"id", "name"},
    }

    # Helper constructors to simulate the pre-parsed SQL AST
    def tbl(name: str, alias: Optional[str] = None) -> TableRef:
        return TableRef(name=name, alias=alias)

    def sel(items: List[SelectItem], froms: List[TableRef], where: Optional[SQLExpr] = None) -> SelectStmt:
        return SelectStmt(select_list=items, from_tables=froms, where=where)

    def col(name: str, table: Optional[str] = None) -> Column:
        return Column(name=name, table=table)

    def cmp(op: str, l: SQLExpr, r: SQLExpr) -> Comparison:
        return Comparison(op, l, r)

    def band(l: SQLExpr, r: SQLExpr) -> BooleanOp:
        return BooleanOp("AND", l, r)

    # 1) Single-table, qualified and unqualified mixed
    # SQL: SELECT id, name FROM users WHERE age > 18
    stmt1 = sel(
        [SelectItem(col("id")), SelectItem(col("name"))],
        [tbl("users")],
        cmp(">", col("age"), Literal(18)),
    )
    ra1 = translate_select(stmt1, catalog=catalog)
    print("-- Example 1 --")
    print("SQL: SELECT id, name FROM users WHERE age > 18")
    print(ra_to_str(ra1))
    # Expected shape:
    # Project[id, name]
    #   Select[(users.age > 18)]
    #     Table(users)

    # 2) Two tables with aliases, qualified columns and join predicate
    # SQL: SELECT u.name, d.name FROM users u, departments d WHERE u.dept_id = d.id
    stmt2 = sel(
        [SelectItem(col("name", "u")), SelectItem(col("name", "d"))],
        [tbl("users", "u"), tbl("departments", "d")],
        cmp("=", col("dept_id", "u"), col("id", "d")),
    )
    ra2 = translate_select(stmt2, catalog=catalog)
    print("\n-- Example 2 --")
    print("SQL: SELECT u.name, d.name FROM users u, departments d WHERE u.dept_id = d.id")
    print(ra_to_str(ra2))
    # Expected shape:
    # Project[u.name, d.name]
    #   Select[(u.dept_id = d.id)]
    #     Product
    #       Table(users AS u)
    #       Table(departments AS d)

    # 3) Ambiguous unqualified column across two tables -> error
    # SQL: SELECT id FROM users u, departments d
    try:
        stmt3 = sel(
            [SelectItem(col("id"))],  # unqualified 'id' exists in both tables
            [tbl("users", "u"), tbl("departments", "d")],
            None,
        )
        translate_select(stmt3, catalog=catalog)
    except TranslationError as e:
        print("\n-- Example 3 --")
        print("SQL: SELECT id FROM users u, departments d")
        print("Error:", e)

    # 4) Unknown column -> error
    # SQL: SELECT users.badcol FROM users
    try:
        stmt4 = sel(
            [SelectItem(col("badcol", "users"))],
            [tbl("users")],
            None,
        )
        translate_select(stmt4, catalog=catalog)
    except TranslationError as e:
        print("\n-- Example 4 --")
        print("SQL: SELECT users.badcol FROM users")
        print("Error:", e)

    # 5) Duplicate alias -> error
    # SQL: SELECT * FROM users u, departments u
    try:
        stmt5 = sel(
            [SelectItem(AllColumns())],
            [tbl("users", "u"), tbl("departments", "u")],
            None,
        )
        translate_select(stmt5, catalog=catalog)
    except TranslationError as e:
        print("\n-- Example 5 --")
        print("SQL: SELECT * FROM users u, departments u")
        print("Error:", e)

    # 6) Unqualified column allowed when single table
    # SQL: SELECT id FROM users WHERE age >= 21
    stmt6 = sel(
        [SelectItem(col("id"))],
        [tbl("users")],
        cmp(">=", col("age"), Literal(21)),
    )
    ra6 = translate_select(stmt6, catalog=catalog)
    print("\n-- Example 6 --")
    print("SQL: SELECT id FROM users WHERE age >= 21")
    print(ra_to_str(ra6))
```

Discussion: common pitfalls and how we handle them

- Ambiguous unqualified columns:
  - Pitfall: col appears in multiple FROM tables; SELECT col or WHERE col = 1 is ambiguous.
  - Handling: AmbiguousColumnError unless column is uniquely attributable (single table or catalog disambiguation).

- Duplicate table aliases or reuse of a base table name as an alias:
  - Pitfall: FROM users u, departments u causes collisions in name resolution.
  - Handling: DuplicateAliasError with a clear message.

- Unknown tables/columns:
  - Pitfall: Typos or missing schema entries.
  - Handling: UnknownTableError and UnknownColumnError when a catalog is provided.

- Missing FROM or empty SELECT list:
  - Pitfall: SELECT without a FROM in this simplified translator, or SELECT with zero items.
  - Handling: EmptyFromError and EmptySelectListError.

- Star expansion (*) and column lists:
  - Pitfall: Deciding when to expand * and how to qualify expanded columns.
  - Handling: We preserve AllColumns in the RA tree; expansion can happen in a later planning phase with access to catalogs and projection schemas.

- Boolean logic preservation:
  - Pitfall: Incorrectly flattening or reordering AND/OR/NOT can change semantics.
  - Handling: We preserve BooleanOp and Not structure exactly as given in the SQL AST.

- Unsupported expressions:
  - Pitfall: Complex functions, aggregates, subqueries not recognized by the toy AST.
  - Handling: UnsupportedFeatureError raised by traversal utilities if an unknown node type appears.

- Name resolution without a catalog:
  - Pitfall: Cannot reliably validate columns; ambiguity increases.
  - Handling: Allow unqualified columns only when exactly one table is present; otherwise raise AmbiguousColumnError. Providing a catalog improves diagnostics and safety.

- Join predicates vs. cross products:
  - Pitfall: Implicit joins (comma FROM) should be represented as a product followed by a selection.
  - Handling: RAProduct builds the cross product; RASelection carries the WHERE predicate above it. This mirrors classic relational algebra normalization and is easy to extend to explicit JOIN nodes later.

