bool GetIndicatorValues(int shift, double &emaFast, double &emaSlow, double &rsi, double &atr)
{
  double bufFast[], bufSlow[], bufRSI[], bufATR[];
  if(CopyBuffer(hFastEMA,0,shift,2,bufFast)<2) { LogLastError("CopyBuffer fast EMA"); return false; }
  if(CopyBuffer(hSlowEMA,0,shift,2,bufSlow)<2) { LogLastError("CopyBuffer slow EMA"); return false; }
  if(CopyBuffer(hRSI,   0,shift,1,bufRSI) <1)  { LogLastError("CopyBuffer RSI"); return false; }
  if(CopyBuffer(hATR,   0,shift,1,bufATR) <1)  { LogLastError("CopyBuffer ATR"); return false; }

  emaFast = bufFast[0];
  emaSlow = bufSlow[0];
  rsi     = bufRSI[0];
  atr     = bufATR[0];
  if(!MathIsValidNumber(emaFast) || !MathIsValidNumber(emaSlow) || !MathIsValidNumber(rsi) || !MathIsValidNumber(atr))
    return false;
  return true;
}

bool IsNewBar(const string sym, ENUM_TIMEFRAMES tf)
{
  static datetime lastTime = 0;
  datetime curTime = iTime(sym, tf, 0);
  if(curTime == 0) return false;
  if(curTime != lastTime)
  {
    lastTime = curTime;
    return true;
  }
  return false;
}

bool IsTradingHourUTC()
{
  datetime now = TimeCurrent();
  MqlDateTime t;
  TimeToStruct(now, t);
  int hour = t.hour;
  if(hour<0 || hour>23) return true;
  if(gSkipHour[hour]) return false;
  return true;
