bool OnePositionPerSymbol()
{
  int total = PositionsTotal();
  for(int i=0;i<total;i++)
  {
    ulong ticket = PositionGetTicket(i);
    if(ticket==0) continue;
    if(PositionSelectByTicket(ticket))
    {
      string sym = PositionGetString(POSITION_SYMBOL);
      ulong mgc  = (ulong)PositionGetInteger(POSITION_MAGIC);
      if(sym==gSymbol && mgc==InpMagicNumber) return true;
    }
  }
  return false;
}

double NormalizeVolume(double vol)
{
  if(gVolStep<=0.0) return vol;
  double steps = MathFloor(vol / gVolStep + 1e-8);
  double v = steps * gVolStep;
  if(v < gMinVolume) v = gMinVolume;
  if(v > gMaxVolume) v = gMaxVolume;
  return NormalizeDouble(v, 2);
}

double PointsToPrice(double points) { return points * gPoint; }

// Calculate position size by risk (equity-based) using ATR stop distance and OrderCalcMargin feasibility
// Returns 0 if cannot size safely.
double CalculateRiskVolume(const bool isBuy, const double entryPrice, const double stopPrice, const double atr, string &why)
{
  why = "";
  double equity = AccountInfoDouble(ACCOUNT_EQUITY);
  double free_margin = AccountInfoDouble(ACCOUNT_FREEMARGIN);
  if(equity<=0 || free_margin<=0) { why="No equity/free margin"; return 0.0; }

  // Risk amount in account currency
  double risk_amount = equity * (InpRiskPerTradePct/100.0);
  if(risk_amount <= 0.0) { why="Risk amount <= 0"; return 0.0; }

  // Pip/point value per 1 lot
  if(gTickValue<=0.0 || gTickSize<=0.0) { why="Invalid tick params"; return 0.0; }

  double stop_distance = MathAbs(entryPrice - stopPrice);
  if(stop_distance <= 0.0) { why="Stop distance <= 0"; return 0.0; }

  // Value per 1 lot for stop distance
  double ticks_per_stop = stop_distance / gTickSize;
  double loss_per_lot = ticks_per_stop * gTickValue;
  if(loss_per_lot <= 0.0) { why="Computed loss_per_lot <= 0"; return 0.0; }

  // Raw lots by risk
  double lots = risk_amount / loss_per_lot;

  // Respect broker constraints
  if(lots < gMinVolume) lots = gMinVolume;
  if(lots > gMaxVolume) lots = gMaxVolume;
  lots = NormalizeVolume(lots);

  if(lots < gMinVolume - 1e-12) { why="Lots below min volume"; return 0.0; }

  // Margin checks and per-trade margin cap against free margin
  double price = entryPrice;
  MqlTradeRequest  r; MqlTradeResult res;
  ZeroMemory(r); ZeroMemory(res);
  r.action   = TRADE_ACTION_DEAL;
  r.symbol   = gSymbol;
  r.type     = isBuy ? ORDER_TYPE_BUY : ORDER_TYPE_SELL;
  r.price    = price;
  r.volume   = lots;
  r.deviation= InpSlippagePoints;
  r.magic    = InpMagicNumber;

  double margin_per_lot=0.0;
  if(!OrderCalcMargin(r.type, gSymbol, 1.0, price, margin_per_lot))
  {
    LogLastError("OrderCalcMargin per-lot failed");
    why="OrderCalcMargin failed";
    return 0.0;
  }
  double margin_needed = margin_per_lot * lots;

  // Cap: single trade margin <= % of free margin
  double margin_cap = free_margin * (InpMaxFreeMarginUsagePct/100.0);
  if(margin_cap > 0 && margin_needed > margin_cap)
  {
    double scale = margin_cap / margin_needed;
    lots = NormalizeVolume(lots * scale);
    if(lots < gMinVolume - 1e-12) { why="Margin cap reduced lots below min"; return 0.0; }
    // Recompute margin_needed
    margin_needed = margin_per_lot * lots;
  }

  // Projected margin level check (approximate)
  // Projected margin = current margin + margin_needed; we use ACCOUNT_MARGIN
  double cur_margin = AccountInfoDouble(ACCOUNT_MARGIN);
  double proj_margin = cur_margin + margin_needed;
  double proj_margin_level = (proj_margin>0.0) ? (equity / proj_margin * 100.0) : DBL_MAX;

  if(InpMinMarginLevelPct > 0.0 && proj_margin_level < InpMinMarginLevelPct)
  {
    why=StringFormat("Projected margin level %.2f%% < min %.2f%%", proj_margin_level, InpMinMarginLevelPct);
    return 0.0;
  }

  // Final free margin feasibility
  double fm_check=0.0;
  if(!OrderCalcMargin(r.type, gSymbol, lots, price, fm_check))
  {
    LogLastError("OrderCalcMargin final failed");
    why="OrderCalcMargin final failed";
    return 0.0;
  }
  if(fm_check > free_margin)
  {
    why="Insufficient free margin for final lots";
    return 0.0;
  }

  return lots;
}

bool WithinSpreadLimit()
{
  MqlTick tick;
  if(!SymbolInfoTick(gSymbol, tick)) { LogLastError("SymbolInfoTick"); return false; }
  double spread_points = (tick.ask - tick.bid) / gPoint;
  if(InpMaxSpreadPoints>0 && spread_points > InpMaxSpreadPoints) return false;
  return true;
}

bool GetEntryPrices(bool isBuy, double &entry, double &sl, double &tp, const double atr)
{
  MqlTick tick;
  if(!SymbolInfoTick(gSymbol, tick)) { LogLastError("SymbolInfoTick"); return false; }

  if(isBuy)
  {
    entry = tick.ask;
    double sl_dist = MathMax(InpATR_SL_Mult * atr, gStopsLevelPoints * gPoint);
    sl = entry - sl_dist;
    double tp_dist = InpRR * (entry - sl);
    tp = entry + tp_dist;
  }
  else
  {
    entry = tick.bid;
    double sl_dist = MathMax(InpATR_SL_Mult * atr, gStopsLevelPoints * gPoint);
    sl = entry + sl_dist;
    double tp_dist = InpRR * (sl - entry);
    tp = entry - tp_dist;
  }

  // Respect freeze/stops levels
  double min_stop_dist = gStopsLevelPoints * gPoint;
  if(min_stop_dist > 0)
  {
    if(isBuy)
    {
      if((entry - sl) < min_stop_dist) sl = entry - min_stop_dist;
      if((tp - entry) < min_stop_dist) tp = entry + min_stop_dist;
    }
    else
    {
      if((sl - entry) < min_stop_dist) sl = entry + min_stop_dist;
      if((entry - tp) < min_stop_dist) tp = entry - min_stop_dist;
    }
  }

  return true;
}

bool SendOrder(bool isBuy, double lots, double entry, double sl, double tp)
{
  MqlTradeRequest  req;
  MqlTradeResult   res;
  ZeroMemory(req);
  ZeroMemory(res);

  req.action     = TRADE_ACTION_DEAL;
  req.symbol     = gSymbol;
  req.magic      = InpMagicNumber;
  req.type       = isBuy ? ORDER_TYPE_BUY : ORDER_TYPE_SELL;
  req.price      = entry;
  req.sl         = sl;
  req.tp         = tp;
  req.volume     = lots;
  req.deviation  = InpSlippagePoints;
  req.type_filling = ORDER_FILLING_FOK;

  bool ok = OrderSend(req, res);
  if(!ok)
  {
    LogLastError("OrderSend failed");
    PrintFormat("OrderSend retcode=%d, deal=%I64u, order=%I64u, comment=%s",
                res.retcode, res.deal, res.order, res.comment);
  }
  else
  {
    if(res.retcode != TRADE_RETCODE_DONE && res.retcode != TRADE_RETCODE_PLACED)
    {
      PrintFormat("OrderSend not done. retcode=%d, comment=%s", res.retcode, res.comment);
      ok=false;
    }
  }
  return ok;
}

// Trailing stop & breakeven management for the single position on this symbol
void ManagePosition(const double atr)
{
  if(!InpAllowTrailing && InpBreakevenRR<=0.0) return;

  if(!PositionSelect(gSymbol)) return;
  if((ulong)PositionGetInteger(POSITION_MAGIC) != InpMagicNumber) return;

  long    type   = PositionGetInteger(POSITION_TYPE);
  double  price  = (type==POSITION_TYPE_BUY) ? SymbolInfoDouble(gSymbol, SYMBOL_BID) : SymbolInfoDouble(gSymbol, SYMBOL_ASK);
  double  entry  = PositionGetDouble(POSITION_PRICE_OPEN);
  double  sl     = PositionGetDouble(POSITION_SL);
  double  tp     = PositionGetDouble(POSITION_TP);
  double  vol    = PositionGetDouble(POSITION_VOLUME);

  if(vol <= 0.0) return;

  double risk_per_unit = MathMax(MathAbs(entry - sl), 1e-8);
  double trail_dist    = MathMax(InpATR_TrailMult * atr, gStopsLevelPoints * gPoint);

  // Breakeven move
  if(InpBreakevenRR > 0.0 && risk_per_unit > 0.0)
  {
    double rr = (type==POSITION_TYPE_BUY) ? (price - entry)/risk_per_unit : (entry - price)/risk_per_unit;
    if(rr >= InpBreakevenRR)
    {
      double newSL = entry;
      if(type==POSITION_TYPE_BUY)
      {
        if(sl < newSL - 0.5*gPoint)
        {
          trade.PositionModify(gSymbol, newSL, tp);
          if(trade.ResultRetcode()!=TRADE_RETCODE_DONE)
            PrintFormat("Breakeven modify failed: %d %s", trade.ResultRetcode(), trade.ResultComment());
        }
      }
      else
      {
        if(sl > newSL + 0.5*gPoint || sl==0.0)
        {
          trade.PositionModify(gSymbol, newSL, tp);
          if(trade.ResultRetcode()!=TRADE_RETCODE_DONE)
            PrintFormat("Breakeven modify failed: %d %s", trade.ResultRetcode(), trade.ResultComment());
        }
      }
    }
  }

  if(!InpAllowTrailing) return;

  // Trailing stop
  if(type==POSITION_TYPE_BUY)
  {
    double trailSL = price - trail_dist;
    // Ensure SL not below entry if already at BE or better
    if(sl < entry && trailSL < entry) trailSL = entry;
    if(trailSL > sl + gPoint) // move only if improves by at least 1 point
    {
      // Respect stops/freeze
      if(gFreezeLevelPoints>0 && (MathAbs((price - trailSL)/gPoint) < gFreezeLevelPoints)) return;
      trade.PositionModify(gSymbol, trailSL, tp);
      if(trade.ResultRetcode()!=TRADE_RETCODE_DONE)
        PrintFormat("Trailing modify failed: %d %s", trade.ResultRetcode(), trade.ResultComment());
    }
  }
  else if(type==POSITION_TYPE_SELL)
  {
    double trailSL = price + trail_dist;
    if(sl > entry && trailSL > entry) trailSL = entry;
    if(sl==0.0 || trailSL < sl - gPoint)
    {
      if(gFreezeLevelPoints>0 && (MathAbs((price - trailSL)/gPoint) < gFreezeLevelPoints)) return;
      trade.PositionModify(gSymbol, trailSL, tp);
      if(trade.ResultRetcode()!=TRADE_RETCODE_DONE)
        PrintFormat("Trailing modify failed: %d %s", trade.ResultRetcode(), trade.ResultComment());
    }
  }
}

enum SignalType { SIG_NONE=0, SIG_BUY=1, SIG_SELL=2 };

SignalType GetSignal(double &atr_out)
{
  double emaF1, emaS1, rsi1, atr1;
  double emaF2, emaS2, rsi2, atr2;

  // Use bar[1] for closed bar signal to avoid repaint; also check bar[2] for cross confirmation
  if(!GetIndicatorValues(1, emaF1, emaS1, rsi1, atr1)) return SIG_NONE;
  if(!GetIndicatorValues(2, emaF2, emaS2, rsi2, atr2)) return SIG_NONE;

  atr_out = atr1;

  if(InpATR_MinFilter>0.0 && atr1 < InpATR_MinFilter) return SIG_NONE;

  bool crossUp   = (emaF2 <= emaS2 && emaF1 > emaS1);
  bool crossDown = (emaF2 >= emaS2 && emaF1 < emaS1);

  if(crossUp && rsi1 >= InpRSI_Buy)   return SIG_BUY;
  if(crossDown && rsi1 <= InpRSI_Sell) return SIG_SELL;

  return SIG_NONE;
}

//------------------------------------------------------------------
// EA events
//------------------------------------------------------------------
int OnInit()
{
  if(!RefreshSymbolInfo(_Symbol))
  {
    Print("Initialization failed: symbol info");
    return INIT_FAILED;
  }

  ParseSkipHours(InpSkipHoursUTC);

  if(!IndicatorCreateAll())
  {
    Print("Initialization failed: indicators");
    return INIT_FAILED;
  }

  trade.SetExpertMagicNumber(InpMagicNumber);

  Print("EA initialized on ", gSymbol,
        " | point=", gPoint,
        " | vol[min,max,step]=", DoubleToString(gMinVolume,2), ",", DoubleToString(gMaxVolume,2), ",", DoubleToString(gVolStep,2));

  return INIT_SUCCEEDED;
}

void OnDeinit(const int reason)
{
  if(hFastEMA!=INVALID_HANDLE) IndicatorRelease(hFastEMA);
  if(hSlowEMA!=INVALID_HANDLE) IndicatorRelease(hSlowEMA);
  if(hRSI    !=INVALID_HANDLE) IndicatorRelease(hRSI);
  if(hATR    !=INVALID_HANDLE) IndicatorRelease(hATR);
}

// Core tick processing
void OnTick()
{
  if(_Symbol != gSymbol)
  {
    if(!RefreshSymbolInfo(_Symbol)) return;
    if(!IndicatorCreateAll()) return;
  }

  // Process trailing on every tick (position-level)
  double atr0=0.0, dummy1, dummy2, dummy3;
  if(hATR!=INVALID_HANDLE)
  {
    double bufATR[];
    if(CopyBuffer(hATR,0,0,1,bufATR)==1) atr0 = bufATR[0];
  }
  ManagePosition(atr0);

  // Only create new signals on new bar to avoid multiple orders
  if(!IsNewBar(gSymbol, InpTimeframe)) return;

  if(!IsTradingHourUTC())
  {
    Print("Skip hour filter active");
    return;
  }

  if(OnePositionPerSymbol())
  {
    Print("Position already open for symbol; one-position-per-symbol enforced");
    return;
  }

  if(!WithinSpreadLimit())
  {
    Print("Spread filter blocks new entries");
    return;
  }

  double atr_for_signal=0.0;
  SignalType sig = GetSignal(atr_for_signal);
  if(sig==SIG_NONE) return;

  // Build entry prices
  bool isBuy = (sig==SIG_BUY);
  double entry=0.0, sl=0.0, tp=0.0;
  if(!GetEntryPrices(isBuy, entry, sl, tp, atr_for_signal))
  {
    Print("Failed to compute entry/SL/TP");
    return;
  }

  // Risk-based sizing with OrderCalcMargin and margin-level checks
  string why="";
  double lots = CalculateRiskVolume(isBuy, entry, sl, atr_for_signal, why);
  if(lots <= 0.0)
  {
    if(why!="") Print("Sizing blocked: ", why);
    return;
  }

  // Final safety checks on freeze/stops levels
  if(gFreezeLevelPoints>0)
  {
    MqlTick t;
    if(SymbolInfoTick(gSymbol, t))
    {
      double ref = isBuy ? t.ask : t.bid;
      double sl_dist_pts = MathAbs((ref - sl)/gPoint);
      if(sl_dist_pts < gFreezeLevelPoints)
      {
        Print("Freeze-level prevents SL set now; aborting entry");
        return;
      }
      double tp_dist_pts = MathAbs((tp - ref)/gPoint);
      if(tp_dist_pts < gFreezeLevelPoints)
      {
        Print("Freeze-level prevents TP set now; aborting entry");
        return;
      }
    }
  }

  // Send order
  if(!SendOrder(isBuy, lots, entry, sl, tp))
  {
    Print("OrderSend failed; entry aborted");
    return;
  }

  PrintFormat("Order sent: %s lots=%.2f entry=%.5f SL=%.5f TP=%.5f",
              isBuy?"BUY":"SELL", lots, entry, sl, tp);
}

